INSERT OR IGNORE INTO verses (id, ref, book, chapter, verse, text, text_normalized, text_html, testament, translation_key, dialect, tags, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(39411, 'Malachi 1:8', 'Malachi', 1, 8, 'کله چې تاسو ړاندۀ څاروى د قربانۍ دپاره راولئ، آيا دا غلط کار نۀ دے؟ کله چې تاسو ګوډ يا بيمار څاروى قربانى کوئ، آيا دا غلط کار نۀ دے څۀ؟ کۀ تاسو دا کوشش وکړئ چې دا خپل حکمران ته پېش کړئ، آيا هغه به تاسو نه خوشحاله شى څۀ؟ آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_008.mp3', NULL, 1761758855, 1761758855),
(39412, 'Malachi 1:9', 'Malachi', 1, 9, '”اوس خُدائ پاک ته سوال زارى کوئ چې په مونږ مهربان شى. ستاسو نه په داسې قربانۍ پېش کولو، آيا هغه به تاسو قبول کړى؟“ مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_009.mp3', NULL, 1761758855, 1761758855),
(39413, 'Malachi 1:10', 'Malachi', 1, 10, '”اے کاش چې په تاسو کښې يو کس د عبادتخانې دروازې بندې کړى، نو چې تاسو نور بې‌فائدې اور زما په قربان‌ګاه بل نۀ کړئ. زۀ تاسو نه خوشحاله نۀ يم،“ مالِک خُدائ ربُ الافواج فرمائى، ”او زۀ به ستاسو د لاسونو نه نذرانې قبولې نۀ کړم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_010.mp3', NULL, 1761758855, 1761758855),
(39414, 'Malachi 1:11', 'Malachi', 1, 11, 'زما نوم به د قومونو په مينځ کښې عظيم وى، د نمر راختو نه تر نمر پرېوتو پورې. په هر ځائ کښې به خوشبودارې او پاکې نذرانې ما ته راوړے شى، ځکه چې زما نوم به د قومونو په مينځ کښې عظيم وى،“ مالِک خُدائ ربُ الافواج فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_011.mp3', NULL, 1761758855, 1761758855),
(39415, 'Malachi 1:12', 'Malachi', 1, 12, '”خو تاسو زما د نوم بې‌حرمتى کوئ په دې وئيلو سره چې د مالِک خُدائ قربان‌ګاه ناپاکه ده، او د دې خوراک بې‌اهميته دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_012.mp3', NULL, 1761758855, 1761758855),
(39416, 'Malachi 1:13', 'Malachi', 1, 13, 'او تاسو وايئ چې، دا څومره بوج دے. او پوکى وهئ او د دې نه نفرت کوئ،“ مالِک خُدائ ربُ الافواج فرمائى. ”کله چې تاسو د غلا، ګوډ يا بيمار څاروى راولئ او د قربانۍ په طور يې پېش کړئ، آيا زۀ دا ستاسو د لاسونو نه قبول کړم څۀ؟“ مالِک خُدائ فرمائى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_013.mp3', NULL, 1761758855, 1761758855),
(39417, 'Malachi 1:14', 'Malachi', 1, 14, '”لعنت دې وى په هغه دوکه باز باندې چې په رمه کښې يې څُرب نر څاروے وى او نذرونه يې منلې وى، خو مالِک ته مات ګوډ څاروے قربانى کړى.“ نو مالِک خُدائ ربُ الافواج فرمائى چې، ”زۀ لوئ بادشاه يم، او په قومونو کښې خلق زما د نوم نه يريږى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/malachi1_verse_014.mp3', NULL, 1761758855, 1761758855),
(39418, 'Job 8:1', 'Job', 8, 1, 'بيا بِلداد شوحى ووئيل،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_001.mp3', NULL, 1761758855, 1761758855),
(39419, 'Job 8:2', 'Job', 8, 2, '”ترڅو پورې به تۀ دا خبرې کوې، او دا بک بک به جارى ساتې؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_002.mp3', NULL, 1761758855, 1761758855),
(39420, 'Job 8:3', 'Job', 8, 3, 'خُدائ پاک د اِنصاف نه نۀ اوړى. او د قادر خُدائ کارونه همېشه په حقه وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_003.mp3', NULL, 1761758855, 1761758855),
(39421, 'Job 8:4', 'Job', 8, 4, 'کۀ ستاسو بچو د هغۀ خِلاف ګناه کړې وى، نو هغوئ ته به د هغې بدله مِلاو شوې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_004.mp3', NULL, 1761758855, 1761758855),
(39422, 'Job 8:5', 'Job', 8, 5, 'کۀ تۀ خُدائ پاک ولټوې او قادر خُدائ ته په دُعا کښې سوال وکړې،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_005.mp3', NULL, 1761758855, 1761758855),
(39423, 'Job 8:6', 'Job', 8, 6, 'کۀ تۀ صفا او صادق يې، نو هغه به په خپله راپاڅى او هغه به تا له خپل صحيح مقام واپس درکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_006.mp3', NULL, 1761758855, 1761758855),
(39424, 'Job 8:7', 'Job', 8, 7, 'اګر چې ستا شروع معمولى شان وه، خو په مستقبل کښې به مالدار شې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_007.mp3', NULL, 1761758855, 1761758855),
(39425, 'Job 8:8', 'Job', 8, 8, 'معلوماتو دپاره مخکښېنو نسلونو نه تپوس وکړه، او د هغوئ چې کومې تجربې دى په هغې غور وکړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_008.mp3', NULL, 1761758855, 1761758855),
(39426, 'Job 8:9', 'Job', 8, 9, 'ځکه چې مونږ پرون پېدا شوى يُو او مونږ ته هيڅ پته نۀ لګى، ځکه چې په زمکه باندې زمونږ وخت د سورى په شان روان دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_009.mp3', NULL, 1761758855, 1761758855),
(39427, 'Job 8:10', 'Job', 8, 10, 'خو پرېږده چې هوښيار مشران درته ښودنه وکړى، او د هغوئ وېنا ته غوږ نيسه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_010.mp3', NULL, 1761758855, 1761758855),
(39428, 'Job 8:11', 'Job', 8, 11, 'چرته چې اوبۀ نۀ وى نو هلته لوخه نۀ را شنه کيږى، دا د اوبو نه بغېر نۀ کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_011.mp3', NULL, 1761758855, 1761758855),
(39429, 'Job 8:12', 'Job', 8, 12, 'او دا لا شنه وى او رېبلے شوې نۀ وى، خو د نورو واښو نه زر وچيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_012.mp3', NULL, 1761758855, 1761758855),
(39430, 'Job 8:13', 'Job', 8, 13, 'نو چې څوک خُدائ پاک هېروى نو د هغوئ هم دغه لار ده، چې څوک د خُدائ نه منکر وى نو د هغوئ اُميد به ختم شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_013.mp3', NULL, 1761758855, 1761758855),
(39431, 'Job 8:14', 'Job', 8, 14, 'د هغوئ ايمان نازک وى، د هغوئ يقين د جولا د جالې په شان وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_014.mp3', NULL, 1761758855, 1761758855),
(39432, 'Job 8:15', 'Job', 8, 15, 'چې څوک په دې جاله يقين کوى نو هغوئ ته به دا جاله ټينګه نۀ شى، کۀ څوک ورپورې ځان وتړى، نو دا به يې برداشت نۀ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_015.mp3', NULL, 1761758855, 1761758855),
(39433, 'Job 8:16', 'Job', 8, 16, 'منکر کسان داسې ښکارى چې په نمر کښې رازرغون وى، او د دې څانګې په باغ کښې خورې ورې وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_016.mp3', NULL, 1761758855, 1761758855),
(39434, 'Job 8:17', 'Job', 8, 17, 'د هغوئ جرړې د کاڼو د ډېرى نه تاويږى، او دا کاڼى کلک نيسى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_017.mp3', NULL, 1761758855, 1761758855),
(39435, 'Job 8:18', 'Job', 8, 18, 'خو کۀ هغوئ د خپل ځائ نه لرې کړے شى، نو بيا به هغوئ اِنکار وکړى او وائى به چې ما تاسو کله هم نۀ يې ليدلے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_018.mp3', NULL, 1761758855, 1761758855),
(39436, 'Job 8:19', 'Job', 8, 19, 'ګوره، د هغوئ خوشحالى به د لږ وخت دپاره وى، خو نور بوټى راشنۀ شى او د دې ځائ ونيسى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_019.mp3', NULL, 1761758855, 1761758855),
(39437, 'Job 8:20', 'Job', 8, 20, 'ګوره، خُدائ پاک به يو بې‌داغه کس نۀ رد کوى، او نۀ به د بدعمله خلقو مدد وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_020.mp3', NULL, 1761758855, 1761758855),
(39438, 'Job 8:21', 'Job', 8, 21, 'هغه به بيا هم تاسو له خوشحالى درکړى، او ستاسو خولې به د خندا نۀ ډکې کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_021.mp3', NULL, 1761758855, 1761758855),
(39439, 'Job 8:22', 'Job', 8, 22, 'چې څوک ستا نه نفرت کوى نو هغوئ به په شرمونو وشرميږى، او د بدکارانو کور به تباه شى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job8_verse_022.mp3', NULL, 1761758855, 1761758855),
(39440, 'Ezekiel 32:1', 'Ezekiel', 32, 1, 'زمونږ د جلاوطنۍ د دولسم کال د دولسمې میاشتې په لومړۍ ورځ څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_001.mp3', NULL, 1761758855, 1761758855),
(39441, 'Ezekiel 32:2', 'Ezekiel', 32, 2, '«ای فاني انسانه، د مصر د پاچا فرعون دپاره د وېر سندره ووایه. هغه ته زما له خوا دا پیغام ورسوه: ‹نورو قومونو منځ کې ګڼې خپل ځان لکه زمري په شان خو په رښتیا یې د بحیرې د بلا په شان ته اوبه شړپوې خپلو سیندونو کې ته اوبه خړوې په خپلو پښو باندې او چټلوې سیندونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_002.mp3', NULL, 1761758855, 1761758855),
(39442, 'Ezekiel 32:3', 'Ezekiel', 32, 3, 'څښتن تعالی داسې وایي: زه به په تا باندې خپل جال کړم خپور د ډېرو قومونو په مرسته به دې غاړې ته راکاږم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_003.mp3', NULL, 1761758855, 1761758855),
(39443, 'Ezekiel 32:4', 'Ezekiel', 32, 4, 'تا به وغورځوم ځمکه باندې تا به ګوزار کړم په میدان باندې زه به راوړم ټول مرغان د نړۍ چې کښېني تا باندې حیوانات به راوغواړم زه چې ماړه شي په تا باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_004.mp3', NULL, 1761758855, 1761758855),
(39444, 'Ezekiel 32:5', 'Ezekiel', 32, 5, 'زه به په غرونو کې خپره کړمه ستا غوښه زه به ډکې کړم درې ستا په هډوکو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_005.mp3', NULL, 1761758855, 1761758855),
(39445, 'Ezekiel 32:6', 'Ezekiel', 32, 6, 'تر غرونو پورې به لمده کړم ځمکه ستا په وینو باندې شي به ډکې درې ورباندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_006.mp3', NULL, 1761758855, 1761758855),
(39446, 'Ezekiel 32:7', 'Ezekiel', 32, 7, 'کله چې مړه کړم ستا د ژوند شمع زه به پټ کړم اسمانونه پټ به کړم ستوري په تیاره کې لمر به پټ کړمه په ورېځو کې سپوږمۍ به نه کوي رڼا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_007.mp3', NULL, 1761758855, 1761758855),
(39447, 'Ezekiel 32:8', 'Ezekiel', 32, 8, 'زه به ټولې رڼاګانې د اسمان کړم تیاره راولم به ستا وطن باندې تیاره ما څښتن تعالی داسې ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_008.mp3', NULL, 1761758855, 1761758855),
(39448, 'Ezekiel 32:9', 'Ezekiel', 32, 9, 'کله چې زه ستاسو د بربادۍ خبر په هغو وطنونو کې چې تاسو یې نه پېژنئ، خپور کړم، نو د ډېرو قومونو د خلکو زړونه به خفه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_009.mp3', NULL, 1761758855, 1761758855),
(39449, 'Ezekiel 32:10', 'Ezekiel', 32, 10, 'کوم کار چې زه به یې ستا سره کوم په هغه باندې به ډېر قومونه ولړزیږي. کله چې زه خپله توره وخوځوم، نو پاچاهان به له وېرې ورپیږي. په کومه ورځ چې ته سقوط وکړې، نو هغوی ټول به د خپل ژوند په خاطر له وېرې لړزیږي.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_010.mp3', NULL, 1761758855, 1761758855),
(39450, 'Ezekiel 32:11', 'Ezekiel', 32, 11, 'څښتن تعالی د مصر پاچا ته داسې وایي: ‹ته به د بابل پاچا د تورې سره مخامخ شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_011.mp3', NULL, 1761758855, 1761758855),
(39451, 'Ezekiel 32:12', 'Ezekiel', 32, 12, 'زه به د ډېر ظالم قوم غښتلي عسکر ولېږم چې په تا باندې حمله وکړي. بيا به ستا ډېر خلک په جنګ کې ووژل شي. له منځه به یوسي هغوی غرور د مصر له منځه به لاړ شي ټول خلک د مصر', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_012.mp3', NULL, 1761758855, 1761758855),
(39452, 'Ezekiel 32:13', 'Ezekiel', 32, 13, 'زه به حلالې کړم ستا ټولې پادې چې څریږي د ویالو په غاړه هلته به نه وي نور انسان یا حیوان چې کړي چټلې اوبه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_013.mp3', NULL, 1761758855, 1761758855),
(39453, 'Ezekiel 32:14', 'Ezekiel', 32, 14, 'هو، زه به کړم صافې ستا اوبه ستا سیندونه به روان کړم ارام ما څښتن تعالی داسې ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_014.mp3', NULL, 1761758855, 1761758855),
(39454, 'Ezekiel 32:15', 'Ezekiel', 32, 15, 'کله چې زه کړم مصر وران او ویجاړ او ټولو شیانو نه یې کړمه خالي کله چې ووژنم ټول اوسېدونکي یې نو شي به پوه هغوی چې زه څښتن یم›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_015.mp3', NULL, 1761758855, 1761758855),
(39455, 'Ezekiel 32:16', 'Ezekiel', 32, 16, 'پورته سندره به د ویر د یوې سندرې په توګه وویلی شي. د ټولو قومونو ښځې به د ویر دا سندره په مصر او د هغه په ټولو اوسېدونکو باندې د ویر کولو په وخت کې ووایي. ما څښتن تعالی داسې ویلي دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_016.mp3', NULL, 1761758855, 1761758855),
(39456, 'Ezekiel 32:17', 'Ezekiel', 32, 17, 'زمونږ د جلاوطنۍ د دولسم کال د دولسمې میاشتې په پنځلسمه ورځ څښتن ماته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_017.mp3', NULL, 1761758855, 1761758855),
(39457, 'Ezekiel 32:18', 'Ezekiel', 32, 18, '«ای فاني انسانه، د مصر د ټولو خلکو په خاطر ویر وکړه. هغوی د دنیا د نورو قوي قومونو سره د ځمکې لاندې د مړو دنیا ته ولېږه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_018.mp3', NULL, 1761758855, 1761758855),
(39458, 'Ezekiel 32:19', 'Ezekiel', 32, 19, 'هغوی ته ووایه: ‹تاسو فکر کوئ چې زیات ښایسته یئ د نورو څخه؟ تاسو به لاړ شئ د مړو دنیا ته یئ به پراته بې دینه خلکو سره›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_019.mp3', NULL, 1761758855, 1761758855),
(39459, 'Ezekiel 32:20', 'Ezekiel', 32, 20, 'د مصر خلک به د هغو خلکو په شان له منځه لاړ شي چې په جنګ کې وژل شوي دي. د هغوی د ټولو د وژلو دپاره توره تیاره ده. د مصر ډېر خلک به د وژنې دپاره بوتلل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_020.mp3', NULL, 1761758855, 1761758855),
(39460, 'Ezekiel 32:21', 'Ezekiel', 32, 21, 'غښتلي جنګیالي به د مړو له دنیا څخه د مصریانو او د هغوی د ملاتړو په اړه ووایي: ‹هغه بې‌دینه خلک چې په جنګ کې وژل شوي دي، هغوی راغلي دي او دلته پراته دي!›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_021.mp3', NULL, 1761758855, 1761758855),
(39461, 'Ezekiel 32:22', 'Ezekiel', 32, 22, 'آشور هلته دی او شاوخوا ته یې د خپلو هغو عسکرو قبرونه دي چې په جنګ کې وژل شوي دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_022.mp3', NULL, 1761758855, 1761758855),
(39462, 'Ezekiel 32:23', 'Ezekiel', 32, 23, 'او د هغوی قبرونه د مړو د دنیا په ډېره ژوره کنده کې پراته دي. د هغه ټول عسکر په جنګ کې وژل شوي دي او د هغوی قبرونه د ده د قبر شاوخوا پراته دي. کله چې هغوی ژوندي وو، نو هغوی به خلک سخت وېرول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_023.mp3', NULL, 1761758855, 1761758855),
(39463, 'Ezekiel 32:24', 'Ezekiel', 32, 24, 'عیلام هم هلته دی او د هغه ټول عسکر د هغه د قبر شاوخوا پراته دي. هغوی ټول په جنګ کې وژل شوي وو او د مړو دنیا ته بې‌دینه لاړل. کله چې هغوی ژوندي وو، نو هغوی به نور قومونه سخت وېرول، خو اوس هغوی د هغو خلکو په شان چې د هغوی څخه مخکې مړه شوي وو، مړه او شرمېدلي پراته دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_024.mp3', NULL, 1761758855, 1761758855),
(39464, 'Ezekiel 32:25', 'Ezekiel', 32, 25, 'عیلام د هغو خلکو په منځ کې پروت دی چې په جنګ کې وژل شوي دي او شاوخوا ته یې د خپلو عسکرو قبرونه دي. هغوی ټول بې‌دینه وو او په جنګ کې وژل شوي وو. کله چې هغوی ژوندي وو، نو هغوی به په خلکو کې وېره خپروله، خو اوس هغوی مړه او شرمېدلي پراته دي او د هغو خلکو په سرنوشت باندې اخته دي چې په جنګ کې وژل شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_025.mp3', NULL, 1761758855, 1761758855),
(39465, 'Ezekiel 32:26', 'Ezekiel', 32, 26, 'د ماشک او توبال د عسکرو قبرونه هم هلته دي. هغوی ټول بې‌دینه وو او په جنګ کې وژل شوي وو، ځکه کله چې هغوی ژوندي وو، نو هغوی به خلک سخت وېرول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_026.mp3', NULL, 1761758855, 1761758855),
(39466, 'Ezekiel 32:27', 'Ezekiel', 32, 27, 'هغوی د پخوا زمانې د جنګیالیو په شان په قدر او عزت نه وو ښخ شوي. هغه جنګیالي د خپلو وسلو سره د مړو دنیا ته لاړل. د هغوی تورې د هغوی د سرونو لاندې ایښې وې او سپرونه یې په مړو باندې پراته وو. کله چې دا جنګیالي ژوندي وو، نو هغوی به خلک سخت وېرول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_027.mp3', NULL, 1761758855, 1761758855),
(39467, 'Ezekiel 32:28', 'Ezekiel', 32, 28, 'نو تاسو مصریان به د هغو بې‌دینه خلکو په منځ کې ټوټې ټوټې پراته یئ، کوم چې په جنګ کې وژل شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_028.mp3', NULL, 1761758855, 1761758855),
(39468, 'Ezekiel 32:29', 'Ezekiel', 32, 29, 'د ادوم د پاچاهانو او نورو ټولو واکمنانو قبرونه هم هلته دي. هغوی قوي عسکر وو، خو اوس هغوی د هغو بې‌دینه خلکو سره چې په جنګ کې وژل شوي وو، د مړو په دنیا کې پراته دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_029.mp3', NULL, 1761758855, 1761758855),
(39469, 'Ezekiel 32:30', 'Ezekiel', 32, 30, 'د شمال د ټولو مشرانو او د صیدونیانو قبرونه هم هلته دي. د هغوی زور به په یو وخت کې د خلکو د سختې وېرې سبب کېده، خو اوس هغوی په شرم او رسوایۍ سره د هغو خلکو سره چې په جنګ کې وژل شوي دي، د مړو دنیا ته لاړل او بې‌دینه پراته دي. هغوی د هغو خلکو سره په شرم او رسوایۍ کې شریک شول چې د مړو دنیا ته تللي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_030.mp3', NULL, 1761758855, 1761758855),
(39470, 'Ezekiel 32:31', 'Ezekiel', 32, 31, 'څښتن تعالی داسې وایي: ‹کله چې فرعون او د هغه لښکر هغوی وویني، نو هغوی ته به دا تسلي راپیدا شي چې یوازې د هغوی عسکر نه دي وژل شوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_031.mp3', NULL, 1761758855, 1761758855),
(39471, 'Ezekiel 32:32', 'Ezekiel', 32, 32, 'ما په فرعون باندې خلک وېرول، خو هغه او د هغه ټولې لښکرې به ووژل شي او د هغو نورو ټولو بې‌دینه خلکو سره به ښخ شي چې په جنګ کې وژل شوي دي.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel32_verse_032.mp3', NULL, 1761758855, 1761758855),
(39472, 'Deuteronomy 5:1', 'Deuteronomy', 5, 1, 'موسی د اسراییلو ټول قوم راوغوښت او ورته ویې ویل: «ای د اسراییلو خلکو، هغو ټولو قوانینو ته غوږ ونیسئ چې زه یې نن تاسو ته درکوم. هغه زده کړئ او په غور سره د هغو څخه پیروي وکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_001.mp3', NULL, 1761758855, 1761758855),
(39473, 'Deuteronomy 5:4', 'Deuteronomy', 5, 4, 'څښتن په هماغه غره باندې د اور د منځ څخه ستاسو سره مخامخ خبرې وکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_004.mp3', NULL, 1761758855, 1761758855),
(39474, 'Deuteronomy 5:5', 'Deuteronomy', 5, 5, 'په هغه وخت کې زه ستاسو او څښتن ترمنځ ودرېدم چې د هغه خبرې تاسو ته ورسوم، ځکه چې تاسو د هغه اور څخه وېرېدلئ او غره ته نه ورختلئ. څښتن وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_005.mp3', NULL, 1761758855, 1761758855),
(39475, 'Deuteronomy 5:6', 'Deuteronomy', 5, 6, '‹زه ستاسو څښتن خدای یم چې تاسو مې د مصر څخه چې په کې غلامان وئ راوویستلئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_006.mp3', NULL, 1761758855, 1761758855),
(39476, 'Deuteronomy 5:7', 'Deuteronomy', 5, 7, 'زما څخه پرته د بل خدای عبادت مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_007.mp3', NULL, 1761758855, 1761758855),
(39477, 'Deuteronomy 5:8', 'Deuteronomy', 5, 8, 'د خپلو ځانونو دپاره د هېڅ شي په شکل چې هغه په اسمان کې یا په ځمکه باندې یا د ځمکې لاندې په اوبو کې وي، بتان مه جوړوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_008.mp3', NULL, 1761758855, 1761758855),
(39478, 'Deuteronomy 5:9', 'Deuteronomy', 5, 9, 'هېڅ بت ته سجده یا عبادت مه کوئ، ځکه چې زه ستاسو څښتن خدای یو غیرتي خدای یم. څوک چې زما څخه کرکه کوي، زه به هغوی او د هغوی اولادې ته تر درېم او څلورم نسله پورې سزا ورکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_009.mp3', NULL, 1761758855, 1761758855),
(39479, 'Deuteronomy 5:10', 'Deuteronomy', 5, 10, 'خو زه د هغو زرګونو نسلونو سره چې زما سره مینه کوي او زما حکمونو ته غاړه ږدي، مینه کوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_010.mp3', NULL, 1761758855, 1761758855),
(39480, 'Deuteronomy 5:11', 'Deuteronomy', 5, 11, 'زما نوم د بدو مقصدونو دپاره مه کاروئ، ځکه چې زه ستاسو څښتن خدای به هغه چاته سزا ورکړم چې زما نوم په غلطه وکاروي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_011.mp3', NULL, 1761758855, 1761758855),
(39481, 'Deuteronomy 5:12', 'Deuteronomy', 5, 12, 'لکه څنګه چې ما یعنې ستاسو څښتن خدای په تاسو باندې امر کړی دی، د سبت ورځ ولمانځئ او هغه سپېڅلې وګڼئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_012.mp3', NULL, 1761758855, 1761758855),
(39482, 'Deuteronomy 5:13', 'Deuteronomy', 5, 13, 'تاسو د کار کولو دپاره شپږ ورځې لرئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_013.mp3', NULL, 1761758855, 1761758855),
(39483, 'Deuteronomy 5:14', 'Deuteronomy', 5, 14, 'خو اوومه ورځ د ارام کولو ورځ ده چې څښتن خدای ته وقف شوې ده. په دې ورځ به تاسو هېڅ کار نه کوئ، نه تاسو، نه ستاسو زامن یا لورګانې، نه غلامان، نه ستاسو غویان یا خره یا نور حیوانات او نه هغه پردي خلک چې ستاسو په وطن کې اوسیږي. ستاسو غلامان باید ستاسو په شان استراحت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_014.mp3', NULL, 1761758855, 1761758855),
(39484, 'Deuteronomy 5:15', 'Deuteronomy', 5, 15, 'دا په یاد ولرئ چې تاسو په مصر کې غلامان وئ او ما یعنې ستاسو څښتن خدای په خپل قوي مټ او ټول قدرت سره ازاد کړئ. نو ځکه تاسو ته حکم کوم چې د سبت یعنې د ارام کولو ورځ لمانځئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_015.mp3', NULL, 1761758855, 1761758855),
(39485, 'Deuteronomy 5:16', 'Deuteronomy', 5, 16, 'لکه څنګه چې زه یعنې ستاسو څښتن خدای تاسو ته حکم کوم چې د خپل مور او پلار عزت کوئ، ترڅو نېکمرغه اوسئ او په هغه خاوره کې چې زه یې درکوم زیات عمر ولرئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_016.mp3', NULL, 1761758855, 1761758855),
(39486, 'Deuteronomy 5:17', 'Deuteronomy', 5, 17, 'قتل مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_017.mp3', NULL, 1761758855, 1761758855),
(39487, 'Deuteronomy 5:18', 'Deuteronomy', 5, 18, 'زنا مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_018.mp3', NULL, 1761758855, 1761758855),
(39488, 'Deuteronomy 5:19', 'Deuteronomy', 5, 19, 'غلا مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_019.mp3', NULL, 1761758855, 1761758855),
(39489, 'Deuteronomy 5:20', 'Deuteronomy', 5, 20, 'د هېچا په خلاف د دروغو شاهدي مه ورکوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_020.mp3', NULL, 1761758855, 1761758855),
(39490, 'Deuteronomy 5:21', 'Deuteronomy', 5, 21, 'د بل سړي ښځې ته د تمې په سترګه مه ګورئ. د هغه کور، ځمکې، غلامانو، غویانو، خرو یا هرڅه چې هغه یې لري، ورته تمه مه کوئ.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_021.mp3', NULL, 1761758855, 1761758855),
(39491, 'Deuteronomy 5:22', 'Deuteronomy', 5, 22, 'دا هغه حکمونه دي چې څښتن په هغه وخت کې تاسو ټولو ته درکړل کله چې د سینا د غره تر څنګ راټول شوي وئ او هغه په لوړ اواز سره د اور او تورې ورېځې د منځ څخه خبرې وکړې. هغه نور څه نه بلکې همدا حکمونه راکړل. بیا یې هغه د تیږو په دوو لوحو باندې ولیکل او ماته یې راکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_022.mp3', NULL, 1761758855, 1761758855),
(39492, 'Deuteronomy 5:23', 'Deuteronomy', 5, 23, 'کله چې ټول غره اور واخیست او تاسو هغه غږ واورېد چې د تیارې څخه راتله، نو ستاسو مشران او ستاسو د قبیلو مشران ماته راغلل', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_023.mp3', NULL, 1761758855, 1761758855),
(39493, 'Deuteronomy 5:24', 'Deuteronomy', 5, 24, 'او ویې ویل: ‹کله چې مونږ د هغه خبرې واورېدلې چې د اور د منځ څخه یې کولې، مونږ ته خپل څښتن خدای خپله لویي او جلال راوښود! نن مونږ ولیدل چې د یو انسان دپاره که خدای ورسره خبرې هم کړې وي، دا ممکنه ده چې ژوندی پاتې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_024.mp3', NULL, 1761758855, 1761758855),
(39494, 'Deuteronomy 5:25', 'Deuteronomy', 5, 25, 'خو مونږ ولې خپل ځانونه د مرګ په خطر کې واچوو؟ هغه هیبتناکه اور به مونږ له منځه یوسي. مونږ یقین لرو که چېرې د خپل څښتن خدای غږ بیا واورو، نو مړه به شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_025.mp3', NULL, 1761758855, 1761758855),
(39495, 'Deuteronomy 5:26', 'Deuteronomy', 5, 26, 'ایا داسې یو انسان چې د اور د منځ څخه یې د ژوندي خدای خبرې اورېدلې وي، کله ژوندی پاتې شوی دی؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_026.mp3', NULL, 1761758855, 1761758855),
(39496, 'Deuteronomy 5:27', 'Deuteronomy', 5, 27, 'نو موسی، نژدې ورشه او زمونږ د څښتن خدای ټولو خبرو ته غوږ ونیسه. بیا بېرته راشه او هغه خبرې چې هغه درته وکړلې مونږ ته یې ووایه. مونږ به ورته غوږ ونیسو او وبه یې منو.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_027.mp3', NULL, 1761758855, 1761758855),
(39497, 'Deuteronomy 5:28', 'Deuteronomy', 5, 28, 'کله چې څښتن دا خبرې واورېدلې، هغه ماته وویل: ‹ما د دغو خلکو خبرې واورېدلې، هغوی رښتیا وایي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_028.mp3', NULL, 1761758855, 1761758855),
(39498, 'Deuteronomy 5:29', 'Deuteronomy', 5, 29, 'کاشکې هغوی تل داسې احساس ولري! کاشکې هغوی تل زما څخه ووېریږي او زما ټولو حکمونو ته غاړه کېږدي، ترڅو د تل دپاره د هغوی او د هغوی د اولادې هر کار سم وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_029.mp3', NULL, 1761758855, 1761758855),
(39499, 'Deuteronomy 5:30', 'Deuteronomy', 5, 30, 'لاړ شه او هغوی ته ووایه چې بېرته خپلو خېمو ته ورستانه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_030.mp3', NULL, 1761758855, 1761758855),
(39500, 'Deuteronomy 5:31', 'Deuteronomy', 5, 31, 'خو موسی، ته دلته زما سره پاتې شه. زه به تاته خپل ټول قوانین او حکمونه درکړم. هغه قوم ته ورزده کړه، ترڅو هغوی په هغه خاوره کې ورته غاړه کېږدي چې زه یې ورکوم.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_031.mp3', NULL, 1761758855, 1761758855),
(39501, 'Deuteronomy 5:32', 'Deuteronomy', 5, 32, 'د اسراییلو خلکو، تاسو باید په غور سره د خپل څښتن خدای هر حکم په ځای کړئ. د هغه د هېڅ یو قانون څخه سرغړونه ونه کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_032.mp3', NULL, 1761758855, 1761758855),
(39502, 'Deuteronomy 5:33', 'Deuteronomy', 5, 33, 'د هغو ټولو څخه پیروي وکړئ، ترڅو ستاسو ټول کارونه سم روان وي او په هغه وطن کې چې تاسو به یې ونیسئ، خپل ژوند ته دوام ورکړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/deuteronomy5_verse_033.mp3', NULL, 1761758855, 1761758855),
(39503, 'Psalms 7:1', 'Psalms', 7, 1, 'ای څښتنه، زما خدایه، ما پناه راوړې تاته وژغوره ما خلاص کړه د دوی ټولو راپسې چې دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_001.mp3', NULL, 1761758855, 1761758855),
(39504, 'Psalms 7:2', 'Psalms', 7, 2, 'هسې نه چې د زمریو په شان مې بوځي هغه ځای ته چې مې څوک د خلاصون نه وي ما به کړي ټوټې ټوټې په هغه ځای کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_002.mp3', NULL, 1761758855, 1761758855),
(39505, 'Psalms 7:5', 'Psalms', 7, 5, 'نو بیا پرېږده دښمنان مې راپسې شي او ما ګېر کړي کړي پایمال مې او ما مړ کړي هم عزت زما له خاورو سره خاورې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_005.mp3', NULL, 1761758855, 1761758855),
(39506, 'Psalms 7:6', 'Psalms', 7, 6, 'په خپل قهر کې راپورته شه څښتنه! زما د دښمنانو د غضب په وړاندې شه راپورته نو اوس راویښ شه ته زما دپاره برقرار کړه عدالت چې ته یې غواړې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_006.mp3', NULL, 1761758855, 1761758855),
(39507, 'Psalms 7:7', 'Psalms', 7, 7, 'ټول قومونه دې خپل ځان باندې راټول کړه حکومت وکړه په هغو له اسمانه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_007.mp3', NULL, 1761758855, 1761758855),
(39508, 'Psalms 7:8', 'Psalms', 7, 8, 'ته قاضي یې د ټولو قومونو زما حق کې قضاوت وکړه څښتنه ته پوهېږې چې صادق او بې‌ګناه یم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_008.mp3', NULL, 1761758855, 1761758855),
(39509, 'Psalms 7:9', 'Psalms', 7, 9, 'خدایه ته عادل یې عدالت کې ته ازمایې زړه او فکر د هرچا د بدکارو د بدیو مخه نیسه اجر ورکړه هغه چاته چې نېکان دي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_009.mp3', NULL, 1761758855, 1761758855),
(39510, 'Psalms 7:10', 'Psalms', 7, 10, 'خدای دی سپر زما هم ژغورونکی د هغو دی چې په زړونو کې صادق وي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_010.mp3', NULL, 1761758855, 1761758855),
(39511, 'Psalms 7:11', 'Psalms', 7, 11, 'خدای دی عادل قاضي بدکاران هره ورځ غندي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_011.mp3', NULL, 1761758855, 1761758855),
(39512, 'Psalms 7:12', 'Psalms', 7, 12, 'که دوی نه کړلې بدلې خپلې لارې خدای به تېره کړي ورته خپله توره هغه کشوي او تیاروي ورته لینده خپله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_012.mp3', NULL, 1761758855, 1761758855),
(39513, 'Psalms 7:13', 'Psalms', 7, 13, 'کړي به وژونکې وسله ورته تیاره جوړوي ورته هم غشي سوځوونکي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_013.mp3', NULL, 1761758855, 1761758855),
(39514, 'Psalms 7:14', 'Psalms', 7, 14, 'ګورئ څنګه کوي فکر د بدۍ دا بدکاران جوړوي د ځورولو پلانونه دروغ وایي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_014.mp3', NULL, 1761758855, 1761758855),
(39515, 'Psalms 7:15', 'Psalms', 7, 15, 'نورو خلکو ته چې دوی کیندي څاګانې شي به په خپله ورګوزار په کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_015.mp3', NULL, 1761758855, 1761758855),
(39516, 'Psalms 7:16', 'Psalms', 7, 16, 'ومومي سزا د خپلو بدو به هغه ظلمونه به یې انبار شي په خپل سر باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_016.mp3', NULL, 1761758855, 1761758855),
(39517, 'Psalms 7:17', 'Psalms', 7, 17, 'شکر به وکړم له څښتنه د انصاف دپاره څښتن تعالی ته به ثنا وایمه په سندرو سره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms7_verse_017.mp3', NULL, 1761758855, 1761758855),
(39518, 'Psalms 96:1', 'Psalms', 96, 1, 'څښتن ته ووایئ یوه نوې سندره ای ټولې نړۍ، سندره ووایئ څښتن ته تاسې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_001.mp3', NULL, 1761758855, 1761758855),
(39519, 'Psalms 96:2', 'Psalms', 96, 2, 'څښتن ته ووایئ سندره او ستاینه یې د نوم وکړئ اعلان کړئ هره ورځ دا زېری چې نجات یې دی راکړی مونږ ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_002.mp3', NULL, 1761758855, 1761758855),
(39520, 'Psalms 96:3', 'Psalms', 96, 3, 'قومونو ته اعلان کړئ جلال د هغه ټولو خلکو ته اعلان کړئ د هغه ډېر عجیبه کارونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_003.mp3', NULL, 1761758855, 1761758855),
(39521, 'Psalms 96:4', 'Psalms', 96, 4, 'ځکه چې لوی دی څښتن او ډېر لایق دی د ثنا او صفت ټولو خدایانو نه دې زیاته وېره وشي د ده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_004.mp3', NULL, 1761758855, 1761758855),
(39522, 'Psalms 96:5', 'Psalms', 96, 5, 'نورو قومونو ټول خدایان دي بې‌ګټې بتان خو څښتن دي پیدا کړي اسمانونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_005.mp3', NULL, 1761758855, 1761758855),
(39523, 'Psalms 96:6', 'Psalms', 96, 6, 'دی راچاپېره جلال او لویي له هغه څخه سپېڅلی کور د هغه ډک دی له قوت او ښایست', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_006.mp3', NULL, 1761758855, 1761758855),
(39524, 'Psalms 96:7', 'Psalms', 96, 7, 'وکړئ ستاینه د څښتن په ځمکه ټولو خلکو هم ستاینه وکړئ د هغه د جلال او قدرت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_007.mp3', NULL, 1761758855, 1761758855),
(39525, 'Psalms 96:8', 'Psalms', 96, 8, 'د څښتن د جلالي نوم ستاینه وکړئ د هغه دربار ته راشئ او نذرانه راوړئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_008.mp3', NULL, 1761758855, 1761758855),
(39526, 'Psalms 96:9', 'Psalms', 96, 9, 'کړئ څښتن ته عبادت په سپېڅلې توګه ای ټولې ځمکې ولړزېږه د هغه په مخکې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_009.mp3', NULL, 1761758855, 1761758855),
(39527, 'Psalms 96:10', 'Psalms', 96, 10, 'تاسو خبر کړئ ټول قومونه د نړۍ چې دی څښتن پاچا! نړۍ یې ټینګه درولې چې خوځیږي نه او قضاوت به د قومونو کړي انصاف باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_010.mp3', NULL, 1761758855, 1761758855),
(39528, 'Psalms 96:11', 'Psalms', 96, 11, 'پرېږده خوشحاله اسمانونه شي او ځمکه وکړي خوښي شي دریاب په غړمبار دې خپلو ټولو مخلوقاتو سره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_011.mp3', NULL, 1761758855, 1761758855),
(39529, 'Psalms 96:12', 'Psalms', 96, 12, 'شي دې خوشحاله پټي هم ټولو فصلونو سره د ځنګل ټولې ونې به بیا ووهي د خوشحالۍ چیغې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_012.mp3', NULL, 1761758855, 1761758855),
(39530, 'Psalms 96:13', 'Psalms', 96, 13, 'کله چې راشي د ځمکې قضاوت ته څښتن نو په انصاف سره به وکړي قضاوت د نړۍ او قضاوت د ولسونو عدالت باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms96_verse_013.mp3', NULL, 1761758855, 1761758855),
(39531, 'Job 39:1', 'Job', 39, 1, 'تا ته پته شته چې کله د غرۀ چېلۍ بچى راوړى؟ ولې تۀ پرې نظر ساتې چې کله هوسۍ بچى راوړى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_001.mp3', NULL, 1761758855, 1761758855),
(39532, 'Job 39:2', 'Job', 39, 2, 'ولې تا ته پته شته چې دا بچى څو مياشتې د هغوئ په ګېډه وى؟ او تا ته د هغه وخت پته شته څۀ چې دا به کله پېدا شى', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_002.mp3', NULL, 1761758855, 1761758855),
(39533, 'Job 39:3', 'Job', 39, 3, 'کله چې هغوئ د اولاد د پېدا کېدو دپاره کښېنى، او د هغوئ بچى پېدا شى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_003.mp3', NULL, 1761758855, 1761758855),
(39534, 'Job 39:4', 'Job', 39, 4, 'د هغوئ بچى تکړه شى او په ځنګل کښې لوئيږى، هغوئ ترې نه لاړ شى او واپس ورله نۀ راځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_004.mp3', NULL, 1761758855, 1761758855),
(39535, 'Job 39:5', 'Job', 39, 5, 'ځنګلى خرونه چا پرېښې دى چې خوشى لاړ شى؟ دا چا آزاد پرېښى دى چې ګرځى راګرځى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_005.mp3', NULL, 1761758855, 1761758855),
(39536, 'Job 39:6', 'Job', 39, 6, 'ما دا په صحرا کښې پرېښى دى، او د مالګې مُلک مې ورکړے دے چې په کښې اوسيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_006.mp3', NULL, 1761758855, 1761758855),
(39537, 'Job 39:7', 'Job', 39, 7, 'هغه د ښار د شور نه نفرت کوى، او خرکار ورسره نشته چې په دې باندې آواز وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_007.mp3', NULL, 1761758855, 1761758855),
(39538, 'Job 39:8', 'Job', 39, 8, 'دا غرونو ته ځى چې دا يې د څرن زمکه شى، او هر يو شين بوټے د خوراک دپاره لټوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_008.mp3', NULL, 1761758855, 1761758855),
(39539, 'Job 39:9', 'Job', 39, 9, 'ولې ځنګلى غوَيے به تا پرېږدى چې کار ترېنه واخلى؟ هغه به ستا په اخور کښې شپه تېره کړى څۀ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_009.mp3', NULL, 1761758855, 1761758855),
(39540, 'Job 39:10', 'Job', 39, 10, 'ولې تۀ يو ځنګلى غوَيے د يوې دپاره تړلے شې؟ دا به ستا دپاره يو پټے يوه کړى څۀ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_010.mp3', NULL, 1761758855, 1761758855),
(39541, 'Job 39:11', 'Job', 39, 11, 'ولې تۀ د هغې لوئ طاقت باندې اعتبار کولے شې چې هغه به ستا مدد وکړى؟ تۀ په دې باندې دا يقين کولے شې څۀ چې دا به ستا دپاره کار وکړى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_011.mp3', NULL, 1761758855, 1761758855),
(39542, 'Job 39:12', 'Job', 39, 12, 'تۀ په دې يقين کوې چې دا به واپس راشى، او ستا درمند ته به ګېډى راوړى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_012.mp3', NULL, 1761758855, 1761758855),
(39543, 'Job 39:13', 'Job', 39, 13, 'د شتر‌مرغ وزر ښائسته کولاو خوريږى، خو دا د زاڼې د وزرو برابر کېدے خو نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_013.mp3', NULL, 1761758855, 1761758855),
(39544, 'Job 39:14', 'Job', 39, 14, 'شتر‌مرغ خپلې هګۍ د دې دپاره په زمکه پرېږدى، چې ګرمى شى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_014.mp3', NULL, 1761758855, 1761758855),
(39545, 'Job 39:15', 'Job', 39, 15, 'دا فکر نۀ کوى چې د څۀ پښې لاندې به راشى، او چې يو ځنګلى ځناور به يې ذرې ذرې کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_015.mp3', NULL, 1761758855, 1761758855),
(39546, 'Job 39:16', 'Job', 39, 16, 'دا په خپل بچى باندې داسې ظلم کوى، چې ګنې دا يې خپل نۀ وى، او کۀ مرى نو پرواه يې نۀ ساتى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_016.mp3', NULL, 1761758855, 1761758855),
(39547, 'Job 39:17', 'Job', 39, 17, 'ځکه چې خُدائ پاک د هغې نه عقل اخستے دے، او هيڅ پوهه يې نۀ ده ورکړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_017.mp3', NULL, 1761758855, 1761758855),
(39548, 'Job 39:18', 'Job', 39, 18, 'خو کله چې پاڅى او منډه کړى، نو بيا څوک چې په آس ناست هم وى د دې نه مخکښې کېدے نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_018.mp3', NULL, 1761758855, 1761758855),
(39549, 'Job 39:19', 'Job', 39, 19, 'ولې آس له طاقت تا ورکړے دے؟ د هغۀ په څټ باندې وېښتۀ تا پېدا کړى دى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_019.mp3', NULL, 1761758855, 1761758855),
(39550, 'Job 39:20', 'Job', 39, 20, 'د قحطۍ مُولخانو په شان د دې ټوپ تا جوړ کړے دے؟ او يا د دې هغه د رُعب والا آوازونه تا جوړ کړى دى څۀ چې خلق يروى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_020.mp3', NULL, 1761758855, 1761758855),
(39551, 'Job 39:21', 'Job', 39, 21, 'دا په پښه باندې زمکه ټکوى او په خپل طاقت په هغه وخت خوشحاليږى چې د جنګ دپاره ولېږلے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_021.mp3', NULL, 1761758855, 1761758855),
(39552, 'Job 39:22', 'Job', 39, 22, 'دا يرې پورې خندا کوى او نۀ بې‌حوصلې کيږى، او د تُورې نه نۀ شاته کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_022.mp3', NULL, 1761758855, 1761758855),
(39553, 'Job 39:23', 'Job', 39, 23, 'په دې باندې سورلۍ سره د غشو تيلۍ ځلېدونکې نېزه او وړه نېزه هم آواز پېدا کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_023.mp3', NULL, 1761758855, 1761758855),
(39554, 'Job 39:24', 'Job', 39, 24, 'د جوش او د غصې د وجې دا په تېزۍ سره ځى، دا د بيګل د غږېدو پورې صبر نۀ شى کولے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_024.mp3', NULL, 1761758855, 1761758855),
(39555, 'Job 39:25', 'Job', 39, 25, 'کله چې بيګل وغږيږى نو آس يو هڼ آواز وکړى. د لرې ځائ نه هغۀ له د جنګ بوئ ورځى، د جنګى مشرانو د تندر په شان آواز او چغې اورى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_025.mp3', NULL, 1761758855, 1761758855),
(39556, 'Job 39:26', 'Job', 39, 26, 'ولې باښه ستا د عقل په وجه الوځى، چې خپل وزر خوارۀ کړى او د جنوب طرف ته والوځى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_026.mp3', NULL, 1761758855, 1761758855),
(39557, 'Job 39:27', 'Job', 39, 27, 'باز ستا په حُکم بره خېژى او په اوچت ځائ خپله جاله جوړوى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_027.mp3', NULL, 1761758855, 1761758855),
(39558, 'Job 39:28', 'Job', 39, 28, 'دا په اوچت ګټ باندې اوسيږى او خپل کور جوړوى او د ګټ په سر باندې په يو محفوظ ځائ کښې شپه تېروى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_028.mp3', NULL, 1761758855, 1761758855),
(39559, 'Job 39:29', 'Job', 39, 29, 'د هغه ځائ نه يې په ښکار باندې نظر وى، او د هغۀ سترګې ښکار د لرې ځائ نه وينى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_029.mp3', NULL, 1761758855, 1761758855),
(39560, 'Job 39:30', 'Job', 39, 30, 'د دې بچى وينه څښى، او چې په کوم ځائ کښې مرداره وى، نو هغه په هغه ځائ کښې حاضر وى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job39_verse_030.mp3', NULL, 1761758855, 1761758855),
(39561, 'Nehemiah 8:1', 'Nehemiah', 8, 1, 'په اوومه میاشت د اسراییلو قوم ټول په خپلو ښارونو کې ځای په ځای شول. د همدې میاشتې په لومړۍ ورځ هغوی ټول په اورشلیم کې د اوبو د دروازې مخې ته په حوېلۍ کې سره راټول شول. هغوی د عزرا څخه چې د شریعت عالم ؤ، وغوښتل چې د تورات کتاب چې څښتن د موسی په وسیله اسراییلو ته ورکړی ؤ، راوړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_001.mp3', NULL, 1761758855, 1761758855),
(39562, 'Nehemiah 8:2', 'Nehemiah', 8, 2, 'نو عزرا هغه کتاب هغه ځای ته راوړ چې خلک په کې راټول شوي وو، یعنې سړي، ښځې او هغه ماشومان چې په داسې عمر کې وو چې د پوهېدلو توان یې درلود.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_002.mp3', NULL, 1761758855, 1761758855),
(39563, 'Nehemiah 8:3', 'Nehemiah', 8, 3, 'عزرا دروازې ته په مخامخ حوېلۍ کې د سهار وختي څخه تر غرمې پورې هغوی ته تورات ولوست او هغوی ټولو ورته په غور سره غوږ نیولی ؤ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_003.mp3', NULL, 1761758855, 1761758855),
(39564, 'Nehemiah 8:4', 'Nehemiah', 8, 4, 'عزرا د لرګي په منبر باندې چې د همدې مقصد دپاره جوړ شوی ؤ، ولاړ ؤ. د هغه ښي لاس ته متتیا، شمع، عنایا، اوریا، حلقیا او معسیا او چپ لاس ته یې فدایا، میشاییل، ملکیا، حاشوم، حشبدانه، زکریا او مشلام ولاړ وو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_004.mp3', NULL, 1761758855, 1761758855),
(39565, 'Nehemiah 8:5', 'Nehemiah', 8, 5, 'عزرا په یو داسې لوړ ځای کې ولاړ ؤ چې هرچا لیدلی شو. کله چې هغه کتاب پرانیست، هغوی ټول ودرېدل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_005.mp3', NULL, 1761758855, 1761758855),
(39566, 'Nehemiah 8:6', 'Nehemiah', 8, 6, 'عزرا لوی څښتن خدای ته ثنا وویله او ټول قوم خپل لاسونه پورته کړل او په ځواب کې یې وویل: «آمین! آمین!» هغوی په سجده شول او د څښتن عبادت یې وکړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_006.mp3', NULL, 1761758855, 1761758855),
(39567, 'Nehemiah 8:7', 'Nehemiah', 8, 7, 'وروسته بیا هغوی پاڅېدل او په خپلو ځایونو کې ودرېدل او دغو لاویانو ورته د تورات کتاب بیان کړ: یشوع، باني، شربیا، یامین، عقوب، شبتای، هودیه، معسیا، قلیطا، عزریا، یوزاباد، حانان او فلایا.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_007.mp3', NULL, 1761758855, 1761758855),
(39568, 'Nehemiah 8:8', 'Nehemiah', 8, 8, 'هغوی د خدای د تورات کتاب په لوړ اواز لوسته او هغه یې تشریح کاوه، ترڅو خلک پرې پوه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_008.mp3', NULL, 1761758855, 1761758855),
(39569, 'Nehemiah 8:9', 'Nehemiah', 8, 9, 'کله چې خلکو ته شریعت لوستل کېده، هغوی په ژړا پیل وکړ. نو نحمیا والي، عزرا کاهن او د شریعت عالم او هغو لاویانو چې خلکو ته یې شریعت تشریح کاوه، ټولو خلکو ته وویل: «دا ورځ ستاسو د څښتن خدای سپېڅلې ورځ ده. نو تاسو ویر او ژړا مه کوئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_009.mp3', NULL, 1761758855, 1761758855),
(39570, 'Nehemiah 8:10', 'Nehemiah', 8, 10, 'اوس خپلو کورونو ته لاړ شئ او جشن ونیسئ. د خپلو خوندورو خوړو او شرابو څخه هغه چاته چې نه یې لري د هغوی برخه ورکړئ. نن ورځ زمونږ د څښتن دپاره یوه سپېڅلې ورځ ده، نو مه خفه کېږئ. د څښتن خوشحالي ستاسو قوت دی.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_010.mp3', NULL, 1761758855, 1761758855),
(39571, 'Nehemiah 8:11', 'Nehemiah', 8, 11, 'لاویانو هم خلک ارام کړل او هغوی ته یې وویل: «غلي شئ! نن ورځ یوه سپېڅلې ورځ ده، نو مه ژاړئ او مه خفه کېږئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_011.mp3', NULL, 1761758855, 1761758855),
(39572, 'Nehemiah 8:12', 'Nehemiah', 8, 12, 'نو ټول خلک خپلو کورونو ته لاړل. هغوی په ډېره خوشحالۍ سره وخوړل او ویې څښل او څه چې یې درلودل، د هغو څخه یې نورو ته هم د هغوی برخه ورولېږله، ځکه څه چې هغوی ته لوستل شوي وو، ورباندې پوه شول.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_012.mp3', NULL, 1761758855, 1761758855),
(39573, 'Nehemiah 8:13', 'Nehemiah', 8, 13, 'یوه ورځ وروسته د ټولو طایفو مشران د کاهنانو او لاویانو سره یوځای عزرا ته ورغلل چې هغوی د تورات حکمونه زده کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_013.mp3', NULL, 1761758855, 1761758855),
(39574, 'Nehemiah 8:14', 'Nehemiah', 8, 14, 'هغوی په دې پوه شول چې په شریعت کې لیکل شوي دي چې څښتن د موسی په وسیله حکم کړی ؤ چې په اوومه میاشت چې هغوی اختر لمانځي، باید په جونګړو کې واوسیږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_014.mp3', NULL, 1761758855, 1761758855),
(39575, 'Nehemiah 8:15', 'Nehemiah', 8, 15, 'دا هغه حکم ؤ چې هغوی باید په اورشلیم او نورو ښارګوټو کې اعلان وکړي: «غرونو ته لاړ شئ او د زیتونو، ځنګلي زیتون، اس، خرما او نورو ونو څانګې راوړئ چې په شریعت کې د لیکل شویو لارښوونو سره سم د هغو څخه جونګړې جوړې کړئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_015.mp3', NULL, 1761758855, 1761758855),
(39576, 'Nehemiah 8:16', 'Nehemiah', 8, 16, 'نو خلکو د ونو څانګې راوړلې او د خپلو کوټو په بامونو، په خپلو حوېلیو، د خدای د کور په حویلۍ او د اوبو د دروازې او د افرایم د دروازې په عمومي میدان کې یې ورڅخه جونګړې جوړې کړې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_016.mp3', NULL, 1761758855, 1761758855),
(39577, 'Nehemiah 8:17', 'Nehemiah', 8, 17, 'هغو ټولو خلکو چې د اسیرتوب څخه بېرته راغلي وو، جونګړې جوړې کړې او په هغو کې اوسېدل. هغوی ټول ډېر خوشحاله وو، ځکه چې د نون د زوی یوشع د زمانې څخه تر هغې ورځې پورې اسراییلیانو په دې ډول جشن نه ؤ لمانځلی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_017.mp3', NULL, 1761758855, 1761758855),
(39578, 'Nehemiah 8:18', 'Nehemiah', 8, 18, 'د اختر د لومړۍ ورځې څخه تر وروستنۍ ورځې پورې عزرا هره ورځ د خدای د تورات یوه برخه په لوړ اواز لوستله. هغوی دا اختر اووه ورځې ولمانځه او د شریعت سره سم په اتمه ورځ نوموړي مراسم په دعا او عبادت سره پای ته ورسېدل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah8_verse_018.mp3', NULL, 1761758855, 1761758855),
(39579, 'Amos 4:1', 'Amos', 4, 1, 'ای د سامرې مېرمنو چې د باشان د غواګانو په شان چاغې شوې یئ، د کمزورو خلکو سره بد چلند کوئ، په غریبانو باندې ظلم کوئ او د خپلو مېړونو څخه غواړئ چې تاسو ته شراب راوړي، دې خبرو ته غوږ ونیسئ!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_001.mp3', NULL, 1761758855, 1761758855),
(39580, 'Amos 4:2', 'Amos', 4, 2, 'څښتن تعالی چې سپېڅلی ذات دی، قسم خوړلی دی: «هغه وخت راروان دی چې هغوی به په تاسو کې چنګک واچوي او تاسو به لکه د ماهیانو په شان راکاږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_002.mp3', NULL, 1761758855, 1761758855),
(39581, 'Amos 4:3', 'Amos', 4, 3, 'تاسو هر یو به د دېوال نژدې سوریو کې راښکل کېږئ او دباندې حرمون ته به غورځول کېږئ.» دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_003.mp3', NULL, 1761758855, 1761758855),
(39582, 'Amos 4:4', 'Amos', 4, 4, 'ای د اسراییلو خلکو، نو بیا لاړ شئ او په بیت‌ییل کې ګناه وکړئ! جلجال ته لاړ شئ او څومره چې کولای شئ ګناه وکړئ! هر سهار خپلې قربانۍ او په هره درېمه ورځ خپل عشر راوړئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_004.mp3', NULL, 1761758855, 1761758855),
(39583, 'Amos 4:5', 'Amos', 4, 5, 'لاړ شئ او خدای ته د شکرانې ډوډۍ وړاندې کړئ او تاسو چې د خپلې خوښې کومې اضافي نذرانې راوړئ، نو د هغو په هکله لافې ووهئ! ځکه چې دا کار ستاسو اسراییلیانو خوښ دی. دا هغه څه دي چې څښتن تعالی ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_005.mp3', NULL, 1761758855, 1761758855),
(39584, 'Amos 4:6', 'Amos', 4, 6, 'دا زه وم چې ستاسو په ټولو ښارونو باندې مې لوږه راوستله او په هر ځای کې مې قحطي راوستله، خو بیاهم تاسو ماته رجوع ونه کړه. دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_006.mp3', NULL, 1761758855, 1761758855),
(39585, 'Amos 4:7', 'Amos', 4, 7, 'کله چې ستاسو فصلونو ته د باران سخته اړتیا وه، نو ما باران بند کړ. په یو ښار باندې مې باران ووراوه او په بل ښار باندې مې بند کړ. په یو پټي باندې باران واورېده او په بل پټی چې باران ونه واورېده وچ شو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_007.mp3', NULL, 1761758855, 1761758855),
(39586, 'Amos 4:8', 'Amos', 4, 8, 'د څو ښارونو تندې وهلي خلک به ښار په ښار د اوبو پیدا کولو په هیله ګرځېدل، خو هلته به د څښلو دپاره زیاتې اوبه نه وې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_008.mp3', NULL, 1761758855, 1761758855),
(39587, 'Amos 4:9', 'Amos', 4, 9, 'ما یو سوځوونکی باد او مرض نازل کړ چې ستاسو فصلونه وچ شي. ستاسو ټول باغونه او تاکونه، د انځرو او د زیتونو ونې ملخانو وخوړلې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_009.mp3', NULL, 1761758855, 1761758855),
(39588, 'Amos 4:10', 'Amos', 4, 10, 'کومه بلا چې ما په مصر باندې راوستې وه، هغه مې په تاسو باندې راوستله. ستاسو ځوانان مې په جنګ کې ووژل او اسونه مې درڅخه واخیستل. ستاسو پوزې مې په خېمو کې د مړو د بوی نه ډکې کړلې. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_010.mp3', NULL, 1761758855, 1761758855),
(39589, 'Amos 4:11', 'Amos', 4, 11, 'ما ستاسو ځینې خلک د سدوم او عموره د خلکو په شان تباه کړل. ستاسو نه چې کوم خلک ژوندي پاتې شوي وو، نو هغوی د سوځېدلي لرګي په شان وو چې د اور نه راویستل شوي وو. خو بیاهم تاسو ماته رجوع ونه کړله. دا هغه څه دي چې څښتن ویلي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_011.mp3', NULL, 1761758855, 1761758855),
(39590, 'Amos 4:12', 'Amos', 4, 12, 'نو ای د اسراییلو خلکو، زه تاسو ته سزا درکوم. څرنګه چې زه دا کار کوم، نو زما قضاوت ته تیار شئ!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_012.mp3', NULL, 1761758855, 1761758855),
(39591, 'Amos 4:13', 'Amos', 4, 13, 'دا هغه ذات دی چې جوړ کړي یې دي غرونه او پیدا کړي یې دي بادونه هغه خبروي انسانان خپلو خیالونو نه هغه ورځ بدلوي شپې باندې هغه ګرځي د ځمکې په اوچتو ځایو د هغه نوم دی مطلق قادر څښتن خدای', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/amos4_verse_013.mp3', NULL, 1761758855, 1761758855),
(39592, 'Psalms 75:1', 'Psalms', 75, 1, 'مونږه ستا شکر کوو خدایه شکر کوو مونږه ځکه چې نژدې یې راته بیانوي خلک ستا عجیبه کارونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_001.mp3', NULL, 1761758855, 1761758855),
(39593, 'Psalms 75:2', 'Psalms', 75, 2, 'وایي خدای چې ما ټاکلی قضاوت دپاره وخت دی او په انصاف سره به کړم قضاوت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_002.mp3', NULL, 1761758855, 1761758855),
(39594, 'Psalms 75:3', 'Psalms', 75, 3, 'که څه هم هر ژوندی موجود به رېږدي او ځمکه به هم لړزیږي زه به یې وساتمه ستنې ټینګې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_003.mp3', NULL, 1761758855, 1761758855),
(39595, 'Psalms 75:4', 'Psalms', 75, 4, 'لاپو وهونکو ته دا وایم چې نه دې وهي لافې امر کوم په بدکارانو چې غرور دې نه کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_004.mp3', NULL, 1761758855, 1761758855),
(39596, 'Psalms 75:5', 'Psalms', 75, 5, 'هغوی ته وایم چې مغرور مه اوسئ د سرکښۍ په سبب بس کړئ د غرور خبرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_005.mp3', NULL, 1761758855, 1761758855),
(39597, 'Psalms 75:6', 'Psalms', 75, 6, 'سرلوړي نه راځي له شرقه یا له غربه ځینې او نه له دښتې او بیابانه ځینې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_006.mp3', NULL, 1761758855, 1761758855),
(39598, 'Psalms 75:7', 'Psalms', 75, 7, 'بلکې دا خدای دی چې کوي قضاوت ورکوي یو ته سرلوړي بل ته ذلت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_007.mp3', NULL, 1761758855, 1761758855),
(39599, 'Psalms 75:8', 'Psalms', 75, 8, 'څښتن نیولې ده پیاله په لاس کې چې کړې یې ډکه د قهر له ترخو شرابو چې اچوي یې څښتن او ټول بدکاران یې څښي باید یې وڅښي بدکاران تر اخري څاڅکي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_008.mp3', NULL, 1761758855, 1761758855),
(39600, 'Psalms 75:9', 'Psalms', 75, 9, 'خو زه به هېڅکله بس نه کړمه خبرې د یعقوب د خدای په هکله او ورته وایمه سندرې به زه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_009.mp3', NULL, 1761758855, 1761758855),
(39601, 'Psalms 75:10', 'Psalms', 75, 10, 'هغه به مات کړي ټول قوت د بدکارانو خو قوت به زیات شي د نېکانو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms75_verse_010.mp3', NULL, 1761758855, 1761758855),
(39602, 'Joshua 16:1', 'Joshua', 16, 1, 'د هغې ځمکې جنوبي سرحد چې د یوسف اولادې ته ورکړل شوې ده، اریحا ته نژدې د اردن د سیند څخه پیل شوی دی یعنې د اریحا د چینو د ختیځ څخه پیل شوی او د دښتې څخه تېر شوی او د اریحا څخه د بیت ییل تر غرنۍ سیمې پورې رسېدلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_001.mp3', NULL, 1761758855, 1761758855),
(39603, 'Joshua 16:2', 'Joshua', 16, 2, 'هغه د بیت ییل څخه لوز ته راوتلی دی او عطاروت ادار ته چې ارکیان په کې اوسېدل، وتلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_002.mp3', NULL, 1761758855, 1761758855),
(39604, 'Joshua 16:3', 'Joshua', 16, 3, 'بیا د ښکتني بیت حورون پورې په لوېدیځ کې د یفلیطیانو سیمې ته غزېدلی دی. د هغه ځای څخه جازر ته وتلی او د مدیترانې په بحیره کې ختم شوی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_003.mp3', NULL, 1761758855, 1761758855),
(39605, 'Joshua 16:4', 'Joshua', 16, 4, 'د یوسف اولادې یعنې د افرایم او لوېدیځې منسي قبیلو دا ځمکه د خپل ملکیت په توګه تر لاسه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_004.mp3', NULL, 1761758855, 1761758855),
(39606, 'Joshua 16:5', 'Joshua', 16, 5, 'دا سیمه د طایفې له مخې د افرایم سیمه وه: د هغوی د ځمکې سرحد د عطاروت ادار څخه چې په ختیځ کې ؤ پورتني بیت حورون ته رسېده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_005.mp3', NULL, 1761758855, 1761758855),
(39607, 'Joshua 16:6', 'Joshua', 16, 6, 'او د مدیترانې بحیرې ته تللی دی. د مکمیته څخه چې په شمال کې ؤ، ختیځ خواته تعنت شیلوه ته راګرځېدلی او د هغه ځای په ختیځ کې تېر شوی او یانواح ته تللی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_006.mp3', NULL, 1761758855, 1761758855),
(39608, 'Joshua 16:7', 'Joshua', 16, 7, 'بیا دا سرحد د یانواح څخه عطاروت او نعره ته راښکته شوی، د اریحا سره نښتی او د اردن سیند ته راوتلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_007.mp3', NULL, 1761758855, 1761758855),
(39609, 'Joshua 16:8', 'Joshua', 16, 8, 'د تفوح څخه دا سرحد لوېدیځ خواته د قانه خوړ ته تللی او د مدیترانې په بحیره کې ختم شوی دی. دا هغه ځمکه وه چې د ملکیت په توګه د افرایم قبیلې ته طایفه په طایفه ورکړل شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_008.mp3', NULL, 1761758855, 1761758855),
(39610, 'Joshua 16:9', 'Joshua', 16, 9, 'په دې کې ځینې ښارګوټي او کلي هم شامل وو چې د منسي د قبیلې په خاوره کې وو، خو هغه افرایم ته ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_009.mp3', NULL, 1761758855, 1761758855),
(39611, 'Joshua 16:10', 'Joshua', 16, 10, 'خو هغوی کنعانیان چې د جازر اوسېدونکي وو، ونه شړل. نو کنعانیان تر نن ورځې پورې د افرایمیانو په منځ کې اوسیږي، خو هغوی مجبور دي چې د غلامانو په توګه کار وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua16_verse_010.mp3', NULL, 1761758855, 1761758855),
(39612, 'Psalms 42:1', 'Psalms', 42, 1, 'لکه هوسۍ وي په ارمان کې د ویالو د اوبو داسې ای خدایه، یمه ستا په ارمان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_001.mp3', NULL, 1761758855, 1761758855),
(39613, 'Psalms 42:2', 'Psalms', 42, 2, 'ای ژوندی خدایه، زه د ستا د دیدار تږی یمه کله به درشم ستا حضور کې عبادت به وکړم؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_002.mp3', NULL, 1761758855, 1761758855),
(39614, 'Psalms 42:3', 'Psalms', 42, 3, 'شپه او ورځ ژاړمه زه اوښکې دي خوراک زما دښمنان تل راته پېغور راکوي چې «د ستا خدای چېرې دی؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_003.mp3', NULL, 1761758855, 1761758855),
(39615, 'Psalms 42:4', 'Psalms', 42, 4, 'زړه مې رامات شي چې رایاد کړم هغه تېر وختونه چې د خدای کور ته به ورتلم له ګڼو خلکو سره وو به خوشحال د شکرانې سندرې مونږ به ویلې د دوی په مخکې به روان ومه زه داسې یوه ګڼه چې نیوه به یې جشن', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_004.mp3', NULL, 1761758855, 1761758855),
(39616, 'Psalms 42:5', 'Psalms', 42, 5, 'ای زما ځانه، دومره خفه ولې یم؟ دومره پرېشان ولې یم؟ باید په خدای باندې توکل ولرم یوځل بیا به یې ثنا ووایم ای زما خدایه، خلاصوونکیه زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_005.mp3', NULL, 1761758855, 1761758855),
(39617, 'Psalms 42:6', 'Psalms', 42, 6, 'زما زړګی ماتیږي نو ځکه تاته یمه لاس په دعا په داسې حال کې چې زه دلته راګېر شوی یمه یعنې چې سیند د اردن اخلي سرچینه له دې ځای دعا کوم دلته د غره له حرمون د میسعر له غره نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_006.mp3', NULL, 1761758855, 1761758855),
(39618, 'Psalms 42:7', 'Psalms', 42, 7, 'ستا پارېدلې څپې ما باندې واوختلې لکه یو قهرېدلی دریاب یا غړمبېدونکی ابشار', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_007.mp3', NULL, 1761758855, 1761758855),
(39619, 'Psalms 42:8', 'Psalms', 42, 8, 'څښتن د ورځې راسره ښایي تلپاتې مینه زه ورته وایمه د شپې سندرې دعا کومه خدای ته زه چې یې ژوندون راکړی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_008.mp3', NULL, 1761758855, 1761758855),
(39620, 'Psalms 42:9', 'Psalms', 42, 9, 'زه هغه خدای ته چې ساتونکی مې دی داسې وایم: «زه دې ولې یم هېر کړی د خپل دښمن له ظلمه ولې زه ویر کې یمه؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_009.mp3', NULL, 1761758855, 1761758855),
(39621, 'Psalms 42:10', 'Psalms', 42, 10, 'ان هډوکي مې ماتیږي چې دښمن راته پېغور کړي تل دوی وایي ماته داسې: چې «ستا خدای چېرې دی؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_010.mp3', NULL, 1761758855, 1761758855),
(39622, 'Psalms 42:11', 'Psalms', 42, 11, 'ای زما ځانه، دومره خفه ولې یم؟ دومره پرېشان ولې یم؟ باید په خدای باندې توکل ولرم یوځلې بیا به یې ثنا ووایم ای زما خدایه، خلاصوونکیه زما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms42_verse_011.mp3', NULL, 1761758855, 1761758855),
(39623, 'Joshua 21:3', 'Joshua', 21, 3, 'نو څنګه چې څښتن حکم کړی ؤ، د اسراییلو قوم لاویانو ته د خپلو سیمو څخه ځینې ښارګوټي او څړځایونه ورکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_003.mp3', NULL, 1761758855, 1761758855),
(39624, 'Joshua 21:4', 'Joshua', 21, 4, 'لومړنۍ پچه د قهاتیانو د طایفو په نوم ووتله. هغو لاویانو ته چې د هارون کاهن د اولادې څخه وو، هغوی ته د یهودا، شمعون او بنیامین د سیمو څخه دیارلس ښارګوټي ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_004.mp3', NULL, 1761758855, 1761758855),
(39625, 'Joshua 21:5', 'Joshua', 21, 5, 'د افرایم، دان او لوېدیځې منسي د سیمو څخه لس ښارګوټي د قهات پاتې اولادې ته ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_005.mp3', NULL, 1761758855, 1761758855),
(39626, 'Joshua 21:6', 'Joshua', 21, 6, 'د یساکار، اشیر، نفتالي او په باشان کې د ختیځې منسي د سیمو څخه د جرشون اولادې ته دیارلس ښارګوټي ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_006.mp3', NULL, 1761758855, 1761758855),
(39627, 'Joshua 21:7', 'Joshua', 21, 7, 'د مراري د اولادې طایفو د روبین، جاد او زبولون د سیمو څخه دولس ښارګوټي تر لاسه کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_007.mp3', NULL, 1761758855, 1761758855),
(39628, 'Joshua 21:8', 'Joshua', 21, 8, 'نو لکه څنګه چې څښتن د موسی په وسیله امر کړی ؤ، د اسراییلو قوم د پچې له مخې لاویانو ته دا ښارګوټي د څړځایونو سره ورکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_008.mp3', NULL, 1761758855, 1761758855),
(39629, 'Joshua 21:11', 'Joshua', 21, 11, 'هغوی ته یې د یهودا په غرنۍ سیمه کې قریت اربع (حبرون) د شاوخوا څړځایونو سره ورکړه (اربع د عناق پلار ؤ).', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_011.mp3', NULL, 1761758855, 1761758855),
(39630, 'Joshua 21:12', 'Joshua', 21, 12, 'خو هغوی د ښار شاوخوا پټي او کلي پخوا د یفنه زوی کالیب ته د هغه د ملکیت په توګه ورکړي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_012.mp3', NULL, 1761758855, 1761758855),
(39631, 'Joshua 21:13', 'Joshua', 21, 13, 'نو هغوی د هارون کاهن اولادې ته دا لاندې ښارګوټي ورکړل: حبرون (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، لبنه،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_013.mp3', NULL, 1761758855, 1761758855),
(39632, 'Joshua 21:14', 'Joshua', 21, 14, 'یتیر، اشتموع،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_014.mp3', NULL, 1761758855, 1761758855),
(39633, 'Joshua 21:15', 'Joshua', 21, 15, 'حولون، دبیر،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_015.mp3', NULL, 1761758855, 1761758855),
(39634, 'Joshua 21:16', 'Joshua', 21, 16, 'عین، یوطه او بیت شمس د هغو د څړځایونو سره - د یهودا او شمعون د قبیلو څخه نهه ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_016.mp3', NULL, 1761758855, 1761758855),
(39635, 'Joshua 21:17', 'Joshua', 21, 17, 'د بنیامین د سیمې څخه یې هغوی ته جبعون، جبع،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_017.mp3', NULL, 1761758855, 1761758855),
(39636, 'Joshua 21:18', 'Joshua', 21, 18, 'عناتوت او علمون د هغو د څړځایونو سره ورکړل. دا څلور ښارګوټي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_018.mp3', NULL, 1761758855, 1761758855),
(39637, 'Joshua 21:19', 'Joshua', 21, 19, 'د کاهنانو یعنې د هارون د اولادې دپاره د څړځایونو سره ټول دیارلس ښارګوټي ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_019.mp3', NULL, 1761758855, 1761758855),
(39638, 'Joshua 21:20', 'Joshua', 21, 20, 'د لاویانو د قهاتیانو پاتې طایفو ته د افرایم د سیمې څخه یو څو ښارګوټي ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_020.mp3', NULL, 1761758855, 1761758855),
(39639, 'Joshua 21:21', 'Joshua', 21, 21, 'هغوی ته د افرایم په غرنۍ سیمه کې دا څلور ښارګوټي ورکړل شول: شکیم (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، جازر،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_021.mp3', NULL, 1761758855, 1761758855),
(39640, 'Joshua 21:22', 'Joshua', 21, 22, 'قبصایم او بیت حورون د هغو د څړځایونو سره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_022.mp3', NULL, 1761758855, 1761758855),
(39641, 'Joshua 21:23', 'Joshua', 21, 23, 'همدارنګه هغوی د دان د سیمې څخه دا څلور ښارګوټي تر لاسه کړل: التقي، جبتون،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_023.mp3', NULL, 1761758855, 1761758855),
(39642, 'Joshua 21:24', 'Joshua', 21, 24, 'ایالون او جت رمون د هغو د څړځایونو سره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_024.mp3', NULL, 1761758855, 1761758855),
(39643, 'Joshua 21:25', 'Joshua', 21, 25, 'هغوی د لوېدیځې نیمې منسي د سیمې څخه دوه ښارګوټي تر لاسه کړل: تعنک او جت رمون د هغو د څړځایونو سره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_025.mp3', NULL, 1761758855, 1761758855),
(39644, 'Joshua 21:26', 'Joshua', 21, 26, 'دا ټول لس ښارګوټي د هغو د څړځایونو سره د قهاتیانو پاتې طایفو ته ورکړل شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_026.mp3', NULL, 1761758855, 1761758855),
(39645, 'Joshua 21:27', 'Joshua', 21, 27, 'د لاویانو د جرشونیانو طایفو ته لاندېني ښارګوټي ورکړل شول: د ختیځې نیمې منسي د سیمې څخه جولان چې په باشان کې ؤ (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ) او بعشتره د هغو د څړځایونو سره - دوه ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_027.mp3', NULL, 1761758855, 1761758855),
(39646, 'Joshua 21:28', 'Joshua', 21, 28, 'د یساکار د سیمې څخه قشیون، دابره،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_028.mp3', NULL, 1761758855, 1761758855),
(39647, 'Joshua 21:29', 'Joshua', 21, 29, 'یرموت او عین جنیم د هغو د څړځایونو سره - څلور ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_029.mp3', NULL, 1761758855, 1761758855),
(39648, 'Joshua 21:30', 'Joshua', 21, 30, 'د اشیر د سیمې څخه مشال، عبدون،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_030.mp3', NULL, 1761758855, 1761758855),
(39649, 'Joshua 21:31', 'Joshua', 21, 31, 'حلقات او رحوب د هغو د څړځایونو سره - څلور ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_031.mp3', NULL, 1761758855, 1761758855),
(39650, 'Joshua 21:32', 'Joshua', 21, 32, 'د نفتالي د سیمې څخه قادش په جلیل کې (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، حموت دور او قرتان د هغو د څړځایونو سره - درې ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_032.mp3', NULL, 1761758855, 1761758855),
(39651, 'Joshua 21:33', 'Joshua', 21, 33, 'د جرشونیانو د طایفو ټول ښارګوټي د هغو د څړځایونو سره دیارلسو ته رسېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_033.mp3', NULL, 1761758855, 1761758855),
(39652, 'Joshua 21:34', 'Joshua', 21, 34, 'د مراریانو طایفو (پاتې لاویانو) ته لاندېني ښارګوټي ورکړل شول: د زبولون د سیمې څخه یقنعام، قرته،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_034.mp3', NULL, 1761758855, 1761758855),
(39653, 'Joshua 21:35', 'Joshua', 21, 35, 'دمنه او نحلال د هغو د څړځایونو سره - څلور ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_035.mp3', NULL, 1761758855, 1761758855),
(39654, 'Joshua 21:36', 'Joshua', 21, 36, 'د روبین د سیمې څخه باصر، یاهص،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_036.mp3', NULL, 1761758855, 1761758855),
(39655, 'Joshua 21:37', 'Joshua', 21, 37, 'قدیموت او میفعه د هغو د څړځایونو سره - څلور ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_037.mp3', NULL, 1761758855, 1761758855),
(39656, 'Joshua 21:38', 'Joshua', 21, 38, 'د جاد د سیمې څخه راموت په جلعاد کې (چې په قتل باندې تورن شوي کس دپاره د پناه اخیستلو ښار ؤ)، محنایم،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_038.mp3', NULL, 1761758855, 1761758855),
(39657, 'Joshua 21:39', 'Joshua', 21, 39, 'حشبون او یعزیر د هغو د څړځایونو سره - ټول څلور ښارګوټي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_039.mp3', NULL, 1761758855, 1761758855),
(39658, 'Joshua 21:40', 'Joshua', 21, 40, 'د ټولو ښارګوټو شمېر چې د مراریانو طایفو یعنې پاتې لاویانو ته ورکړل شول، دولسو ته رسېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_040.mp3', NULL, 1761758855, 1761758855),
(39659, 'Joshua 21:43', 'Joshua', 21, 43, 'نو څښتن اسراییلو ته هغه ټوله ځمکه ورکړه چې د هغوی د نیکونو سره یې قسم خوړلی ؤ. هغوی د دې ځمکې ملکیت تر لاسه کړ او هلته ځای په ځای شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_043.mp3', NULL, 1761758855, 1761758855),
(39660, 'Joshua 21:44', 'Joshua', 21, 44, 'لکه څنګه چې څښتن د هغوی د نیکونو سره وعده کړې وه، هغه د هغوی په ټوله خاوره کې ارامي راوستله. د هغوی یو دښمن هم نه شو کولای چې د هغوی په وړاندې ودریږي، ځکه چې څښتن اسراییلیانو ته په خپلو ټولو دښمنانو باندې بری ورکړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_044.mp3', NULL, 1761758855, 1761758855),
(39661, 'Joshua 21:45', 'Joshua', 21, 45, 'څښتن چې کومې وعدې د اسراییلو د قوم سره کړې وې، هغه ټولې یې سرته ورسولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/joshua21_verse_045.mp3', NULL, 1761758855, 1761758855),
(39662, 'Jeremiah 17:1', 'Jeremiah', 17, 1, 'مالِک خُدائ فرمائى چې، ”د يهوداه د خلقو ګناه د اوسپنې په قلم چې نوکه يې د هيرې ده، ستاسو د کاڼو نه په سختو زړُونو نقش شوې ده او ستاسو د قربان‌ګاه په ګوټونو ليکلې شوې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_001.mp3', NULL, 1761758855, 1761758855),
(39663, 'Jeremiah 17:2', 'Jeremiah', 17, 2, 'نۀ صرف تاسو بلکې ستاسو بچى هم خپلې قربان‌ګاه او د اشيرې بُت شکلونه همېشه رايادوى کۀ د شنې ونې په خوا کښې وى او کۀ په اوچته غونډۍ وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_002.mp3', NULL, 1761758855, 1761758855),
(39664, 'Jeremiah 17:3', 'Jeremiah', 17, 3, 'نو زۀ به په دې مُلک کښې خپل مقدس غر سره ستاسو د ټول مال دولت او ستاسو علاقائى عبادتخانې نورو خلقو ته د غنيمت په توګه حواله کړم، دا ستاسو د ګناهونو بدل دے کوم چې تاسو په خپل ټول مُلک کښې کړې دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_003.mp3', NULL, 1761758855, 1761758855),
(39665, 'Jeremiah 17:4', 'Jeremiah', 17, 4, 'ستاسو د خپلې ګناه په وجه به هغه مُلک ستاسو د لاس نه ووځى کوم چې ما تاسو ته په ميراث کښې درکړے دے. زۀ به تاسو په هغه مُلکونو کښې چې تاسو يې نۀ پېژنئ دشمنانو ته د غلام په شکل حواله کړم. ځکه چې تاسو زما د غصې اور بل کړے دے او هغه به تل بليږى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_004.mp3', NULL, 1761758855, 1761758855),
(39666, 'Jeremiah 17:5', 'Jeremiah', 17, 5, 'مالِک خُدائ فرمائى چې، ”لعنت دې په هغه چا وى چې د هغۀ زړۀ د مالِک خُدائ نه اوړېدلے وى او په فانى انسان توکل او د هغۀ په زور بهروسه کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_005.mp3', NULL, 1761758855, 1761758855),
(39667, 'Jeremiah 17:6', 'Jeremiah', 17, 6, 'هغه د بيابان د هغه بوټى په شان دے، کۀ څۀ هم چې خير وى خو هغوئ ته به مِلاو نۀ شى. ځکه چې هغه به د بيابان په خشکه او مالګينه زمکه کښې شوے وى، چرته چې نور څۀ نۀ کيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_006.mp3', NULL, 1761758855, 1761758855),
(39668, 'Jeremiah 17:7', 'Jeremiah', 17, 7, 'خو بختور دى هغوئ څوک چې په مالِک خُدائ يقين لرى، او په مالِک خُدائ يې توکل کړے وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_007.mp3', NULL, 1761758855, 1761758855),
(39669, 'Jeremiah 17:8', 'Jeremiah', 17, 8, 'هغوئ د هغه ونو په شان دى چې د لختى په غاړه کَرلے شوې وى او جرړې يې اوبو ته رسېدلې وى. نو کله چې د ګرمۍ موسم راشى نو يره يې نۀ وى، د هغوئ پاڼې هر وخت شنې وى. او په خُشک سالۍ کښې يې څۀ پرېشانى نۀ وى، نو کله هم بې‌مېوې نۀ پاتې کيږى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_008.mp3', NULL, 1761758855, 1761758855),
(39670, 'Jeremiah 17:9', 'Jeremiah', 17, 9, 'د انسان زړۀ د هر څۀ نه زيات دوکه مار وى، او د شرارت نه ډک وى. څوک پرې هم نۀ پوهيږى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_009.mp3', NULL, 1761758855, 1761758855),
(39671, 'Jeremiah 17:10', 'Jeremiah', 17, 10, '”زۀ مالِک خُدائ د انسان د زړۀ لټون کوم او د هغۀ پټ سوچونه آزمائيم، زۀ هر چا ته اجر د هغۀ د عمل په مطابق ورکوم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_010.mp3', NULL, 1761758855, 1761758855),
(39672, 'Jeremiah 17:11', 'Jeremiah', 17, 11, 'هغه څوک چې په ناجائزه طريقې سره مال دولت راجمع کړى هغه د هغه تيتر په شان وى چې پردۍ هګۍ وشاربى کومې چې هغې اچولې نۀ وى، نو وروستو به د هغۀ نه ټول مال دولت لاړ شى، کله چې د هغۀ عمر نيم تېر شى نو د هغۀ مال دولت به د هغۀ نه والوځى او په آخر کښې به دے خپل ځان کم عقل ثابت کړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_011.mp3', NULL, 1761758855, 1761758855),
(39673, 'Jeremiah 17:12', 'Jeremiah', 17, 12, 'خو هغه جلالى تخت چې د ازل نه اوچت دے، هغه زمونږ د خُدائ پاک مقدس کور دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_012.mp3', NULL, 1761758855, 1761758855),
(39674, 'Jeremiah 17:13', 'Jeremiah', 17, 13, 'اے مالِکه خُدايه، د بنى اِسرائيلو اُميده، هر څوک چې تا نه مخ واړوى هغوئ ټول به ټيټ سترګې او شرمنده شى. هغوئ چا چې تا نه مخ اړولے دے په دوړو د ليکلو په شان دى، دوئ به زر ختم شى ځکه چې هغوئ د هغه مالِک خُدائ نه مخ اړولے دے څوک چې د ژوندون د اوبو چينه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_013.mp3', NULL, 1761758855, 1761758855),
(39675, 'Jeremiah 17:14', 'Jeremiah', 17, 14, 'اے مالِکه خُدايه، کۀ چرې تۀ ما له شفا راکړې نو زۀ به بلکل روغ رمټ شم، کۀ چرې تۀ ما له خلاصون راکړې نو زۀ به بچ شم، ځکه چې زۀ صرف ستا ثناء صِفت کوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_014.mp3', NULL, 1761758855, 1761758855),
(39676, 'Jeremiah 17:15', 'Jeremiah', 17, 15, 'هغوئ ما ته بار بار دا وائى چې، د مالِک خُدائ هغه کارونه څۀ شول د چا د پوره کېدلو په حقله چې هغۀ پېشګوئې کړې وه؟ نو اوس دې هغه پوره کړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_015.mp3', NULL, 1761758855, 1761758855),
(39677, 'Jeremiah 17:16', 'Jeremiah', 17, 16, 'اے مالِکه خُدايه، زۀ د هغه کار نه نۀ يم تښتېدلے د کوم دپاره چې تاسو زۀ د خپل قوم دپاره د شپونکى په حيثيت مقرر کړے يم. تاسو ته پته ده چې ما په هغوئ د افت د ورځې د راتلو خواهش نۀ دے کړے. زما د شونډو نه چې څۀ هم وتلى دى هغه ستا په وړاندې څرګند دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_016.mp3', NULL, 1761758855, 1761758855),
(39678, 'Jeremiah 17:17', 'Jeremiah', 17, 17, 'مالِکه خُدايه، ما مۀ يروه، د افت په ورځ صرف تۀ زما اُميد يې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_017.mp3', NULL, 1761758855, 1761758855),
(39679, 'Jeremiah 17:18', 'Jeremiah', 17, 18, 'زما دشمنان دې وشرميږى خو ما مۀ شرموه، په هغوئ يره راوله خو ما مۀ يروه. په هغوئ د افت ورځې راوله، او هغوئ په دوه چنده تباه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_018.mp3', NULL, 1761758855, 1761758855),
(39680, 'Jeremiah 17:19', 'Jeremiah', 17, 19, 'مالِک خُدائ ما ته وفرمائيل، ”يرمياه، لاړ شه او د عوامى دروازې په خولۀ کښې ودرېږه په کومه چې د يهوداه بادشاهان ځى راځى او هم داسې د يروشلم په نورو دروازو کښې ودرېږه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_019.mp3', NULL, 1761758855, 1761758855),
(39681, 'Jeremiah 17:20', 'Jeremiah', 17, 20, 'هغوئ ته ووايه، د مالِک خُدائ پېغام واورئ. اے د يهوداه بادشاهانو او د يهوداه ټولو خلقو او د يروشلم اوسېدونکو او هغوئ ټولو ته چې په دې دروازې ځى راځى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_020.mp3', NULL, 1761758855, 1761758855),
(39682, 'Jeremiah 17:21', 'Jeremiah', 17, 21, 'مالِک خُدائ فرمائى چې، خبردار چې د سبت په ورځ په خپل سر پنډ مۀ اوچتوئ او د يروشلم په دروازو پنډ سره مۀ ننوځئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_021.mp3', NULL, 1761758855, 1761758855),
(39683, 'Jeremiah 17:22', 'Jeremiah', 17, 22, 'او تر دې چې په خپلو کورونو کښې هم د سبت په ورځ هيڅ قسمه کار مۀ کوئ او مۀ څۀ بار اوچتوئ. خو د سبت ورځ مقدسه وساتئ لکه څنګه چې ما ستاسو پلار نيکۀ ته حکم کړے وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_022.mp3', NULL, 1761758855, 1761758855),
(39684, 'Jeremiah 17:23', 'Jeremiah', 17, 23, 'خو هغوئ ما ته غوږ ونۀ نيولو او نۀ يې ما ته توجو راکړه او نۀ يې زما پيروى وکړه. خو هغوئ سرکشه وُو او اصلاح کولو ته يې جواب ورنۀ کړو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_023.mp3', NULL, 1761758855, 1761758855),
(39685, 'Jeremiah 17:24', 'Jeremiah', 17, 24, 'خو مالِک خُدائ فرمائى، کۀ چرې تاسو زما خبره ومنئ او د سبت په ورځ په دې دروازو د تجارت دپاره څۀ داخل نۀ کړئ او نۀ څۀ کار وکړئ، او هغه مقدسه وساتئ،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_024.mp3', NULL, 1761758855, 1761758855),
(39686, 'Jeremiah 17:25', 'Jeremiah', 17, 25, 'نو بيا به هغه بادشاهان څوک چې د داؤد په تخت ناست دى نو هغوئ به د خپلو آفسرانو سره د دې ښار په دروازو ځى راځى. او هغوئ او د هغوئ آفسران به په آسونو او ګاډو سوارۀ راشى، او د يهوداه خلق به ورسره وى او هغوئ څوک چې په يروشلم کښې اوسيږى، او دا ښار به د تل دپاره آباد وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_025.mp3', NULL, 1761758855, 1761758855),
(39687, 'Jeremiah 17:26', 'Jeremiah', 17, 26, 'د يهوداه د ښارونو او د يروشلم د ګېرچاپېره کلو نه به خلق راشى، هغوئ به د بنيامين د علاقې، د مغربى غونډو د لمنو نه، او د نجب او د غريزې علاقې نه به د خپلو سوزېدونکو نذرانو او قربانو سره راشى. هغوئ به د خپلو غلو دانو او خوشبوئى د شکرانې نذرانې سره د مالِک خُدائ کور ته راشى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_026.mp3', NULL, 1761758855, 1761758855),
(39688, 'Jeremiah 17:27', 'Jeremiah', 17, 27, 'خو کۀ تاسو زما خبره ونۀ منئ او د سبت ورځ مقدسه ونۀ ساتئ، او لکه د نورو ورځو په شان د سبت په ورځ د سودا پنډونه د يروشلم دروازو ته راؤړئ، نو بيا به زۀ په دې دروازو اور بل کړم. او دا اور به د يروشلم محلونه وسوزوى. او د دې اور لمبې به هيڅوک مړې کولے نۀ شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah17_verse_027.mp3', NULL, 1761758855, 1761758855),
(39689, 'Jeremiah 20:1', 'Jeremiah', 20, 1, 'کله چې فشحور د اِمير زوئ څوک چې د مالِک خُدائ په کور کښې مشر اِمام وو، هغه څۀ واورېدل د څۀ چې يرمياه پېشګوئې کوله،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_001.mp3', NULL, 1761758855, 1761758855),
(39690, 'Jeremiah 20:2', 'Jeremiah', 20, 2, 'نو هغۀ يرمياه نبى راګېر کړلو او په کوړو يې ووهلو او بيا يې هغه پاس د مالِک خُدائ په کور کښې د بنيامين په دروازه کښې د لرګى په کُنده کښې بند کړلو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_002.mp3', NULL, 1761758855, 1761758855),
(39691, 'Jeremiah 20:3', 'Jeremiah', 20, 3, 'په بله ورځ کله چې فشحور هغه د کُندې نه آزاد کړو، يرمياه هغۀ ته وفرمائيل چې، ”مالِک خُدائ ستا نوے نوم اېښے دے او د نن نه پس به ستا نوم فشحور نۀ وى بلکې په هر اړخ باندې دهشت.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_003.mp3', NULL, 1761758855, 1761758855),
(39692, 'Jeremiah 20:4', 'Jeremiah', 20, 4, 'ځکه مالِک خُدائ په خپله دا فرمائى چې، زۀ به په تا او ستا په دوستانو باندې دهشت راولم، او تۀ به په خپلو سترګو سره د هغوئ وژل د دشمنانو د لاسه ووينې. زۀ به د يهوداه ټول خلق د بابل بادشاه ته حواله کړم، څوک چې به د هغوئ نه ځينې بابل ته قېديان بوځى او ځينې به په تُوره قتل کړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_004.mp3', NULL, 1761758855, 1761758855),
(39693, 'Jeremiah 20:5', 'Jeremiah', 20, 5, 'زۀ به د دې ښار ټول مال دولت او د هغوئ ټول قيمتى سامانونه او د يهوداه بادشاه خزانې د هغوئ دشمنانو ته حواله کړم. هغوئ به دا لوټ کړى او بابل ته به يې يوسى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_005.mp3', NULL, 1761758855, 1761758855),
(39694, 'Jeremiah 20:6', 'Jeremiah', 20, 6, 'ترڅو چې ستا خبره ده فشحوره، تۀ او ستا مکمل خاندان به هم ونيولے شى او بابل ته به بوتلے شى. هلته به تاسو او ستا هغه ټول دوستان مړۀ او ښخ شى چا ته به چې تا په دروغو پېشګوئې کوله چې هيڅ پرواه مۀ کوئ خير به شى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_006.mp3', NULL, 1761758855, 1761758855),
(39695, 'Jeremiah 20:7', 'Jeremiah', 20, 7, 'اے مالِکه خُدايه، تا زۀ دوکه کړم، او زۀ دوکه شوم. تاسو زورَور يئ او زۀ دې مغلوب کړم. زۀ اوس ټوله ورځ د مسخرو شوم، او هر څوک ما پورې ټوقې او خندا کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_007.mp3', NULL, 1761758855, 1761758855),
(39696, 'Jeremiah 20:8', 'Jeremiah', 20, 8, 'کله چې هم زۀ خپله خولۀ خلاصوم، نو بيا ضرور زۀ د ظلم او تباهۍ په حقله چغې سورې وهم. ځکه چې زۀ د مالِک خُدائ د کلام په وجه ټوله ورځ کنځل او بدې ردې تېروم او سپکولے شم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_008.mp3', NULL, 1761758855, 1761758855),
(39697, 'Jeremiah 20:9', 'Jeremiah', 20, 9, 'خو چې کله زۀ ووايم چې، ”زۀ به د مالِک خُدائ په حقله خبرې نۀ کوم او نۀ به نور د هغۀ پېغام چا ته رسوم،“ نو بيا د هغۀ کلام زما په زړۀ کښې لکه د اور په شان بليږى او هغه اور زما هډوکو ته رسيږى. زۀ په ځان کښې د هغۀ د ايسارولو د کوشش په وجه ډېر ستړے شوے يم او زۀ هغه نۀ شم ايسارولے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_009.mp3', NULL, 1761758855, 1761758855),
(39698, 'Jeremiah 20:10', 'Jeremiah', 20, 10, 'ما د خپل ځان په حقله د ډېرو خلقو ګونګوسى اورېدلى دى. هغوئ وائى چې، ”هرې خوا ته دهشت دے بس دهشت. راځئ چې د هغۀ اِطلاع ورکړُو. راځئ چې د هغۀ په حقله اِطلاع ورکړُو.“ زما نزدې دوستان هم زما د غورزېدلو په انتظار دى، او هغوئ وائى چې، ”شايد چې هغه دوکه شى، نو بيا به يې راګېر کړُو او د هغۀ نه به خپله بدله واخلو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_010.mp3', NULL, 1761758855, 1761758855),
(39699, 'Jeremiah 20:11', 'Jeremiah', 20, 11, 'بلکې مالِک خُدائ د يو طاقتور جنګيالى په شان ما سره دے، نو بيا څوک هم چې زما د ژوند ختمولو پسې دى هغوئ به هيڅکله هم کامياب نۀ شى، او په خپله به تيندکونه وخورى. هغوئ به ناکاميابه شى او په شرمونو به وشرميږى، د هغوئ دا بې‌عزتى به هيڅکله د هېرېدلو نۀ وى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_011.mp3', NULL, 1761758855, 1761758855),
(39700, 'Jeremiah 20:12', 'Jeremiah', 20, 12, 'خو اے مالِکه خُدايه، ربُ الافواجه، تاسو په خپله صادق سړے وينئ، او تاسو په خپله د انسان د زړۀ او دماغ ژور سوچونه او رازونه آزمايئ. ما خپل خواست تا ته پېش کړے دے نو په دې وجه تاسو زما بدله اخستل ما ته وښايئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_012.mp3', NULL, 1761758855, 1761758855),
(39701, 'Jeremiah 20:13', 'Jeremiah', 20, 13, 'د مالِک خُدائ حمد ووايئ. د مالِک خُدائ ثناء صِفت ادا کړئ. هغه غريبانان د شريرانو د لاس نه بچ کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_013.mp3', NULL, 1761758855, 1761758855),
(39702, 'Jeremiah 20:14', 'Jeremiah', 20, 14, 'په هغه ورځ دې لعنت وى په کومه چې زۀ پېدا شوے وم. او هغه ورځ دې مبارکه نۀ وى په کومه ورځ چې زۀ د مور نه پېدا شوم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_014.mp3', NULL, 1761758855, 1761758855),
(39703, 'Jeremiah 20:15', 'Jeremiah', 20, 15, 'په هغه کس دې لعنت وى چا چې زما د پلار د خوشحالولو دپاره دا زېرے راوړے وو چې، ”ستا زوئ پېدا شوے دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_015.mp3', NULL, 1761758855, 1761758855),
(39704, 'Jeremiah 20:16', 'Jeremiah', 20, 16, 'هغه سړے دې د هغه ښارونو په شان شى کوم چې مالِک خُدائ په بې‌رحمۍ سره تباه کړى وُو. هغه دې په سحر کښې د يرې چغې واورى او په غرمه کښې دې د جنګ شور واورى،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_016.mp3', NULL, 1761758855, 1761758855),
(39705, 'Jeremiah 20:17', 'Jeremiah', 20, 17, 'ځکه چې زۀ هغۀ د پېدا کېدو نه وړاندې د مور په ګېډه کښې مړ نۀ کړم، ترڅو چې د هغې ګېډه زما قبر جوړ شوے وے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_017.mp3', NULL, 1761758855, 1761758855),
(39706, 'Jeremiah 20:18', 'Jeremiah', 20, 18, 'زۀ د مور د خېټې نه ولې دُنيا ته راغلم؟ د دې دپاره پېدا شوم چې په دُنيا کښې تکليفونه او کړاونه وګورم، او چې زما ژوند په بې‌عزتۍ کښې ختم شى؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah20_verse_018.mp3', NULL, 1761758855, 1761758855),
(39707, 'Psalms 17:1', 'Psalms', 17, 1, 'واوره زارۍ زما څښتنه، د انصاف دپاره هم د مرستې په خاطر زما فریاد واوره واوره دعا ته زما د بې ریا زړه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_001.mp3', NULL, 1761758855, 1761758855),
(39708, 'Psalms 17:2', 'Psalms', 17, 2, 'زما په حق کې ته انصاف وکړه ځکه پوهېږې حقیقت باندې ته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_002.mp3', NULL, 1761758855, 1761758855),
(39709, 'Psalms 17:3', 'Psalms', 17, 3, 'تا امتحان کړ زما زړه ته په شپه کې راغلې ماته زه دې ښه وازمایلم هېڅ بدي دې پیدا نه کړله په ما کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_003.mp3', NULL, 1761758855, 1761758855),
(39710, 'Psalms 17:4', 'Psalms', 17, 4, 'لکه د نورو په شان نه کوم خبرې بدې ما دی کړی اطاعت د ستا د امر ما د ظلم لاره نه ده خپله کړې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_004.mp3', NULL, 1761758855, 1761758855),
(39711, 'Psalms 17:5', 'Psalms', 17, 5, 'یمه تللی همېشه د ستا په لاره ښویېدلي مې هېڅ نه دي قدمونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_005.mp3', NULL, 1761758855, 1761758855),
(39712, 'Psalms 17:6', 'Psalms', 17, 6, 'خدایه فریاد کومه ځکه راکوې ته ځواب ونیسه غوږ ماته واوره زما بیان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_006.mp3', NULL, 1761758855, 1761758855),
(39713, 'Psalms 17:7', 'Psalms', 17, 7, 'عجیبه او تلپاتې مینه دې ښکاره کړه ماته ژغوري ستا ځواکمن لاس هغوی چې پناه غواړي په تا کې له دښمنه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_007.mp3', NULL, 1761758855, 1761758855),
(39714, 'Psalms 17:8', 'Psalms', 17, 8, 'ومې ساته لکه کسي د چشمانو پټ مې کړه د سیوري د وزرو نه دې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_008.mp3', NULL, 1761758855, 1761758855),
(39715, 'Psalms 17:9', 'Psalms', 17, 9, 'ومې ساته له بد کارو چې حمله کوي په ما له قاتلو دښمنانو چې چاپېره دي له ما', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_009.mp3', NULL, 1761758855, 1761758855),
(39716, 'Psalms 17:10', 'Psalms', 17, 10, 'رحم نشته په هغوی کې کړي خبرې کبرجنې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_010.mp3', NULL, 1761758855, 1761758855),
(39717, 'Psalms 17:11', 'Psalms', 17, 11, 'په ما پسې دي هغوی چاپېر شوي دي له ما نه په هرځای کې چې زه ګرځم دوی فرصت ته انتظار کړي چې ما وولي په ځمکه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_011.mp3', NULL, 1761758855, 1761758855),
(39718, 'Psalms 17:12', 'Psalms', 17, 12, 'دوی په شان دي د هغو وږیو زمریانو چې کړي ښکار خوراک دپاره یا په مثل د زمریانو د بچیانو چې په پټ ځای کې وي ناست حملې دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_012.mp3', NULL, 1761758855, 1761758855),
(39719, 'Psalms 17:13', 'Psalms', 17, 13, 'ای څښتنه، شه راپورته مقابل کې ته زما د دښمنانو او دوی مات کړه له بدکارو مې کړه خلاص په توره خپله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_013.mp3', NULL, 1761758855, 1761758855),
(39720, 'Psalms 17:14', 'Psalms', 17, 14, 'چې هرڅه لري هغوی په دې دنیا کې ما کړه خلاص له داسې خلکو سزا ورکړه د کړاو چې تا ساتلی دوی دپاره هم ورکړه پرېمانه کړاوونه یې بچیانو ته دغه شانتې ورکړه کړاوونه د بچیانو اولادو ته یې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_014.mp3', NULL, 1761758855, 1761758855),
(39721, 'Psalms 17:15', 'Psalms', 17, 15, 'خو زه به وکړم ستا دیدار ځکه بد مې کړي نه دي او چې کله رابېدار شم موجودیت د ستا قانع به زما زړه کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms17_verse_015.mp3', NULL, 1761758855, 1761758855),
(39722, 'Jeremiah 3:1', 'Jeremiah', 3, 1, 'مالِک خُدائ فرمائى، ”کۀ يو سړے خپله ښځه طلاقه کړى او د هغۀ نه جدا شى او بيا هغه د بل چا سره وادۀ وکړى نو آيا بيا اول خاوند ته د دې سره د دوباره وادۀ کولو اجازت شته څۀ؟ بلکل نه، ولې چې په داسې کولو به ټوله زمکه پوره پليته نۀ شى څۀ؟ خو اے اِسرائيله لکه څنګه چې يوه زناکاره ښځه په ډېرو سړو پسې ګرځى دغه شان تاسو په ډېرو بُتانو پسې وګرځېدئ نو اوس تاسو غواړئ چې ما ته دوباره راشئ څۀ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_001.mp3', NULL, 1761758855, 1761758855),
(39723, 'Jeremiah 3:2', 'Jeremiah', 3, 2, 'د اوچتو خُشکو غرونو طرف ته نظر وکړه او وګوره چې آيا هلته په هغې کښې داسې ځائ شته چې تۀ په کښې بې‌حرمته شوے نۀ يې؟ د لارې په خوا کښې تۀ د زنا دپاره يارانو ته داسې ولاړه وې، لکه چې يو کوچے په صحرا کښې په انتظار ناست وى. تا د زناکارۍ او شرارت په وجه ټوله زمکه پليته کړې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_002.mp3', NULL, 1761758855, 1761758855),
(39724, 'Jeremiah 3:3', 'Jeremiah', 3, 3, 'نو باران په دې وجه ايسار شوے وو او د سپرلى څاڅکى ونۀ ورېدل. نو دا چې تا د کنجرى شکل نيولے دے او تا له هيڅ شرم نۀ درځى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_003.mp3', NULL, 1761758855, 1761758855),
(39725, 'Jeremiah 3:4', 'Jeremiah', 3, 4, 'تۀ د دومره بې‌شرمۍ باوجود بيا هم ما ته وائې چې، ”اے پلاره، کله چې زۀ وړه وم، تا ما سره مينه کوله،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_004.mp3', NULL, 1761758855, 1761758855),
(39726, 'Jeremiah 3:5', 'Jeremiah', 3, 5, 'ولې تۀ به د تل دپاره ما ته په قهر يې څۀ؟ ولې ستا غضب به د تل دپاره په مونږ باندې وى څۀ؟“ تۀ خو داسې وائې مګر څومره بدعملى چې تا نه کېدے شى دومره کوې.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_005.mp3', NULL, 1761758855, 1761758855),
(39727, 'Jeremiah 3:6', 'Jeremiah', 3, 6, 'د يوسياه بادشاه د حکومت په دوران کښې مالِک خُدائ ما ته وفرمائيل، ”تا هغه څۀ وليدل کوم چې بې‌وفا اِسرائيل کړى دى؟ لکه د يوې بدکارې ښځې په شان هغې په هر يو اوچت غرۀ او د هرې شنې ونې د سورى لاندې زنا کړې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_006.mp3', NULL, 1761758855, 1761758855),
(39728, 'Jeremiah 3:7', 'Jeremiah', 3, 7, 'زما خيال دا وو چې د دې هر څۀ کولو نه وروستو به هغه ما ته واپس راوګرځى. خو دا راونۀ ګرځېده او د دې بې‌وفا خور يهوداه دا هر څۀ وليدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_007.mp3', NULL, 1761758855, 1761758855),
(39729, 'Jeremiah 3:8', 'Jeremiah', 3, 8, 'ما بې‌وفا اِسرائيل ته د هغې د زناکارۍ په وجه طلاق نامه ورکړه او ومې شړله نو بيا ما وليدل چې د هغې خور يهوداه نۀ يرېدله. هغه هم بهر ووتله او زناکارى يې شروع کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_008.mp3', NULL, 1761758855, 1761758855),
(39730, 'Jeremiah 3:9', 'Jeremiah', 3, 9, 'ځکه چې د اِسرائيل دغه بدکارى هغې ته ډېره بې‌اهميته ښکارېده نو هغې هغه زمکه پليته کړه چې د کاڼو او لرګو د بُتانو سره يې زنا شروع کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_009.mp3', NULL, 1761758855, 1761758855),
(39731, 'Jeremiah 3:10', 'Jeremiah', 3, 10, 'خو د دې هر څۀ باوجود، د هغې بې‌وفا خور يهوداه ما ته په پوره زړۀ سره راونۀ ګرځېدله، خو صرف په ظاهرى شکل سره زما طرف ته راواپس شوه. دا د مالِک خُدائ فرمان دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_010.mp3', NULL, 1761758855, 1761758855),
(39732, 'Jeremiah 3:11', 'Jeremiah', 3, 11, 'نو بيا مالِک خُدائ ما ته وفرمائيل چې، ”خو بيا دا چې بې‌ايمانه اِسرائيل د دوکه باز يهوداه نه صادق دے.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_011.mp3', NULL, 1761758855, 1761758855),
(39733, 'Jeremiah 3:12', 'Jeremiah', 3, 12, 'هغۀ ما ته وفرمائيل چې، ”د شمال طرف ته لاړ شه او هغوئ ته ووايه، اے بې‌ايمانه اِسرائيله، مالِک خُدائ فرمائى ما ته راواپس شه. زۀ به په غصې سره نور تا ته نۀ ګورم، ځکه چې زۀ رحم کوونکے يم، مالِک خُدائ فرمائى، او نۀ به زۀ د تل دپاره تا ته غصه يم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_012.mp3', NULL, 1761758855, 1761758855),
(39734, 'Jeremiah 3:13', 'Jeremiah', 3, 13, 'تۀ صرف د خپلو ګناهونو اقرار وکړه چې ګناهګار يم او تا د خپل مالِک خُدائ خلاف سرکشى کړې ده، او تا د هرې شنې ونې د لاندې د پردو بُتانو عبادت کړے دے او زما د کلام تابعدارى دې نۀ ده کړې، مالِک خُدائ دا فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_013.mp3', NULL, 1761758855, 1761758855),
(39735, 'Jeremiah 3:14', 'Jeremiah', 3, 14, 'اے بې‌ايمانه خلقو، راواپس شئ ځکه چې زۀ ستاسو مالِک يم. زۀ به ستاسو د ښاريې نه يو او د هرې قبيلې نه دوه دوه کسان خوښ کړم او صيون ښار ته به مو واپس راولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_014.mp3', NULL, 1761758855, 1761758855),
(39736, 'Jeremiah 3:15', 'Jeremiah', 3, 15, 'زۀ به تاسو له د شپونکو په شان مشران درکړم چې زما سوچ لرى او تاسو ته په عِلم او عقل سره هدايت کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_015.mp3', NULL, 1761758855, 1761758855),
(39737, 'Jeremiah 3:16', 'Jeremiah', 3, 16, 'نو کله چې ستاسو د خلقو شمېر په هغه مُلک کښې ډېر شى، مالِک خُدائ فرمائى، نو تاسو به په هغه ورځو کښې د خُدائ د لوظ صندوق ذکر نۀ کوئ او هم به ستاسو خيال ته دا نور نۀ راځى، او نۀ به هغه يادوئ، او نۀ به د هغې د ضرورت احساس تاسو ته کيږى، او نۀ به هغه دوباره جوړ کړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_016.mp3', NULL, 1761758855, 1761758855),
(39738, 'Jeremiah 3:17', 'Jeremiah', 3, 17, 'نو په دغه وخت کښې به دوئ يروشلم ته د ”مالِک خُدائ تخت“ ووائى، او ټول قومونه به په يروشلم کښې راټول شى او د مالِک خُدائ نوم له به عزت ورکړى. او دوئ به نور د خپل سرکشه او شريره زړونو پيروى نۀ کوى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_017.mp3', NULL, 1761758855, 1761758855),
(39739, 'Jeremiah 3:18', 'Jeremiah', 3, 18, 'نو په دغه ورځو کښې به د يهوداه خاندان د اِسرائيل د خاندان سره يوځائ شى او په شريکه به دوئ د شمال د جلاوطنۍ د مُلک نه هغه مُلک ته واپس راشى کوم چې ما ستاسو پلار نيکۀ له په ميراث کښې ورکړے وو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_018.mp3', NULL, 1761758855, 1761758855),
(39740, 'Jeremiah 3:19', 'Jeremiah', 3, 19, '”مالِک خُدائ په خپله فرمائى چې اے بنى اِسرائيله، ما غوښتل چې زۀ تا سره د خپل بچى په شان سلوک وکړم او د خپلې خوښې مُلک او زمکه درکړم، چې د نورو مُلکونو په نسبت ښکلې او شانداره وى. زما دا خيال وو چې تۀ به ما ته خپل پلار ووائې او زما نه به وانۀ وړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_019.mp3', NULL, 1761758855, 1761758855),
(39741, 'Jeremiah 3:20', 'Jeremiah', 3, 20, 'خو تۀ ما سره بې‌وفا شوې د هغې ښځې په شان څوک چې خپل خاوند سره بې‌وفا وى. مالِک خُدائ دا فرمائى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_020.mp3', NULL, 1761758855, 1761758855),
(39742, 'Jeremiah 3:21', 'Jeremiah', 3, 21, 'د خُشکو غرونو په اوچتو سرونو باندې د بنى اِسرائيليانو د ژړا او فرياد شور اورېدلے شى، ځکه چې هغوئ غلطه لار اختيار کړې ده او خپل مالِک خُدائ يې هېر کړے دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_021.mp3', NULL, 1761758855, 1761758855),
(39743, 'Jeremiah 3:22', 'Jeremiah', 3, 22, 'اے بې‌وفا بچو ما ته راواپس شئ زۀ به ستاسو بې‌وفائى له شفا درکړم. اے مالِکه خُدايه، مونږ به تا ته راواپس کيږُو ځکه چې تۀ مالِک خُدائ زمونږ خُدائ پاک يې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_022.mp3', NULL, 1761758855, 1761758855),
(39744, 'Jeremiah 3:23', 'Jeremiah', 3, 23, 'مونږ چې په زور شور سره د غرونو او غونډو په سرونو د بُتانو کوم عبادت کړے دے دا په رښتيا سره دوکه وه، د بنى اِسرائيل خلاصون په يقين سره صرف په مالِک خُدائ زمونږ خُدائ پاک دے.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_023.mp3', NULL, 1761758855, 1761758855),
(39745, 'Jeremiah 3:24', 'Jeremiah', 3, 24, 'د اول نه تر آخره پورې دې شرمناک د بعل بُت زمونږ د پلار نيکۀ د محنت مېوه، د دوئ رمې او څاروى، زامن او لوڼه ټول قبضه کړى دى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_024.mp3', NULL, 1761758855, 1761758855),
(39746, 'Jeremiah 3:25', 'Jeremiah', 3, 25, 'مونږ له په کار دى چې بې‌عزتى او شرم قبول کړُو او په شرمونو پټ شُو. ځکه چې مونږ د خپل پلار نيکۀ سره د خپل مالِک خُدائ زمونږ خُدائ پاک په خلاف ګناه کړې ده. د اول نه تر آخره پورې مونږ د خپل مالِک خُدائ پيروى نۀ ده کړې.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah3_verse_025.mp3', NULL, 1761758855, 1761758855),
(39747, 'Judges 8:1', 'Judges', 8, 1, 'د افرایم خلکو جدعون ته وویل: «تا ولې زمونږ سره داسې چلند وکړ؟ تا ولې مونږ د مدیانیانو سره د جګړې په وخت کې راونه غوښتلو؟» او هغه یې سخت ملامت کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_001.mp3', NULL, 1761758855, 1761758855),
(39748, 'Judges 8:2', 'Judges', 8, 2, 'خو جدعون په ځواب کې وویل: «ما چې کوم کار کړی دی هغه ستاسو د کار په پرتله هېڅ هم نه دی. حتی هغه وړوکی کار چې تاسو د افرایم خلکو کړی دی، هغه زمونږ د ټولې طایفې د کارونو څخه زیات ارزښت لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_002.mp3', NULL, 1761758855, 1761758855),
(39749, 'Judges 8:3', 'Judges', 8, 3, 'تاسو د خدای په مرسته د مدیانیانو دوه مشران یعنې غراب او زیب ووژل. ما څه کړي دي چې ستاسو سره یې پرتله کړم؟» په دې خبره د هغوی قهر سوړ شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_003.mp3', NULL, 1761758855, 1761758855),
(39750, 'Judges 8:4', 'Judges', 8, 4, 'وروسته بیا جدعون د خپلو درې سوه کسانو سره د اردن د سیند څخه تېر شو. که څه هم هغوی ډېر ستومانه شوي وو، خو بیاهم د خپلو دښمنانو پسې وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_004.mp3', NULL, 1761758855, 1761758855),
(39751, 'Judges 8:5', 'Judges', 8, 5, 'کله چې هغوی سوکوت ته ورسېدل، جدعون د ښارګوټي خلکو ته وویل: «مهرباني وکړئ زما کسانو ته د خوړلو دپاره یو څه ورکړئ. هغوی ډېر ستړي دي، خو مونږ د مدیانیانو پاچاهان زبح او صلمونع تعقیبوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_005.mp3', NULL, 1761758855, 1761758855),
(39752, 'Judges 8:6', 'Judges', 8, 6, 'خو د سوکوت مشرانو وویل: «تاسو تر اوسه پورې زبح او صلمونع نه دي نیولي، نو مونږ ولې ستا لښکرو ته ډوډۍ ورکړو؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_006.mp3', NULL, 1761758855, 1761758855),
(39753, 'Judges 8:7', 'Judges', 8, 7, 'جدعون وویل: «ښه ده! کله چې څښتن زبح او صلمونع ماته په لاس راکړل، نو بیا به زه بېرته راشم او ستاسو غوښې به د صحرا په اغزیو باندې وشکوم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_007.mp3', NULL, 1761758855, 1761758855),
(39754, 'Judges 8:8', 'Judges', 8, 8, 'جدعون د هغه ځای څخه فنوعیل ته لاړ او د هغه ځای د خلکو څخه یې خواړه وغوښتل، خو د فنوعیل خلکو هم د سوکوت د خلکو په شان هغه ته ځواب ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_008.mp3', NULL, 1761758855, 1761758855),
(39755, 'Judges 8:9', 'Judges', 8, 9, 'جدعون د فنوعیل خلکو ته وویل: «کله چې زه په سلامتۍ سره بېرته راشم، نو ستاسو برج به راوغورځوم!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_009.mp3', NULL, 1761758855, 1761758855),
(39756, 'Judges 8:10', 'Judges', 8, 10, 'په دې وخت کې زبح او صلمونع شاوخوا د پنځلس زره عسکرو سره په قرقور کې وو. د دښتې د قومونو د ټولو لښکرو څخه یوازې همدومره کسان پاتې شوي وو، ځکه چې یو لک او شل زره عسکر په جګړه کې وژل شوي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_010.mp3', NULL, 1761758855, 1761758855),
(39757, 'Judges 8:11', 'Judges', 8, 11, 'جدعون د کاروان د تېرېدلو په لاره باندې چې د نوبح او یجبها په ختیځ کې وه، لاړ او ناڅاپه یې د مدیانیانو په لښکرو باندې حمله وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_011.mp3', NULL, 1761758855, 1761758855),
(39758, 'Judges 8:12', 'Judges', 8, 12, 'د مدیانیانو دوه پاچاهان زبح او صلمونع وتښتېدل، خو جدعون په هغوی پسې شو، ویې نیول او د هغوی ټول لښکر یې سخت وارخطا کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_012.mp3', NULL, 1761758855, 1761758855),
(39759, 'Judges 8:13', 'Judges', 8, 13, 'د جګړې څخه وروسته جدعون کور ته روان شو. هغه د حارس په غاښي باندې روان ؤ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_013.mp3', NULL, 1761758855, 1761758855),
(39760, 'Judges 8:14', 'Judges', 8, 14, 'او یو ځوان یې چې د سوکوت اوسېدونکی ؤ، ونیوه او پوښتنه یې ترې وکړه چې د سوکوت مامورین او سپین ږیري څوک دي. هغه ځوان ورته د سوکوت د اووه اویا کسانو نومونه ولیکل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_014.mp3', NULL, 1761758855, 1761758855),
(39761, 'Judges 8:15', 'Judges', 8, 15, 'بیا جدعون لاړ او د سوکوت خلکو ته یې وویل: «تاسو ماته پېغور راکاوه او ویل مو چې تا تر اوسه پورې زبح او صلمونع نه دي نیولي، نو مونږ ولې ستاسو ستړي شویو لښکرو ته ډوډۍ ورکړو؟ دا دی وګورئ زبح او صلمونع دلته دي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_015.mp3', NULL, 1761758855, 1761758855),
(39762, 'Judges 8:16', 'Judges', 8, 16, 'بیا هغه د دښتې اغزي راواخیستل او د سوکوت مشران یې په اغزیو باندې ووهل او سزا یې ورته ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_016.mp3', NULL, 1761758855, 1761758855),
(39763, 'Judges 8:17', 'Judges', 8, 17, 'همدارنګه هغه د فنوعیل برج وران کړ او د ښارګوټي ټول سړي یې ووژل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_017.mp3', NULL, 1761758855, 1761758855),
(39764, 'Judges 8:18', 'Judges', 8, 18, 'بیا هغه د زبح او صلمونع څخه پوښتنه وکړه: «هغه خلک چې تاسو په تابور کې ووژل، هغه څه ډول خلک وو؟» هغوی په ځواب کې وویل: «هغوی ستا په شان وو، هر یو لکه د شاهزاده په شان ؤ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_018.mp3', NULL, 1761758855, 1761758855),
(39765, 'Judges 8:19', 'Judges', 8, 19, 'جدعون وویل: «هغوی زما سکه ورونه وو. زه د ژوندي څښتن په نوم قسم خورم، که چېرې تاسو هغوی نه وای وژلي، نو ما به هم تاسو نه وای وژلي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_019.mp3', NULL, 1761758855, 1761758855),
(39766, 'Judges 8:20', 'Judges', 8, 20, 'بیا هغه خپل مشر زوی یتر ته وویل: «پورته شه او هغوی ووژنه!» خو هغه خپله توره راونه ویستله، ځکه چې هغه لا هلک ؤ او ووېرېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_020.mp3', NULL, 1761758855, 1761758855),
(39767, 'Judges 8:21', 'Judges', 8, 21, 'بیا زبح او صلمونع جدعون ته وویل: «راشه ته په خپله مونږ ووژنه. د هلک څخه د سړي کار مه غواړه.» نو جدعون هغوی دواړه ووژل او کوم زېورات چې د هغوی د اوښانو په غاړو کې وو، هغه یې واخیستل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_021.mp3', NULL, 1761758855, 1761758855),
(39768, 'Judges 8:22', 'Judges', 8, 22, 'له هغې وروسته اسراییلیانو جدعون ته وویل: «ته زمونږ پاچا شه او ستا څخه وروسته دې ستا اولاده په مونږ باندې پاچاهي وکړي، ځکه چې تا مونږ له مدیانیانو څخه ژغورلي یو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_022.mp3', NULL, 1761758855, 1761758855),
(39769, 'Judges 8:23', 'Judges', 8, 23, 'جدعون په ځواب کې وویل: «نه به زه او نه به زما زوی ستاسو پاچا شي. څښتن به ستاسو پاچا وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_023.mp3', NULL, 1761758855, 1761758855),
(39770, 'Judges 8:24', 'Judges', 8, 24, 'خو زه ستاسو څخه یوه غوښتنه کوم. تاسو هر یو ماته د خپل غنیمت څخه یوه یوه غوږوالۍ راکړئ.» هغه داسې وویل، ځکه چې د دښمن عسکر چې اسماعیلیان وو، د سرو زرو غوږوالۍ به یې اچولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_024.mp3', NULL, 1761758855, 1761758855),
(39771, 'Judges 8:25', 'Judges', 8, 25, 'خلکو په ځواب کې وویل: «مونږ په خوشحالۍ سره خپلې غوږوالۍ تاته درکوو.» نو هغوی یوه چپنه وغوړوله او هر کس په کې خپلې غوږوالۍ چې په غنیمت کې یې نیولې وې، واچولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_025.mp3', NULL, 1761758855, 1761758855),
(39772, 'Judges 8:26', 'Judges', 8, 26, 'د سرو زرو د غوږوالیو وزن چې جدعون واخیستلې شل کیلو ګرامه ؤ، پرته له ګاڼو، غاړکیو او د مدیانیانو د پاچاهانو د شاهانه کالیو او هغو زنځیرونو څخه چې د هغوی د اوښانو په غاړو کې وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_026.mp3', NULL, 1761758855, 1761758855),
(39773, 'Judges 8:27', 'Judges', 8, 27, 'جدعون د هغو سرو زرو څخه یو بت جوړ کړ او هغه یې په خپل ښارګوټي یعنې عفره کې کېښود. ټولو اسراییلیانو خدای پرېښود او د بت د عبادت دپاره هلته لاړل. دا کار د جدعون او د هغه د کورنۍ دپاره یو دام شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_027.mp3', NULL, 1761758855, 1761758855),
(39774, 'Judges 8:28', 'Judges', 8, 28, 'نو مدیانیان د اسراییلیانو په وړاندې کمزوري شول او نور یې نه شو کولای چې سر راپورته کړي. د جدعون په ژوندانه کې څلوېښت کاله په هغه خاوره کې ارامي وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_028.mp3', NULL, 1761758855, 1761758855),
(39775, 'Judges 8:29', 'Judges', 8, 29, 'جدعون بېرته خپل کور ته ستون شو او هلته اوسېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_029.mp3', NULL, 1761758855, 1761758855),
(39776, 'Judges 8:30', 'Judges', 8, 30, 'جدعون اویا زامن درلودل، ځکه چې ډېرې ښځې یې درلودلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_030.mp3', NULL, 1761758855, 1761758855),
(39777, 'Judges 8:31', 'Judges', 8, 31, 'هغه یوه وینځه هم درلودله چې په شکیم کې اوسېدله، هغې هم د هغه دپاره یو زوی وزېږاوه او جدعون ورباندې ابیملک نوم کېښود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_031.mp3', NULL, 1761758855, 1761758855),
(39778, 'Judges 8:32', 'Judges', 8, 32, 'جدعون د یوآش زوی په پوخ عمر کې مړ شو او د خپل پلار په هدیره کې یې په عفره یعنې د ابیعزر د طایفې په ښارګوټي کې ښخ کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_032.mp3', NULL, 1761758855, 1761758855),
(39779, 'Judges 8:33', 'Judges', 8, 33, 'څنګه چې جدعون مړ شو، د اسراییلو قوم یوځل بیا د خدای سره بې وفایي وکړه او د بعل د بتانو عبادت یې پیل کړ. هغوی د بعل بریت څخه خپل خدای جوړ کړ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_033.mp3', NULL, 1761758855, 1761758855),
(39780, 'Judges 8:34', 'Judges', 8, 34, 'او خپل څښتن خدای یې چې هغوی یې د خپل شاوخوا ټولو دښمنانو څخه ژغورلي وو، هېر کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_034.mp3', NULL, 1761758855, 1761758855),
(39781, 'Judges 8:35', 'Judges', 8, 35, 'سره له دې چې یروبعل (جدعون) د اسراییلیانو دپاره ښه ښه کارونه کړي وو، خو هغوی د هغه د کورنۍ سره وفاداري ونه ښودله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges8_verse_035.mp3', NULL, 1761758855, 1761758855),
(39782, 'Exodus 29:1', 'Exodus', 29, 1, 'دا هغه مراسم دي چې د کاهنانو په توګه د هارون او د هغه د زامنو د وقف کولو دپاره دې سرته ورسیږي: یو داسې خوسی او دوه پسونه واخله چې کوم عیب په کې نه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_001.mp3', NULL, 1761758855, 1761758855),
(39783, 'Exodus 29:2', 'Exodus', 29, 2, 'د غنمو د ډېرو ښو اوړو څخه فطیرې ډوډۍ پخې کړه. ځینې د زیتونو په تېلو کې پخې کړه، ځینې بې له تېلو او ځینې یې د کلچو په شکل چې تېل ورباندې موښل شوي وي پخې کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_002.mp3', NULL, 1761758855, 1761758855),
(39784, 'Exodus 29:3', 'Exodus', 29, 3, 'دا ټولې ډوډۍ په یوې ټوکرۍ کې واچوه او کله چې ته راځې او هغه غویی او دوه پسونه ماته قرباني کوې، نو هغه درسره راوړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_003.mp3', NULL, 1761758855, 1761758855),
(39785, 'Exodus 29:4', 'Exodus', 29, 4, 'بیا هارون او د هغه زامن د سپېڅلې خېمې د دروازې خولې ته راوله او غسل ورته ورکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_004.mp3', NULL, 1761758855, 1761758855),
(39786, 'Exodus 29:5', 'Exodus', 29, 5, 'دا کالي واخله او هارون ته یې ورواغونده: کمیس، هغه چپنه چې د سپېڅلي پېشبند لاندې اغوستل کیږي، سپېڅلی پېشبند او سینه پوښ. سپېڅلی پېشبند په کمربند باندې وتړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_005.mp3', NULL, 1761758855, 1761758855),
(39787, 'Exodus 29:6', 'Exodus', 29, 6, 'هغه ته لونګۍ په سر کړه او په هغې لونګۍ باندې سپېڅلی نښان ولګوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_006.mp3', NULL, 1761758855, 1761758855),
(39788, 'Exodus 29:7', 'Exodus', 29, 7, 'بیا د مسح کولو تېل واخله او د هغه په سر باندې یې توی کړه او مسح یې کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_007.mp3', NULL, 1761758855, 1761758855),
(39789, 'Exodus 29:8', 'Exodus', 29, 8, 'د هغه زامن راوله او کمیسونه ورته واغونده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_008.mp3', NULL, 1761758855, 1761758855),
(39790, 'Exodus 29:9', 'Exodus', 29, 9, 'او خولۍ ګانې ورته په سر کړه. بیا د هارون او د هغه د زامنو په ملاګانو باندې پټۍ ګانې وتړه. په دې ډول به هارون او د هغه زامن وټاکې. هغوی او د هغوی اولاده به د تل دپاره د کاهنانو په توګه زما خدمت کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_009.mp3', NULL, 1761758855, 1761758855),
(39791, 'Exodus 29:10', 'Exodus', 29, 10, 'غویی د سپېڅلې خېمې مخې ته راوله او هارون او د هغه زامن به د هغه په سر باندې خپل لاسونه کېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_010.mp3', NULL, 1761758855, 1761758855),
(39792, 'Exodus 29:11', 'Exodus', 29, 11, 'هغه د خېمې د دروازې په خوله کې زما په حضور کې حلال کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_011.mp3', NULL, 1761758855, 1761758855),
(39793, 'Exodus 29:12', 'Exodus', 29, 12, 'د غویي لږه وینه واخله او په خپله ګوته یې په هغو ښکرونو باندې چې د قربانۍ د ځای په کنجونو کې دي وسولوه. بیا پاتې وینه د قربانۍ د ځای په بېخ کې توی کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_012.mp3', NULL, 1761758855, 1761758855),
(39794, 'Exodus 29:13', 'Exodus', 29, 13, 'بیا ټوله هغه وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه او د هغه دوه پښتورګي چې وازګه ورباندې پرته وي، واخله او هغه ماته د یوې نذرانې په توګه د قربانۍ په ځای باندې وسوځوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_013.mp3', NULL, 1761758855, 1761758855),
(39795, 'Exodus 29:14', 'Exodus', 29, 14, 'خو د غویي غوښه، پوستکی او خوشایي د کمپ څخه دباندې وسوځوه. دا د ګناه یوه نذرانه ده چې د کاهنانو د ګناهونو د پاکولو دپاره ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_014.mp3', NULL, 1761758855, 1761758855),
(39796, 'Exodus 29:15', 'Exodus', 29, 15, 'د هغو پسونو څخه یو پسه واخله او هارون او د هغه زامن به خپل لاسونه د هغه په سر باندې کېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_015.mp3', NULL, 1761758855, 1761758855),
(39797, 'Exodus 29:16', 'Exodus', 29, 16, 'هغه حلال کړه او وینه یې واخله او د قربانۍ د ځای په څلورو خواو باندې یې وشینده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_016.mp3', NULL, 1761758855, 1761758855),
(39798, 'Exodus 29:17', 'Exodus', 29, 17, 'پسه ټوټې ټوټې کړه او د نس دنننۍ برخې او پښې یې ووینځه او د سر او د نورو ټوټو سره یې کېږده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_017.mp3', NULL, 1761758855, 1761758855),
(39799, 'Exodus 29:18', 'Exodus', 29, 18, 'بیا ټول پسه د قربانۍ په ځای باندې وسوځوه. دا زما یعنې څښتن دپاره یوه سوځېدونکې نذرانه ده چې بوی یې په ما باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_018.mp3', NULL, 1761758855, 1761758855),
(39800, 'Exodus 29:19', 'Exodus', 29, 19, 'هغه بل پسه واخله او هارون او د هغه زامن به خپل لاسونه د هغه په سر باندې کېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_019.mp3', NULL, 1761758855, 1761758855),
(39801, 'Exodus 29:20', 'Exodus', 29, 20, 'هغه حلال کړه. لږه وینه یې واخله او د هارون او د هغه د زامنو د ښي غوږونو په نرمیو، د ښي لاسونو په غټو ګوتو او د ښي پښو په غټو ګوتو باندې یې وسولوه. بیا پاتې وینه د قربانۍ د ځای په څلورو خواو باندې وشینده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_020.mp3', NULL, 1761758855, 1761758855),
(39802, 'Exodus 29:21', 'Exodus', 29, 21, 'د هغې وینې څخه لږه وینه چې د قربانۍ په ځای باندې پرته ده، واخله او لږ د مسح کولو تېل واخله او په هارون او د هغه په زامنو او د هغوی په کالیو باندې یې وشینده. بیا به هغه، د هغه زامن او د هغوی کالي ماته وقف شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_021.mp3', NULL, 1761758855, 1761758855),
(39803, 'Exodus 29:22', 'Exodus', 29, 22, 'د پسه وازګه، لم، هغه وازګه چې په کولمو باندې پرته وي، د اینې ډېره ښه برخه، دوه پښتورګي د وازګې سره چې ورباندې پرته وي او ښي ورون، دا ټول ورڅخه پرې کړه. دا پسه د ټاکنې د مراسمو دپاره دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_022.mp3', NULL, 1761758855, 1761758855),
(39804, 'Exodus 29:23', 'Exodus', 29, 23, 'د هغې ټوکرۍ څخه د هر ډول ډوډۍ نه یوه یوه ډوډۍ راواخله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_023.mp3', NULL, 1761758855, 1761758855),
(39805, 'Exodus 29:24', 'Exodus', 29, 24, 'او دا ټول د هارون او د هغه د زامنو په لاسونو کې کېږده. بیا هغوی دې هغه پورته ونیسي، ترڅو دا وښایي چې هغه ماته وقف شوي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_024.mp3', NULL, 1761758855, 1761758855),
(39806, 'Exodus 29:25', 'Exodus', 29, 25, 'بیا یې د هغوی د لاسونو څخه راواخله او د قربانۍ په ځای باندې یې د سوځېدونکې نذرانې سره وسوځوه چې بوی یې په ما څښتن باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_025.mp3', NULL, 1761758855, 1761758855),
(39807, 'Exodus 29:26', 'Exodus', 29, 26, 'کله چې ته د هارون د ټاکلو دپاره د پسه سینه واخلې، نو لومړی باید هغه پورته ونیسې، ترڅو دا وښایي چې دا غوښه ماته وقف شوې ده. دا به ستا برخه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_026.mp3', NULL, 1761758855, 1761758855),
(39808, 'Exodus 29:29', 'Exodus', 29, 29, 'د هارون سپېڅلي کالي به د هغه له مرګ څخه وروسته د هغه اولادې ته پاتې شي، ترڅو هغوی په کې مسح شي او وټاکل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_029.mp3', NULL, 1761758855, 1761758855),
(39809, 'Exodus 29:30', 'Exodus', 29, 30, 'د هارون زوی چې د هغه څخه وروسته کاهن کیږي او سپېڅلې خېمې ته ورننوځي چې په سپېڅلي ځای کې خدمت وکړي، نو هغه دې اووه ورځې دا کالي واغوندي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_030.mp3', NULL, 1761758855, 1761758855),
(39810, 'Exodus 29:31', 'Exodus', 29, 31, 'هغه پسه چې د ټاکنې د مراسمو دپاره دی، واخله او غوښه یې په یو پاک ځای کې پخه کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_031.mp3', NULL, 1761758855, 1761758855),
(39811, 'Exodus 29:32', 'Exodus', 29, 32, 'د سپېڅلې خېمې د دروازې په خولې کې دې هارون او د هغه زامن د پسه غوښه او هغه ډوډۍ چې په ټوکرۍ کې پاتې ده، وخوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_032.mp3', NULL, 1761758855, 1761758855),
(39812, 'Exodus 29:33', 'Exodus', 29, 33, 'یوازې هغوی کولای شي چې د ټاکنې په مراسمو کې هغه غوښه او ډوډۍ چې د هغوی د کفارې د ادا کولو دپاره ورڅخه کار اخیستل کیږي، وخوري. عادي خلک نه شي کولای هغه وخوري، ځکه چې دا شیان سپېڅلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_033.mp3', NULL, 1761758855, 1761758855),
(39813, 'Exodus 29:34', 'Exodus', 29, 34, 'که چېرې یو څه غوښه یا ډوډۍ ونه خوړل شي او تر سهاره پورې پاتې شي، هغه وسوځوه. هغه باید ونه خوړل شي، ځکه چې سپېڅلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_034.mp3', NULL, 1761758855, 1761758855),
(39814, 'Exodus 29:35', 'Exodus', 29, 35, 'لکه څنګه چې ما درته حکم کړی دی د هارون او د هغه د زامنو د ټاکنې مراسم دې په اوو ورځو کې سرته ورسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_035.mp3', NULL, 1761758855, 1761758855),
(39815, 'Exodus 29:36', 'Exodus', 29, 36, 'ته باید هره ورځ یو غویی حلال کړې او ماته یې وړاندې کړې، ترڅو د هغوی ګناه وبخښم او د قربانۍ ځای پاک شي. برسېره پردې باید د زیتونو تېل واخلې او د قربانۍ ځای ورباندې مسح کړې چې سپېڅلی شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_036.mp3', NULL, 1761758855, 1761758855),
(39816, 'Exodus 29:37', 'Exodus', 29, 37, 'اووه ورځې دا کار وکړه. بیا به د قربانۍ ځای دومره سپېڅلی شي چې هرڅوک یا هر شی چې د هغه سره ولګیږي، هغه به هم سپېڅلی شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_037.mp3', NULL, 1761758855, 1761758855),
(39817, 'Exodus 29:38', 'Exodus', 29, 38, 'ته باید هره ورځ د قربانۍ په ځای باندې دوه یو کلن وري قرباني کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_038.mp3', NULL, 1761758855, 1761758855),
(39818, 'Exodus 29:39', 'Exodus', 29, 39, 'یو په سهار کې قرباني کړه او بل په ماښام کې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_039.mp3', NULL, 1761758855, 1761758855),
(39819, 'Exodus 29:40', 'Exodus', 29, 40, 'د لومړني وري سره یو کیلو ګرام ښه اوړه وړاندې کړه چې یو لیتر سوچه د زیتونو تېل ورسره ګډ وي او د څښلو د نذرانې په توګه یو لیتر شراب هم وړاندې کړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_040.mp3', NULL, 1761758855, 1761758855),
(39820, 'Exodus 29:41', 'Exodus', 29, 41, 'دوهم وری په ماښام کې قرباني کړه او د هغه سره هماغه اندازه اوړه، د زیتونو تېل او شراب وړاندې کړه لکه څنګه چې په سهار کې دې وکړل. دا زما دپاره یوه سوځېدونکې نذرانه ده او د هغې بوی په ما باندې ښه لګیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_041.mp3', NULL, 1761758855, 1761758855),
(39821, 'Exodus 29:42', 'Exodus', 29, 42, 'دا سوځېدونکې نذرانه دې د تل دپاره هره ورځ د سپېڅلې خېمې د دروازې په خولې کې زما حضور ته وړاندې شي. زه به هلته د اسراییلو د خلکو سره لیدنه او کتنه وکړم او تا سره به خبرې وکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_042.mp3', NULL, 1761758855, 1761758855),
(39822, 'Exodus 29:43', 'Exodus', 29, 43, 'د اسراییلیانو سره به هم هلته لیدنه او کتنه وکړم او هغه ځای به زما د جلال په وسیله پاک شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_043.mp3', NULL, 1761758855, 1761758855),
(39823, 'Exodus 29:44', 'Exodus', 29, 44, 'نو زه به خېمه او د قربانۍ ځای سپېڅلی کړم او هارون او د هغه زامن به د دې دپاره پاک کړم چې د کاهنانو په توګه زما خدمت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_044.mp3', NULL, 1761758855, 1761758855),
(39824, 'Exodus 29:45', 'Exodus', 29, 45, 'بیا به زه د اسراییلو د خلکو په منځ کې اوسېږم او د هغوی خدای به یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_045.mp3', NULL, 1761758855, 1761758855),
(39825, 'Exodus 29:46', 'Exodus', 29, 46, 'هغوی به په دې پوه شي چې زه د هغوی څښتن خدای یم، چا چې هغوی له مصر څخه راوویستل، ترڅو د هغوی په منځ کې واوسېږم. زه د هغوی څښتن خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus29_verse_046.mp3', NULL, 1761758855, 1761758855),
(39826, 'Psalms 20:1', 'Psalms', 20, 1, 'په سختۍ کې دې څښتن کاندي قبوله ستا دعا د یعقوب خدای دې ساتنه وکړي ستا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_001.mp3', NULL, 1761758855, 1761758855),
(39827, 'Psalms 20:2', 'Psalms', 20, 2, 'له خپل سپېڅلي ځای نه دې کومک واستوي تاته د صهیون له غره دې مرسته وکړي ستا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_002.mp3', NULL, 1761758855, 1761758855),
(39828, 'Psalms 20:3', 'Psalms', 20, 3, 'کړي رایادې دې ستا ټولې نذرانې کړي قبولې دې ستا ټولې سوځېدونکې قربانۍ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_003.mp3', NULL, 1761758855, 1761758855),
(39829, 'Psalms 20:4', 'Psalms', 20, 4, 'کړي پوره دې هغه ستا د زړه ارمان او د ستا ټول پلانونه دې کامیاب کړي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_004.mp3', NULL, 1761758855, 1761758855),
(39830, 'Psalms 20:5', 'Psalms', 20, 5, 'بیا به چیغې د خوشحالۍ ستا په بریا کړو د خپل خدای په نوم به جګ کړو بیرغونه کړي څښتن دې ټول قبول ستا سوالونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_005.mp3', NULL, 1761758855, 1761758855),
(39831, 'Psalms 20:6', 'Psalms', 20, 6, 'اوس پوهېږم چې څښتن خپل غوره کړی پاچا ژغوري کړي دعا به یې قبوله له خپل پاک ځایه اسمانه ور به کړي په خپل قدرت هغه ته لویې کامیابۍ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_006.mp3', NULL, 1761758855, 1761758855),
(39832, 'Psalms 20:7', 'Psalms', 20, 7, 'ځینې توکل کوي ګاډیو جنګي خپلو باندې ځینې توکل کړي په اسونو باندې زمونږ توکل دی په نامه د خپل څښتن خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_007.mp3', NULL, 1761758855, 1761758855),
(39833, 'Psalms 20:8', 'Psalms', 20, 8, 'داسې خلک به ښوییږي او رالویږي خو مونږه به پاڅېږو ټینګ ودرېږو به', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_008.mp3', NULL, 1761758855, 1761758855),
(39834, 'Psalms 20:9', 'Psalms', 20, 9, 'ای څښتنه، ته پاچا ته بری ورکړه د کومک دپاره زمونږه فریاد واوره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/psalms20_verse_009.mp3', NULL, 1761758855, 1761758855),
(39835, 'Proverbs 14:1', 'Proverbs', 14, 1, 'هوښیاره ښځه خپل کور ودانوي خو جاهله ښځه خپل کور په خپل لاس ورانوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_001.mp3', NULL, 1761758855, 1761758855),
(39836, 'Proverbs 14:2', 'Proverbs', 14, 2, 'څوک چې له څښتن څخه وېریږي هغه په سمه لار ځي خو څوک چې په غلطو لارو روان وي څښتن سپکوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_002.mp3', NULL, 1761758855, 1761758855),
(39837, 'Proverbs 14:3', 'Proverbs', 14, 3, 'د جاهل له کبرجنې ژبې نه د سزا شنه لښته جوړیږي خو د هوښیارانو د خولې خبرې له هغوی ساتنه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_003.mp3', NULL, 1761758855, 1761758855),
(39838, 'Proverbs 14:4', 'Proverbs', 14, 4, 'چېرته چې څاروي نه وي هلته اخور خالي وي خو د غویي په زور ډېر حاصل لاسته راځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_004.mp3', NULL, 1761758855, 1761758855),
(39839, 'Proverbs 14:5', 'Proverbs', 14, 5, 'رښتینی شاهد هېڅکله دروغ نه وایي خو دروغجن شاهد تل دروغ بادوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_005.mp3', NULL, 1761758855, 1761758855),
(39840, 'Proverbs 14:6', 'Proverbs', 14, 6, 'ملنډې وهونکی حکمت لټوي خو هېڅ نه مومي خو د عقل خاوند علم په اسانۍ لاسته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_006.mp3', NULL, 1761758855, 1761758855),
(39841, 'Proverbs 14:7', 'Proverbs', 14, 7, 'له کم‌عقل نه لېرې لاړ شه ځکه چې له خولې نه به یې علم حاصل نه کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_007.mp3', NULL, 1761758855, 1761758855),
(39842, 'Proverbs 14:8', 'Proverbs', 14, 8, 'ځیرک انسان په خپل حکمت خپله لار پېژني خو د کم‌عقلانو جهالت د ګمراهۍ سبب ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_008.mp3', NULL, 1761758855, 1761758855),
(39843, 'Proverbs 14:9', 'Proverbs', 14, 9, 'جاهل د ګناه د تاوان په نذرانه پورې خاندي خو صادقان د څښتن رضا او خوشحالي غواړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_009.mp3', NULL, 1761758855, 1761758855),
(39844, 'Proverbs 14:10', 'Proverbs', 14, 10, 'یوازې د انسان زړه په خپل خفګان ښه پوهیږي او هېڅوک د هغه په خوشحالۍ کې برخه نه شي اخیستلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_010.mp3', NULL, 1761758855, 1761758855),
(39845, 'Proverbs 14:11', 'Proverbs', 14, 11, 'د بدکارانو کور به وران شي خو د صادقانو خېمه به ودانه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_011.mp3', NULL, 1761758855, 1761758855),
(39846, 'Proverbs 14:12', 'Proverbs', 14, 12, 'د یو انسان په نظر یوه لار سمه ښکاري خو په اخر کې هغه په مرګ پای ته رسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_012.mp3', NULL, 1761758855, 1761758855),
(39847, 'Proverbs 14:13', 'Proverbs', 14, 13, 'حتی په خندا کې زړه هم خفه کیږي او د خوشحالۍ په اخر کې خفګان پاتې کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_013.mp3', NULL, 1761758855, 1761758855),
(39848, 'Proverbs 14:14', 'Proverbs', 14, 14, 'له سمې لارې نه مخ اړوونکی به د خپل کار حاصل وګوري خو نېک انسان به د خپل عمل په مېوه نور هم موړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_014.mp3', NULL, 1761758855, 1761758855),
(39849, 'Proverbs 14:15', 'Proverbs', 14, 15, 'ساده سړی په هرڅه باندې باور کوي خو ځیرک انسان د هر قدم په اخیستلو کې فکر کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_015.mp3', NULL, 1761758855, 1761758855),
(39850, 'Proverbs 14:16', 'Proverbs', 14, 16, 'د حکمت خاوند په احتیاط له بدو نه خپل ځان ساتي خو کم‌عقل انسان په ځان ډاډمن او د هېڅ شی پروا نه لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_016.mp3', NULL, 1761758855, 1761758855),
(39851, 'Proverbs 14:17', 'Proverbs', 14, 17, 'غوسه ناک خلک د جهالت کارونه کوي او له مکرجن انسان نه خلک کرکه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_017.mp3', NULL, 1761758855, 1761758855),
(39852, 'Proverbs 14:18', 'Proverbs', 14, 18, 'جهالت د ساده خلکو په نصیب وي خو د ځیرکه خلکو په سر به د علم تاج وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_018.mp3', NULL, 1761758855, 1761758855),
(39853, 'Proverbs 14:19', 'Proverbs', 14, 19, 'بدکاران به د ښو خلکو په مخکې سر ټیټې شي او شر اچوونکي به د نېکانو په دروازو کې په ګونډو شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_019.mp3', NULL, 1761758855, 1761758855),
(39854, 'Proverbs 14:20', 'Proverbs', 14, 20, 'د مسکین انسان نه خپل ګاونډي هم کرکه کوي خو شتمن انسان ډېر دوستان لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_020.mp3', NULL, 1761758855, 1761758855),
(39855, 'Proverbs 14:21', 'Proverbs', 14, 21, 'څوک چې خپل ګاونډي سپک ګڼي نو ګناه کوي او بختور دی هغه څوک چې په عاجزانو رحم کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_021.mp3', NULL, 1761758855, 1761758855),
(39856, 'Proverbs 14:22', 'Proverbs', 14, 22, 'څوک چې بدې ارادې لري بې‌لارې کیږي خو څوک چې نېکې ارادې لري نو مینه او وفا یې په برخه کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_022.mp3', NULL, 1761758855, 1761758855),
(39857, 'Proverbs 14:23', 'Proverbs', 14, 23, 'ټول سخت کارونه د ابادۍ سبب ګرځي خو تشې خبرې حتمي نېستي راولي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_023.mp3', NULL, 1761758855, 1761758855),
(39858, 'Proverbs 14:24', 'Proverbs', 14, 24, 'د هوښیارانو دولت د هغوی د سر تاج دی خو د کم‌عقلانو ناپوهي د هغوی جهالت دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_024.mp3', NULL, 1761758855, 1761758855),
(39859, 'Proverbs 14:25', 'Proverbs', 14, 25, 'رښتینی شاهد د خلکو ژوند ژغوري خو د دروغجن له خولې نه د ټګۍ خبرې راوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_025.mp3', NULL, 1761758855, 1761758855),
(39860, 'Proverbs 14:26', 'Proverbs', 14, 26, 'له څښتن څخه وېره د انسان دپاره د امن ټینګه کلا ده او د هغه د اولادونو دپاره کلکه پناه ګاه ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_026.mp3', NULL, 1761758855, 1761758855),
(39861, 'Proverbs 14:27', 'Proverbs', 14, 27, 'له څښتن څخه وېره د ژوند سرچینه ده چې انسان د مرګ له دامونو څخه ژغوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_027.mp3', NULL, 1761758855, 1761758855),
(39862, 'Proverbs 14:28', 'Proverbs', 14, 28, 'د پاچا شان او شوکت په ډېرو خلکو جوړ وي خو بې‌ولسه مشر له تباهۍ سره مخامخ کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_028.mp3', NULL, 1761758855, 1761758855),
(39863, 'Proverbs 14:29', 'Proverbs', 14, 29, 'څوک چې زر نه په قهریږي د ډېرې پوهې خاوند وي خو غوسه ناک سړی خپل جهالت ښکاره کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_029.mp3', NULL, 1761758855, 1761758855),
(39864, 'Proverbs 14:30', 'Proverbs', 14, 30, 'ارام فکر بدن ته روغتیا ورکوي خو کینه هډوکي وراسته کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_030.mp3', NULL, 1761758855, 1761758855),
(39865, 'Proverbs 14:31', 'Proverbs', 14, 31, 'څوک چې په غریبانو ظلم کوي نو د هغوی د خالق سپکاوی کوي خو څوک چې په مظلومانو رحم کوي نو د خالق درناوی کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_031.mp3', NULL, 1761758855, 1761758855),
(39866, 'Proverbs 14:32', 'Proverbs', 14, 32, 'بدکاره انسان په خپلو عملونو ځان تباه کوي خو نېک انسان د مرګ په خوله کې هم پناه اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_032.mp3', NULL, 1761758855, 1761758855),
(39867, 'Proverbs 14:33', 'Proverbs', 14, 33, 'حکمت د عقلمن انسان په زړه کې تلپاتې وي او د کم‌عقلانو په منځ کې هم خپل ځان څرګندوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_033.mp3', NULL, 1761758855, 1761758855),
(39868, 'Proverbs 14:34', 'Proverbs', 14, 34, 'په صداقت سره یو قوم سرلوړی کیږي خو ګناه د هغوی د رسوایۍ سبب ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_034.mp3', NULL, 1761758855, 1761758855),
(39869, 'Proverbs 14:35', 'Proverbs', 14, 35, 'پاچا د هوښیار خدمتګار څخه خوشحالیږي خو څوک چې د شرم کارونه کوي د هغه د قهر سبب کیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs14_verse_035.mp3', NULL, 1761758855, 1761758855),
(39870, 'Ezra 10:1', 'Ezra', 10, 1, 'په داسې حال کې چې عزرا د خدای د کور په مخکې په دعا کې په سجده پرېوت، هغه ژړل او د قوم په ګناهونو باندې یې اقرار کاوه. د اسراییلیانو یوه ډېره لویه ډله چې سړي، ښځې او ماشومان په کې وو د هغه په شاوخوا راټول شول او ډېر سخت یې وژړل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_001.mp3', NULL, 1761758855, 1761758855),
(39871, 'Ezra 10:2', 'Ezra', 10, 2, 'بیا شکنیا د یحییل زوی چې د عیلام د طایفې څخه ؤ، عزرا ته وویل: «مونږ د پردیو قومونو د ښځو سره په ودونو کولو د خپل خدای سره خپله وفاداري ماته کړه، خو بیاهم د اسراییلو د قوم دپاره هیله شته.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_002.mp3', NULL, 1761758855, 1761758855),
(39872, 'Ezra 10:3', 'Ezra', 10, 3, 'راځئ اوس د خپل خدای سره لوظ وکړو چې مونږ به دا ټولې ښځې او د هغوی اولادونه وشړو. مونږ به دا کار ستاسو او د هغو خلکو د مشورې سره سم چې د خدای حکم ته درناوی کوي، وکړو. مونږ به د خدای د شریعت د غوښتنې سره سم عمل وکړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_003.mp3', NULL, 1761758855, 1761758855),
(39873, 'Ezra 10:4', 'Ezra', 10, 4, 'راپاڅېږه، دا ستا مسوولیت دی. مونږ ستا شاته ولاړ یو، نو په زړورتیا سره دا کار وکړه.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_004.mp3', NULL, 1761758855, 1761758855),
(39874, 'Ezra 10:5', 'Ezra', 10, 5, 'نو عزرا د کاهنانو مشرانو، لاویانو او نورو اسراییلیانو ته قسم ورکړ چې دوی به د شکنیا د مشورې څخه پیروي وکړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_005.mp3', NULL, 1761758855, 1761758855),
(39875, 'Ezra 10:6', 'Ezra', 10, 6, 'بیا عزرا د خدای د کور د مخې نه د الیاشیب د زوی یهوحانان د خوب کوټې ته ورغی او هلته یې شپه تېره کړه. هغه نه څه وخوړل او نه یې څه وڅښل، ځکه چې د جلاوطنو خلکو په بې وفایۍ باندې یې ویر کاوه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_006.mp3', NULL, 1761758855, 1761758855),
(39876, 'Ezra 10:9', 'Ezra', 10, 9, 'په درېو ورځو کې، د نهمې میاشتې په شلمه ورځ هغه ټول خلک چې د یهودا او بنیامین په سیمو کې اوسېدل، اورشلیم ته راغلل او د خدای د کور په حوېلۍ کې سره راټول شول. هغوی لړزېدل، ځکه چې له یوې خوا دا یوه ډېره مهمه غونډه وه او بله دا چې هلته په سخت باران کې ناست وو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_009.mp3', NULL, 1761758855, 1761758855),
(39877, 'Ezra 10:10', 'Ezra', 10, 10, 'عزرا کاهن پاڅېد او هغوی ته یې وویل: «تاسو بې وفایي کړې ده او د پردیو قومونو د ښځو سره په ودونو کولو باندې مو د اسراییلو ګناهونه زیات کړي دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_010.mp3', NULL, 1761758855, 1761758855),
(39878, 'Ezra 10:11', 'Ezra', 10, 11, 'نو اوس د خپلو نیکونو د څښتن خدای په مخکې د خپلو ګناهونو اقرار وکړئ او هغه کار وکړئ چې هغه ورباندې خوشحالیږي. د هغو پردیو خلکو نه چې زمونږ په خاوره کې اوسیږي، بېل شئ او د پردیو ښځو څخه ځانونه خلاص کړئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_011.mp3', NULL, 1761758855, 1761758855),
(39879, 'Ezra 10:12', 'Ezra', 10, 12, 'ټولو خلکو په لوړ اواز ځواب ورکړ: «تاسو په حقه خبره کوئ. څنګه چې تاسو وایئ هماغسې باید وکړو.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_012.mp3', NULL, 1761758855, 1761758855),
(39880, 'Ezra 10:13', 'Ezra', 10, 13, 'خو هغوی زیاته کړه: «دلته ډېر زیات خلک دي او سخت باران وریږي. مونږ نه شو کولای چې دلته دباندې ودرېږو. دا داسې کار نه دی چې په یوې یا دوه ورځو کې سرته ورسیږي، ځکه چې په مونږ کې ډېر خلک په دې ګناه اخته دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_013.mp3', NULL, 1761758855, 1761758855),
(39881, 'Ezra 10:14', 'Ezra', 10, 14, 'پرېږدئ چې زمونږ مشران په اورشلیم کې پاتې شي او د دې موضوع مسوولیت په غاړه واخلي. بیا هغه څوک چې ښځه یې د پردي قوم څخه وي، هغه دې د خپل ښار د مشرانو او قاضیانو سره یوځای په ټاکلي وخت راشي. په دې ډول به د دې موضوع په هکله زمونږ د خدای سخت قهر سوړ شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_014.mp3', NULL, 1761758855, 1761758855),
(39882, 'Ezra 10:15', 'Ezra', 10, 15, 'د عساهیل د زوی یوناتان او د تقوه د زوی یحزیا او د هغوی د ملاتړ کوونکو یعنې مشلام او لاوي شبتای څخه پرته نور هېچا د دې پلان سره مخالفت ونه کړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_015.mp3', NULL, 1761758855, 1761758855),
(39883, 'Ezra 10:16', 'Ezra', 10, 16, 'راستانه شویو جلاوطنو خلکو دا پلان ومنلو، نو عزرا کاهن د طایفو د مشرانو له منځ نه کسان وټاکل او د هغو نومونه یې ولیکل. د لسمې میاشتې په لومړۍ ورځ هغوی کښېناستل او خپله څېړنه یې پیل کړه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_016.mp3', NULL, 1761758855, 1761758855),
(39884, 'Ezra 10:17', 'Ezra', 10, 17, 'او هغوی د لومړۍ میاشتې په لومړۍ ورځ د هغو خلکو ټولې قضیې وڅېړلې چې د پردي قوم څخه یې ښځې کړې وې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_017.mp3', NULL, 1761758855, 1761758855),
(39885, 'Ezra 10:18', 'Ezra', 10, 18, 'د هغو خلکو لست چې د پردي قوم څخه یې ښځې کړې وې: د طایفو له مخې د کاهنانو لست: د یوصاداق د زوی یشوع او د هغه د ورونو د طایفې څخه: معسیا، الیعازر، یاریب او جدلیا.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_018.mp3', NULL, 1761758855, 1761758855),
(39886, 'Ezra 10:19', 'Ezra', 10, 19, 'هغوی لوظ وکړ چې خپلې ښځې به وشړي. د خپلو ګناهونو په خاطر یې یو پسه د قربانۍ په توګه وړاندې کړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_019.mp3', NULL, 1761758855, 1761758855),
(39887, 'Ezra 10:20', 'Ezra', 10, 20, 'د یمیر له طایفې څخه: حناني او زبدیا.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_020.mp3', NULL, 1761758855, 1761758855),
(39888, 'Ezra 10:21', 'Ezra', 10, 21, 'د حاریم له طایفې څخه: معسیا، الیاس، شمعیه، یحییل او عزیا.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_021.mp3', NULL, 1761758855, 1761758855),
(39889, 'Ezra 10:22', 'Ezra', 10, 22, 'د فشحور له طایفې څخه: الیوعینای، معسیا، اسماعیل، نتنییل، یوزاباد او العاسه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_022.mp3', NULL, 1761758855, 1761758855),
(39890, 'Ezra 10:23', 'Ezra', 10, 23, 'د لاویانو څخه: یوزاباد، شمعي، قلایا (چې د قلیطا په نوم هم یادیږي)، فتحیا، یهودا او الیعازر.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_023.mp3', NULL, 1761758855, 1761758855),
(39891, 'Ezra 10:24', 'Ezra', 10, 24, 'د سندرغاړو څخه: الیاشیب. د خدای د کور له ساتونکو څخه: شلوم، طالم او اوري.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_024.mp3', NULL, 1761758855, 1761758855),
(39892, 'Ezra 10:25', 'Ezra', 10, 25, 'د نورو اسراییلیانو څخه: د فروش له طایفې څخه: رمیا، یزیا، ملکیا، میامین، العازار، ملکیا او بنایاه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_025.mp3', NULL, 1761758855, 1761758855),
(39893, 'Ezra 10:26', 'Ezra', 10, 26, 'د عیلام له طایفې څخه: متنیا، زکریا، یحییل، عبدي، یریموت او الیاس.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_026.mp3', NULL, 1761758855, 1761758855),
(39894, 'Ezra 10:27', 'Ezra', 10, 27, 'د زتو له طایفې څخه: الیوعینای، الیاشیب، متنیا، یریموت، زاباد او عزیزا.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_027.mp3', NULL, 1761758855, 1761758855),
(39895, 'Ezra 10:28', 'Ezra', 10, 28, 'د ببای له طایفې څخه: یهوحانان، حننیا، زبای او عتلای.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_028.mp3', NULL, 1761758855, 1761758855),
(39896, 'Ezra 10:29', 'Ezra', 10, 29, 'د باني له طایفې څخه: مشلام، ملوک، عدایا، یاشوب، شیال او یریموت.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_029.mp3', NULL, 1761758855, 1761758855),
(39897, 'Ezra 10:30', 'Ezra', 10, 30, 'د فحت موآب له طایفې څخه: عدنا، کلال، بنایاه، معسیا، متنیا، بزل ییل، بنوي او منسي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_030.mp3', NULL, 1761758855, 1761758855),
(39898, 'Ezra 10:33', 'Ezra', 10, 33, 'د حاشوم له طایفې څخه: متنای، متاته، زاباد، الیفلط، یریمای، منسي او شمعي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_033.mp3', NULL, 1761758855, 1761758855),
(39899, 'Ezra 10:43', 'Ezra', 10, 43, 'د نبو له طایفې څخه: یعییل، متتیا، زاباد، زبینا، یدو، یوییل او بنایاه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_043.mp3', NULL, 1761758855, 1761758855),
(39900, 'Ezra 10:44', 'Ezra', 10, 44, 'دې ټولو خلکو د پردیو قومونو څخه ښځې کړې وې او ځینو سړیو د دې ښځو څخه ماشومان هم لرل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/ezra10_verse_044.mp3', NULL, 1761758855, 1761758855),
(39901, 'Jeremiah 42:1', 'Jeremiah', 42, 1, 'نو بيا د فوج ټول جنګى مشران، يوحانان د قريح زوئ او يزنياه د هوسعياه زوئ، او د وړو نه تر لويو پورې ټول خلق', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_001.mp3', NULL, 1761758855, 1761758855),
(39902, 'Jeremiah 42:2', 'Jeremiah', 42, 2, 'يرمياه نبى ته راغلل او ورته يې ووئيل، ”مونږ ستا مِنت کوُو چې زمونږ دپاره د مالِک خُدائ ستا مقدس خُدائ نه دُعا وغواړه، کوم چې پاتې شوى کسان يُو. لکه څنګه چې تۀ وينې چې د مخکښې په مقابل کښې اوس مونږ ډېر لږ يُو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_002.mp3', NULL, 1761758855, 1761758855),
(39903, 'Jeremiah 42:3', 'Jeremiah', 42, 3, 'زمونږ دپاره دُعا وکړه چې مالِک خُدائ زمونږ خُدائ پاک مونږ ته لارښودنه وکړى چې څۀ وکړُو او چرته لاړ شُو.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_003.mp3', NULL, 1761758855, 1761758855),
(39904, 'Jeremiah 42:4', 'Jeremiah', 42, 4, 'يرمياه هغوئ ته په جواب کښې وفرمائيل چې، ”صحيح ده، زۀ به مالِک خُدائ ستاسو خُدائ پاک ته هم هغه شان دُعا وکړم لکه څنګه چې تاسو ما ته خواست وکړو، او زۀ به هر هغه څۀ تاسو ته ووايم چې هغه څۀ ما ته وفرمائى. زۀ به ستاسو نه هيڅ څيز هم نۀ پټوم.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_004.mp3', NULL, 1761758855, 1761758855),
(39905, 'Jeremiah 42:5', 'Jeremiah', 42, 5, 'بيا هغوئ يرمياه ته ووئيل، ”نو بيا دې مالِک خُدائ په مونږ په دې خبره رښتينے او وفادار ګواه وى کۀ چرې مونږ ستا په هغه ټولو خبرو عمل ونۀ کړو کومې چې مالِک خُدائ ستا خُدائ پاک زمونږ دپاره تا ته فرمائيلى دى چې تۀ يې مونږ ته بيان کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_005.mp3', NULL, 1761758855, 1761758855),
(39906, 'Jeremiah 42:6', 'Jeremiah', 42, 6, 'کۀ هغه کلام زمونږ خوښ شى او کۀ خوښ نۀ شى، مونږ به د مالِک خُدائ د کلام پيروى کوُو چا ته چې تۀ مونږ د خپل خواست دپاره لېږې. ځکه کۀ چرې مونږ د هغۀ د کلام پيروى وکړُو، نو هر څۀ به زمونږ دپاره د خير وى.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_006.mp3', NULL, 1761758855, 1761758855),
(39907, 'Jeremiah 42:7', 'Jeremiah', 42, 7, 'لس ورځې وروستو د مالِک خُدائ کلام په يرمياه نازل شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_007.mp3', NULL, 1761758855, 1761758855),
(39908, 'Jeremiah 42:8', 'Jeremiah', 42, 8, 'نو بيا هغۀ يوحنان د قريح زوئ او نورو فوجى آفسرانو ته، او ټولو خلقو لويو او وړو ته آواز وکړو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_008.mp3', NULL, 1761758855, 1761758855),
(39909, 'Jeremiah 42:9', 'Jeremiah', 42, 9, 'هغۀ هغوئ ته وفرمائيل چې، ”تاسو زۀ مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک ته د خپل درخواست سره ولېږلم، هغه داسې فرمائى چې،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_009.mp3', NULL, 1761758855, 1761758855),
(39910, 'Jeremiah 42:10', 'Jeremiah', 42, 10, 'کۀ تاسو په دې مُلک کښې پاتې شئ، نو زۀ به تاسو بيا آباد کړم او نۀ به مو خرابوم، زۀ به تاسو وکرم او تاسو به د بېخ نه نۀ وباسم. زۀ ستاسو په هغه افت کوم چې ما په تاسو نازل کړے دے پښېمانه يم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_010.mp3', NULL, 1761758855, 1761758855),
(39911, 'Jeremiah 42:11', 'Jeremiah', 42, 11, 'مالِک خُدائ فرمائى چې، د بابل بادشاه نه نور مۀ يرېږئ. ځکه چې زۀ تاسو سره يم او د هغۀ نه به مو بچ کړم او د هغۀ د لاس نه به خلاصون درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_011.mp3', NULL, 1761758855, 1761758855),
(39912, 'Jeremiah 42:12', 'Jeremiah', 42, 12, 'زۀ به په تاسو دا رحم وکړم چې هغه به درباندې مهربانه کړم، نو بيا به هغه تاسو ته په خپل مُلک کښې د پاتې کېدو اجازت درکړى.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_012.mp3', NULL, 1761758855, 1761758855),
(39913, 'Jeremiah 42:13', 'Jeremiah', 42, 13, 'خو کۀ چرې تاسو د مالِک خُدائ ستاسو خُدائ پاک د دې پېغام نه اِنکار وکړئ، او کۀ چرې تاسو ووايئ چې، نه، مونږ به دلته نۀ پاتې کيږُو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_013.mp3', NULL, 1761758855, 1761758855),
(39914, 'Jeremiah 42:14', 'Jeremiah', 42, 14, 'خو د دې په ځائ به مِصر ته لاړ شُو، چرته چې به مونږ د جنګونو، د جنګ د بيګل آوازونو او قحط نه آزاد شُو،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_014.mp3', NULL, 1761758855, 1761758855),
(39915, 'Jeremiah 42:15', 'Jeremiah', 42, 15, 'نو بيا تاسو د مالِک خُدائ پېغام د يهوداه پاتې خلقو ته واوروئ. مالِک خُدائ ربُ الافواج داسې فرمائى چې، کۀ چرې تاسو دا ضرور غوره کړئ چې مِصر ته لاړ شئ او هلته پاتې شئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_015.mp3', NULL, 1761758855, 1761758855),
(39916, 'Jeremiah 42:16', 'Jeremiah', 42, 16, 'د کوم جنګ او قحط نه چې تاسو يرېږئ نو هم هغه به تاسو راګېر کړى، او تاسو به هلته مړۀ شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_016.mp3', NULL, 1761758855, 1761758855),
(39917, 'Jeremiah 42:17', 'Jeremiah', 42, 17, 'نو په حقيقت کښې چې څوک هم په تلو کلک ولاړ وى او هلته د اوسېدو اراده لرى نو هغه به په جنګ، قحط او په وبا مړ شى. په تاسو کښې به يو کس هم د هغه افت نه ونۀ تښتى کوم چې زۀ په تاسو باندې هلته راولم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_017.mp3', NULL, 1761758855, 1761758855),
(39918, 'Jeremiah 42:18', 'Jeremiah', 42, 18, 'مالِک خُدائ ربُ الافواج د بنى اِسرائيلو خُدائ پاک فرمائى، لکه څنګه چې زما قهر او غضب د يروشلم په خلقو نازل شوے وو، نو کۀ تاسو مِصر ته لاړئ نو زما غضب به په تاسو هم نازل شى. نو ستاسو نوم به د تل دپاره د لعنت، يرې او مسخرې په توګه اخستلے کيږى او خپل مُلک به دوباره ونۀ وينئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_018.mp3', NULL, 1761758855, 1761758855),
(39919, 'Jeremiah 42:19', 'Jeremiah', 42, 19, 'اے د يهوداه ژوندى پاتې شوى خلقو، مالِک خُدائ تاسو ته فرمائيلى دى چې مِصر ته مۀ ځئ. زۀ چې دا خبردارے نن تاسو ته درکوم دا مۀ هېروئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_019.mp3', NULL, 1761758855, 1761758855),
(39920, 'Jeremiah 42:20', 'Jeremiah', 42, 20, 'ځکه تاسو چې کله زۀ مالِک خُدائ ته د خواست کولو دپاره ولېږلم نو تاسو غټه غلطى وکړه، ځکه چې تاسو ووئيل، د څۀ چې مالِک خُدائ مونږ ته حکم کړے دے هغه مونږ ته ووايه، مونږ به په هغې باندې پوره عمل کوُو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_020.mp3', NULL, 1761758855, 1761758855),
(39921, 'Jeremiah 42:21', 'Jeremiah', 42, 21, 'خو ما تاسو ته نن د هغۀ حکم واورولو، خو تاسو تر اوسه پورې د مالِک خُدائ د هغه پېغام پيروى نۀ کوئ د کوم دپاره چې تاسو زۀ استولے وم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_021.mp3', NULL, 1761758855, 1761758855),
(39922, 'Jeremiah 42:22', 'Jeremiah', 42, 22, 'نو اوس په دې خبره باندې يقين ساتئ چې، تاسو چې کوم ځائ ته تلل او اوسېدل غواړئ نو تاسو به هلته په جنګ، قحط او وبا مړۀ شئ.“', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/jeremiah42_verse_022.mp3', NULL, 1761758855, 1761758855),
(39923, 'Proverbs 23:1', 'Proverbs', 23, 1, 'کله چې ته د اختیار د خاوند سره ډوډۍ خوړلو ته کښېنې نو ښه فکر وکړه چې ستا په مخکې څه دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_001.mp3', NULL, 1761758855, 1761758855),
(39924, 'Proverbs 23:2', 'Proverbs', 23, 2, 'که ته ډېر خېټور انسان هم یې نو په خپله مرۍ دې چاړه کېږده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_002.mp3', NULL, 1761758855, 1761758855),
(39925, 'Proverbs 23:3', 'Proverbs', 23, 3, 'او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره ځکه چې دا خوراک ستا د چل او تېرایستلو دپاره دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_003.mp3', NULL, 1761758855, 1761758855),
(39926, 'Proverbs 23:4', 'Proverbs', 23, 4, 'د شتمنۍ د لاسته راوړلو دپاره ځان مه ستومانه کوه هوښیار اوسه او د داسې کار نه ځان وساته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_004.mp3', NULL, 1761758855, 1761758855),
(39927, 'Proverbs 23:5', 'Proverbs', 23, 5, 'ځکه ټوله شتمني به دې ناڅاپه د عقاب په شان وزرې پرانیزي او د سترګو په رپ کې به اسمان ته والوزي او ختمه به شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_005.mp3', NULL, 1761758855, 1761758855),
(39928, 'Proverbs 23:6', 'Proverbs', 23, 6, 'د شوم سړي ډوډۍ مه خوره او د خوندورو خوړو نه یې د یوې مړۍ تمه هم مه لره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_006.mp3', NULL, 1761758855, 1761758855),
(39929, 'Proverbs 23:7', 'Proverbs', 23, 7, 'ځکه هرڅه چې ته خورې هغه یې حسابوي او درته وایي چې راځه، ما سره وخوره او وڅښه! خو هغه د زړه له کومي دا خبره نه کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_007.mp3', NULL, 1761758855, 1761758855),
(39930, 'Proverbs 23:8', 'Proverbs', 23, 8, 'کومه مړۍ چې دې خوړلې ده هغه به بېرته وګرځوې او ټولې خوږې خبرې به دې له منځه لاړې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_008.mp3', NULL, 1761758855, 1761758855),
(39931, 'Proverbs 23:9', 'Proverbs', 23, 9, 'کم‌عقل سړي ته هېڅکله نصیحت مه کوه ځکه هغه ستا د هوښیارۍ کلام ته په سپکه سترګه ګوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_009.mp3', NULL, 1761758855, 1761758855),
(39932, 'Proverbs 23:10', 'Proverbs', 23, 10, 'د ځمکې د حد پخوانۍ تیږه مه بېځایه کوه او د یتیمانو ځمکه په ظلم مه نیسه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_010.mp3', NULL, 1761758855, 1761758855),
(39933, 'Proverbs 23:11', 'Proverbs', 23, 11, 'ځکه چې د دوی ساتونکی زورور دی او هغه به د دوی حق ستا نه واخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_011.mp3', NULL, 1761758855, 1761758855),
(39934, 'Proverbs 23:12', 'Proverbs', 23, 12, 'د زړه له کومي نصیحت قبول کړه او د علم او پوهې خبرو ته غوږ ونیسه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_012.mp3', NULL, 1761758855, 1761758855),
(39935, 'Proverbs 23:13', 'Proverbs', 23, 13, 'د خپل زوی په اصلاح کې لټي مه کوه. که ته یې په لښته ووهې نو مړ به نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_013.mp3', NULL, 1761758855, 1761758855),
(39936, 'Proverbs 23:14', 'Proverbs', 23, 14, 'نو هغه ته په لښته سزا ورکړه چې روح یې د قبر نه وژغورل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_014.mp3', NULL, 1761758855, 1761758855),
(39937, 'Proverbs 23:15', 'Proverbs', 23, 15, 'نو ای زما زویه! که ته د حکمت خاوند شې نو زړه به مې ډېر خوشحاله شي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_015.mp3', NULL, 1761758855, 1761758855),
(39938, 'Proverbs 23:16', 'Proverbs', 23, 16, 'او کله چې ته رښتینې خبرې کوې نو زړه مې د خوشحالۍ نه ټوپونه وهي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_016.mp3', NULL, 1761758855, 1761758855),
(39939, 'Proverbs 23:17', 'Proverbs', 23, 17, 'خپل زړه مه پرېږده چې له ګناهکارانو سره بخیلي وکړي بلکې هر وخت د څښتن نه په وېره کې اوسه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_017.mp3', NULL, 1761758855, 1761758855),
(39940, 'Proverbs 23:18', 'Proverbs', 23, 18, 'نو باور ولره چې په راتلونکې کې ستا دپاره پوره هیله ده او هېڅکله به ستا هیلې له منځه لاړې نه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_018.mp3', NULL, 1761758855, 1761758855),
(39941, 'Proverbs 23:19', 'Proverbs', 23, 19, 'نو ای زما زویه! ماته غوږ ونیسه او هوښیار اوسه او خپل زړه دې په سمه لار باندې ټینګ وساته.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_019.mp3', NULL, 1761758855, 1761758855),
(39942, 'Proverbs 23:20', 'Proverbs', 23, 20, 'د شرابیانو سره ناسته ولاړه مه کوه او د خېټورو خلکو سره چې ډېره غوښه خوښوي مه ګرځه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_020.mp3', NULL, 1761758855, 1761758855),
(39943, 'Proverbs 23:21', 'Proverbs', 23, 21, 'ځکه چې شرابیان او خېټور خلک به خوار شي او ډېر خوب به هغوی ته زاړه کالي واغوندي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_021.mp3', NULL, 1761758855, 1761758855),
(39944, 'Proverbs 23:22', 'Proverbs', 23, 22, 'د خپل پلار خبرو ته دې غوږ ونیسه چې تاته یې ژوند درکړی دی او د خپلې بوډۍ مور سپینو ویښتو ته په سپکه سترګه مه ګوره.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_022.mp3', NULL, 1761758855, 1761758855),
(39945, 'Proverbs 23:23', 'Proverbs', 23, 23, 'حقیقت حاصل کړه او هغه په بیه واخله او د پیسو په خاطر حکمت، نصیحت او عقل مه خرڅوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_023.mp3', NULL, 1761758855, 1761758855),
(39946, 'Proverbs 23:24', 'Proverbs', 23, 24, 'د نېک سړي پلار ډېر خوشحاله وي او هوښیار زوی د خپل پلار دپاره د خوښۍ سبب وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_024.mp3', NULL, 1761758855, 1761758855),
(39947, 'Proverbs 23:25', 'Proverbs', 23, 25, 'پرېږده چې ستا مور او پلار په تا خوښ اوسي او مور دې چې ته یې زېږولی یې خوشحالي وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_025.mp3', NULL, 1761758855, 1761758855),
(39948, 'Proverbs 23:26', 'Proverbs', 23, 26, 'نو ای زما زویه! خپل زړه دې ماته راکړه او په ډېره خوشحالۍ زما په لارو قدم کېږده', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_026.mp3', NULL, 1761758855, 1761758855),
(39949, 'Proverbs 23:27', 'Proverbs', 23, 27, 'ځکه زناکاره ښځه ستا دپاره ژوره کنده ده او هغه د یوې تنګې څاه په څېر ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_027.mp3', NULL, 1761758855, 1761758855),
(39950, 'Proverbs 23:28', 'Proverbs', 23, 28, 'هغه د یو داړه مار په شان په کمین کې ناسته وي او د خلکو ترمنځ خیانت زیاتوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_028.mp3', NULL, 1761758855, 1761758855),
(39951, 'Proverbs 23:29', 'Proverbs', 23, 29, 'څوک دی چې افسوس کوي او څوک دی چې غمجن دی؟ څوک دی چې شخړې جوړوي او څوک دی چې شکایت کوي؟ څوک دی چې ناحقه زخمونه لري او څوک دی چې سترګې یې سرې دي؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_029.mp3', NULL, 1761758855, 1761758855),
(39952, 'Proverbs 23:30', 'Proverbs', 23, 30, 'دا هغه څوک دي چې تل شراب خوري او هر ډول شراب څښي او تل ورپسې ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_030.mp3', NULL, 1761758855, 1761758855),
(39953, 'Proverbs 23:31', 'Proverbs', 23, 31, 'د شرابو سور رنګ ته په شوق مه ګوره چې په پیاله کې ځلیږي او په اسانۍ له ستوني نه تېریږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_031.mp3', NULL, 1761758855, 1761758855),
(39954, 'Proverbs 23:32', 'Proverbs', 23, 32, 'خو په اخر کې د مار په شان چیچل کوي او د منګري په څېر د زهرو ډک وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_032.mp3', NULL, 1761758855, 1761758855),
(39955, 'Proverbs 23:33', 'Proverbs', 23, 33, 'ستا سترګې به هر ډول حیرانوونکي شیان ویني او په زړه کې به دې ګډې وډې خبرې ګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_033.mp3', NULL, 1761758855, 1761758855),
(39956, 'Proverbs 23:34', 'Proverbs', 23, 34, 'د هغه چا په شان به شې چې د دریاب دپاسه خوب کوي او د څپو په سر پروت ټالۍ وهي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_034.mp3', NULL, 1761758855, 1761758855),
(39957, 'Proverbs 23:35', 'Proverbs', 23, 35, 'ته به ووایې: «هغوی زه ووهلم خو زه دردمند نه شوم. زه یې وټکولم خو پوه پرې نه شوم. کله به راویښ شم چې د شرابو یوه بله پیاله وڅښم؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/proverbs23_verse_035.mp3', NULL, 1761758855, 1761758855),
(39958, 'Genesis 7:1', 'Genesis', 7, 1, 'څښتن نوح ته وویل: «د خپلې ټولې کورنۍ سره کشتۍ ته ننوځه، ځکه چې په ټوله دنیا کې مې یوازېنی سړی ته ولیدلې چې نېک کارونه کوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_001.mp3', NULL, 1761758855, 1761758855),
(39959, 'Genesis 7:2', 'Genesis', 7, 2, 'د ټولو پاکو حیواناتو څخه اووه، اووه جوړې نر او ښځه او د ناپاکو حیواناتو څخه یوه یوه جوړه نر او ښځه د ځان سره واخله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_002.mp3', NULL, 1761758855, 1761758855),
(39960, 'Genesis 7:3', 'Genesis', 7, 3, 'او همدارنګه د هر ډول مرغانو څخه اووه جوړې نر او ښځه واخله، ترڅو د هغوی نسل د ځمکې په مخ باندې ژوندی پاتې شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_003.mp3', NULL, 1761758855, 1761758855),
(39961, 'Genesis 7:4', 'Genesis', 7, 4, 'ځکه چې زه به له اووه ورځو وروسته په ځمکه باندې څلوېښت شپې او څلوېښت ورځې باران ووروم او ټول ژوندي مخلوقات چې ما جوړ کړي دي، هغه به له منځه یوسم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_004.mp3', NULL, 1761758855, 1761758855),
(39962, 'Genesis 7:5', 'Genesis', 7, 5, 'نوح هغه ټول کارونه سرته ورسول چې څښتن ورته حکم کړی ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_005.mp3', NULL, 1761758855, 1761758855),
(39963, 'Genesis 7:6', 'Genesis', 7, 6, 'نوح د شپږ سوه کالو په عمر ؤ چې په ځمکه باندې سېلاب راغی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_006.mp3', NULL, 1761758855, 1761758855),
(39964, 'Genesis 7:7', 'Genesis', 7, 7, 'نوح او د هغه زامن او ښځه او د زامنو ښځې یې د سېلاب څخه د ژغورلو په خاطر کشتۍ ته ننوتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_007.mp3', NULL, 1761758855, 1761758855),
(39965, 'Genesis 7:10', 'Genesis', 7, 10, 'نو اووه ورځې وروسته سېلاب راغی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_010.mp3', NULL, 1761758855, 1761758855),
(39966, 'Genesis 7:11', 'Genesis', 7, 11, 'نوح شپږ سوه کلن ؤ او د دوهمې میاشتې په اوولسمه ورځ د ځمکې لاندې ژورو ځایونو څخه اوبه راووتلې او د اسمان دروازې خلاصې شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_011.mp3', NULL, 1761758855, 1761758855),
(39967, 'Genesis 7:12', 'Genesis', 7, 12, 'څلوېښت شپې او څلوېښت ورځې په ځمکه باندې باران واورېده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_012.mp3', NULL, 1761758855, 1761758855),
(39968, 'Genesis 7:13', 'Genesis', 7, 13, 'په هماغه ورځ نوح او د هغه زامن، سام، حام او یافت او د نوح ښځه او د هغه د زامنو درې ښځې کشتۍ ته ورننوتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_013.mp3', NULL, 1761758855, 1761758855),
(39969, 'Genesis 7:14', 'Genesis', 7, 14, 'د هغوی سره د هر ډول کورني او وحشي حیواناتو، خزندو او د هر ډول مرغانو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_014.mp3', NULL, 1761758855, 1761758855),
(39970, 'Genesis 7:15', 'Genesis', 7, 15, 'یعنې د ژوندیو مخلوقاتو څخه یوه یوه جوړه نوح ته راغله او کشتۍ ته ننوتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_015.mp3', NULL, 1761758855, 1761758855),
(39971, 'Genesis 7:16', 'Genesis', 7, 16, 'لکه څنګه چې خدای حکم کړی ؤ، هغوی د هر ژوندي مخلوق څخه نر او ښځه ننوتل. نو څښتن هغوی پسې دروازه وتړله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_016.mp3', NULL, 1761758855, 1761758855),
(39972, 'Genesis 7:17', 'Genesis', 7, 17, 'باران څلوېښت ورځې واورېد او اوبه د ځمکې په مخ زیاتې شوې او کشتۍ یې پورته کړه او د ځمکې څخه اوچته شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_017.mp3', NULL, 1761758855, 1761758855),
(39973, 'Genesis 7:18', 'Genesis', 7, 18, 'اوبه ډېرې پورته شوې او کشتۍ د اوبو په مخ باندې روانه شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_018.mp3', NULL, 1761758855, 1761758855),
(39974, 'Genesis 7:19', 'Genesis', 7, 19, 'اوبه تر دې اندازې زیاتې شوې چې د اسمان لاندې ټول لوړ غرونه یې پټ کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_019.mp3', NULL, 1761758855, 1761758855),
(39975, 'Genesis 7:20', 'Genesis', 7, 20, 'اوبه د غرونو د څوکو څخه اووه متره اوچتې شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_020.mp3', NULL, 1761758855, 1761758855),
(39976, 'Genesis 7:21', 'Genesis', 7, 21, 'د ځمکې په مخ هر ژوندی موجود یعنې کورني او وحشي حیوانات، مرغان، خزندې او انسانان ټول مړه شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_021.mp3', NULL, 1761758855, 1761758855),
(39977, 'Genesis 7:22', 'Genesis', 7, 22, 'د ځمکې په مخ ټول ساه لرونکي مړه شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_022.mp3', NULL, 1761758855, 1761758855),
(39978, 'Genesis 7:23', 'Genesis', 7, 23, 'څښتن د ځمکې په مخ ټول ژوندي مخلوقات، انسانان او حیوانات، خزندې او مرغان له منځه یووړل او یوازې نوح او هغوی چې په کشتۍ کې ورسره وو، پاتې شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_023.mp3', NULL, 1761758855, 1761758855),
(39979, 'Genesis 7:24', 'Genesis', 7, 24, 'اوبه یوسلو پنځوس ورځې وروسته مخ په کمېدلو شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis7_verse_024.mp3', NULL, 1761758855, 1761758855),
(39980, 'Genesis 42:1', 'Genesis', 42, 1, 'کله چې یعقوب خبر شو چې په مصر کې غلې دانې شته، نو هغه خپلو زامنو ته وویل: «تاسو ولې هسې ناست یئ او یو بل ته ګورئ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_001.mp3', NULL, 1761758855, 1761758855),
(39981, 'Genesis 42:2', 'Genesis', 42, 2, 'ما اورېدلي دي چې په مصر کې غلې دانې شته. هلته لاړ شئ او زمونږ دپاره یو څه واخلئ چې له لوږې څخه مړه نه شو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_002.mp3', NULL, 1761758855, 1761758855),
(39982, 'Genesis 42:3', 'Genesis', 42, 3, 'نو د یوسف لس ورونه د غلو دانو د اخیستلو دپاره مصر ته لاړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_003.mp3', NULL, 1761758855, 1761758855),
(39983, 'Genesis 42:4', 'Genesis', 42, 4, 'خو یعقوب د یوسف ورور بنیامین د هغوی سره ونه لېږه، ځکه چې هغه وېرېده چې کوم زیان ورته ونه رسیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_004.mp3', NULL, 1761758855, 1761758855),
(39984, 'Genesis 42:5', 'Genesis', 42, 5, 'نو د یعقوب زامن هم د هغو کنعانیانو په ډله کې وو چې د غلې د اخیستلو دپاره راغلي وو، ځکه چې په کنعان کې هم قحطي وه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_005.mp3', NULL, 1761758855, 1761758855),
(39985, 'Genesis 42:6', 'Genesis', 42, 6, 'یوسف د مصر د دوهم مشر په توګه د ټولې دنیا په خلکو باندې غله خرڅوله، نو کله چې د یوسف ورونه راورسېدل، هغه ته یې د درناوي په خاطر خپل سرونه ټیټ کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_006.mp3', NULL, 1761758855, 1761758855),
(39986, 'Genesis 42:7', 'Genesis', 42, 7, 'څنګه چې یوسف خپل ورونه ولیدل هغوی یې وپېژندل، خو ځان یې هغوی ته لکه د یو پردي په شان وښود او د هغوی سره یې په سخته لهجه خبرې وکړې. هغه پوښتنه ورڅخه وکړه: «له کوم ځای څخه راغلي یئ؟» هغوی ځواب ورکړ: «مونږ د کنعان څخه راغلي یو چې یو څه غله واخلو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_007.mp3', NULL, 1761758855, 1761758855),
(39987, 'Genesis 42:8', 'Genesis', 42, 8, 'که څه هم یوسف خپل ورونه وپېژندل، خو هغوی یوسف ونه پېژانده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_008.mp3', NULL, 1761758855, 1761758855),
(39988, 'Genesis 42:9', 'Genesis', 42, 9, 'په دې وخت کې یوسف خپل هغه خوبونه رایاد کړل چې د هغوی په اړه یې لیدلي وو او هغوی ته یې وویل: «تاسو جاسوسان یئ! تاسو د دې دپاره راغلي یئ چې وګورئ زمونږ په هېواد کې د کوم ځای امنیت کمزوری دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_009.mp3', NULL, 1761758855, 1761758855),
(39989, 'Genesis 42:10', 'Genesis', 42, 10, 'هغوی ځواب ورکړ: «نه زما باداره، ستا غلامان د غلې د اخیستلو دپاره راغلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_010.mp3', NULL, 1761758855, 1761758855),
(39990, 'Genesis 42:11', 'Genesis', 42, 11, 'مونږ ټول ورونه یو. مونږ جاسوسان نه یو، مونږ صادق خلک یو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_011.mp3', NULL, 1761758855, 1761758855),
(39991, 'Genesis 42:12', 'Genesis', 42, 12, 'یوسف هغوی ته وویل: «نه! تاسو د دې دپاره راغلي یئ چې وګورئ زمونږ په هېواد کې د کوم ځای امنیت کمزوری دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_012.mp3', NULL, 1761758855, 1761758855),
(39992, 'Genesis 42:13', 'Genesis', 42, 13, 'هغوی ځواب ورکړ: «ستا غلامان دولس ورونه د یو سړي زامن یو چې هغه د کنعان په خاوره کې اوسیږي. یو ورور مو مړ شوی دی او کشر ورور اوس زمونږ د پلار سره دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_013.mp3', NULL, 1761758855, 1761758855),
(39993, 'Genesis 42:14', 'Genesis', 42, 14, 'یوسف هغوی ته وویل: «دا همدا خبره ده لکه څنګه چې ما درته ویلي وو. تاسو جاسوسان یئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_014.mp3', NULL, 1761758855, 1761758855),
(39994, 'Genesis 42:15', 'Genesis', 42, 15, 'اوس به تاسو په دې ډول وازمایلی شئ. زه د فرعون په ژوندون باندې قسم خورم چې تاسو به هېڅکله له دې ځای نه لاړ نه شئ، تر هغې پورې چې ستاسو کشر ورور دلته رانه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_015.mp3', NULL, 1761758855, 1761758855),
(39995, 'Genesis 42:16', 'Genesis', 42, 16, 'ستاسو څخه دې یو تن لاړ شي چې ستاسو ورور راولي او پاتې به په زندان کې وساتل شي، ترڅو ستاسو خبره وازمایلی شي چې تاسو رښتیا وایئ او که نه. که داسې نه وي، نو د فرعون په نامه باندې قسم خورم چې تاسو جاسوسان یئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_016.mp3', NULL, 1761758855, 1761758855),
(39996, 'Genesis 42:17', 'Genesis', 42, 17, 'بیا یې هغوی درې ورځې په زندان کې وساتل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_017.mp3', NULL, 1761758855, 1761758855),
(39997, 'Genesis 42:18', 'Genesis', 42, 18, 'په درېمه ورځ یوسف هغوی ته وویل: «زه له خدایه وېرېږم. زه به تاسو په یو شرط ژوندي پرېږدم،', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_018.mp3', NULL, 1761758855, 1761758855),
(39998, 'Genesis 42:19', 'Genesis', 42, 19, 'که چېرې تاسو صادقان یئ، نو ستاسو د ورونو څخه دې یو کس په زندان کې پاتې شي او نور کولای شي چې لاړ شي او خپلو وږیو کورنیو ته غله یوسي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_019.mp3', NULL, 1761758855, 1761758855),
(39999, 'Genesis 42:20', 'Genesis', 42, 20, 'خو تاسو خامخا خپل کشر ورور ماته راولئ، نو ستاسو خبره به ثابته شي چې رښتیا وایئ او تاسو به مړه نه شئ.» هغوی رضا شول', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_020.mp3', NULL, 1761758855, 1761758855),
(40000, 'Genesis 42:21', 'Genesis', 42, 21, 'او یو بل ته یې وویل: «اوس مونږ دغه تکلیف د هغه کار په نتیجه کې وینو چې د خپل ورور سره مو کړی دی. مونږ ولیدل چې هغه په لوی مصیبت کې ؤ او مونږ ته یې د خپل ژوند دپاره زاري کوله، خو مونږ قبوله نه کړه. په همدې سبب دغه مصیبت په مونږ باندې راغلی دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_021.mp3', NULL, 1761758855, 1761758855),
(40001, 'Genesis 42:22', 'Genesis', 42, 22, 'روبین ځواب ورکړ: «ایا تاسو ته مې ونه ویل چې د دې هلک په وړاندې ګناه مه کوئ؟ خو تاسو زما خبره ونه منله! اوس به مونږ د هغه د وینې حساب ورکوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_022.mp3', NULL, 1761758855, 1761758855),
(40002, 'Genesis 42:23', 'Genesis', 42, 23, 'هغوی ته معلومه نه وه چې یوسف د هغوی په خبرو باندې پوهیږي، ځکه چې دوی د هغه سره د ترجمان په وسیله خبرې کولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_023.mp3', NULL, 1761758855, 1761758855),
(40003, 'Genesis 42:24', 'Genesis', 42, 24, 'یوسف د هغوی څخه لېرې لاړ او په ژړا شو. خو بېرته دوی ته راستون شو او بیا یې د هغوی سره خبرې وکړې. د هغوی څخه یې شمعون ونیوه او د هغوی په مخکې یې وتاړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_024.mp3', NULL, 1761758855, 1761758855),
(40004, 'Genesis 42:25', 'Genesis', 42, 25, 'یوسف امر وکړ چې د هغوی بوجۍ دې د غلو دانو څخه ډکې شي او د هر کس پیسې دې بېرته د هغه په بوجۍ کې کېښودلې شي او هغوی ته دې د سفر دپاره خواړه ورکړای شي. نو همداسې یې ورسره وکړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_025.mp3', NULL, 1761758855, 1761758855),
(40005, 'Genesis 42:26', 'Genesis', 42, 26, 'هغوی غله په خپلو خرو باندې بار کړه او روان شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_026.mp3', NULL, 1761758855, 1761758855),
(40006, 'Genesis 42:27', 'Genesis', 42, 27, 'په هغه ځای کې چې هغوی د شپې تېرولو دپاره پاتې شول، یو تن خپله بوجۍ خلاصه کړه چې خپل خره ته خوراک ورکړي، نو خپلې پیسې یې ولیدلې چې د بوجۍ په خوله کې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_027.mp3', NULL, 1761758855, 1761758855),
(40007, 'Genesis 42:28', 'Genesis', 42, 28, 'هغه خپلو ورونو ته وویل: «زما پیسې یې بېرته ماته راکړې دي او دلته زما په بوجۍ کې دي.» د هغوی زړونه ولوېدل او په رپېدلو یې یو بل ته مخ واړاوه او ویې ویل: «دا څه دي چې خدای زمونږ سره وکړل؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_028.mp3', NULL, 1761758855, 1761758855),
(40008, 'Genesis 42:29', 'Genesis', 42, 29, 'کله چې هغوی خپل پلار یعقوب ته د کنعان خاورې ته راغلل، نو هغه څه چې په هغوی باندې تېر شوي وو، هغه ته یې بیان کړل او ویې ویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_029.mp3', NULL, 1761758855, 1761758855),
(40009, 'Genesis 42:30', 'Genesis', 42, 30, '«د مصر دوهم مشر زمونږ سره په سخته لهجه خبرې وکړې او په مونږ باندې یې دا تور ولګاوه چې مونږ د هغه په خاوره کې جاسوسي کوو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_030.mp3', NULL, 1761758855, 1761758855),
(40010, 'Genesis 42:31', 'Genesis', 42, 31, 'خو مونږ هغه ته وویل چې مونږ صادق خلک یو، مونږ جاسوسان نه یو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_031.mp3', NULL, 1761758855, 1761758855),
(40011, 'Genesis 42:32', 'Genesis', 42, 32, 'مونږ دولس ورونه او د یو پلار زامن یو. زمونږ یو ورور مړ شوی دی او کشر ورور مو په کنعان کې زمونږ د پلار سره دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_032.mp3', NULL, 1761758855, 1761758855),
(40012, 'Genesis 42:33', 'Genesis', 42, 33, 'د مصر دوهم مشر په ځواب کې وویل: ‹هغه وخت به زه پوه شم چې تاسو صادقان یئ چې د خپلو ورونو څخه یو دلته زما سره پرېږدئ او د خپلو وږیو کورنیو دپاره غله واخلئ او لاړ شئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_033.mp3', NULL, 1761758855, 1761758855),
(40013, 'Genesis 42:34', 'Genesis', 42, 34, 'خو خپل کشر ورور ماته راولئ، نو زه به پوه شم چې تاسو جاسوسان نه یئ، بلکې صادقان یئ. بیا به هغه وخت تاسو ته خپل ورور بېرته درکړم او تاسو به وکولای شئ چې دلته پاتې شئ او سوداګري وکړئ.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_034.mp3', NULL, 1761758855, 1761758855),
(40014, 'Genesis 42:35', 'Genesis', 42, 35, 'نو څنګه چې هغوی خپلې بوجۍ خالي کړې، د هر کس په بوجۍ کې د هغه د پیسو کڅوړه وه. کله چې هغوی او د هغوی پلار د پیسو کڅوړې ولیدلې، نو ووېرېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_035.mp3', NULL, 1761758855, 1761758855),
(40015, 'Genesis 42:36', 'Genesis', 42, 36, 'د هغوی پلار یعقوب هغوی ته وویل: «تاسو زه د خپلو اولادونو څخه بې‌برخې کړم، یوسف نور نشته او شمعون هم نور نشته. اوس غواړئ چې بنیامین بوځئ. دا هرڅه زما سره کیږي!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_036.mp3', NULL, 1761758855, 1761758855),
(40016, 'Genesis 42:37', 'Genesis', 42, 37, 'په دې وخت کې روبین خپل پلار ته وویل: «که بنیامین مې بېرته تاته رانه‌ووست، زما دواړه زامن ووژنه. هغه ماته وسپاره زه به یې بېرته راولم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_037.mp3', NULL, 1761758855, 1761758855),
(40017, 'Genesis 42:38', 'Genesis', 42, 38, 'خو یعقوب وویل: «زما زوی به تاسو سره هلته نه ځي. د هغه ورور مړ شوی دی او هغه یوازې پاتې دی. که چېرې په لاره کې په هغه باندې څه پېښه وشي، نو زه زوړ سړی یم، له غمه به مړ شم او تاسو ټول به ملامته شئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis42_verse_038.mp3', NULL, 1761758855, 1761758855),
(40018, 'Ezekiel 19:1', 'Ezekiel', 19, 1, 'څښتن ماته وویل چې د اسراییلو د دوو پاچاهانو دپاره دا د ویر سندره ووایم:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_001.mp3', NULL, 1761758855, 1761758855),
(40019, 'Ezekiel 19:2', 'Ezekiel', 19, 2, '«څنګه مور دې درلودله؟ هغه وه یوه زمرۍ! څملاستله د زمریانو منځ کې هغې کړل لوی خپل بچیان ځوانو زمریو منځ کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_002.mp3', NULL, 1761758855, 1761758855),
(40020, 'Ezekiel 19:3', 'Ezekiel', 19, 3, 'هغې لوی کړ یو بچی او د هغه نه جوړ شو یو قوي زمری او هغه زده کړ د ښکار چل او خوړل به یې انسانان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_003.mp3', NULL, 1761758855, 1761758855),
(40021, 'Ezekiel 19:4', 'Ezekiel', 19, 4, 'واورېدل نورو قومونو د هغه په هکله هغه یې راګېر کړ په خپلې کنده کې مصر ته یې بوتلو په چنګکونو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_004.mp3', NULL, 1761758855, 1761758855),
(40022, 'Ezekiel 19:5', 'Ezekiel', 19, 5, 'مور یې وویست انتظار هغه دپاره چې راستون شي خو امیدونه یې ټول له لاسه ورکړل بیا هغې لوی کړلو خپل بل بچی او هغه یې جوړ کړ یو قوي زمری', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_005.mp3', NULL, 1761758855, 1761758855),
(40023, 'Ezekiel 19:6', 'Ezekiel', 19, 6, 'چې کله ښه لوی شو نو ګرځېده راګرځېده هغه نورو زمریانو سره هغه هم زده کړل چې ښکار وکړي او وخوري انسانان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_006.mp3', NULL, 1761758855, 1761758855),
(40024, 'Ezekiel 19:7', 'Ezekiel', 19, 7, 'هغه چپه کړې کلاګانې او ښارونه یې وران کړل چې به کله غړمبېدلو هغه نو هغه هېواد او ټول خلک به یې وېرېدل له هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_007.mp3', NULL, 1761758855, 1761758855),
(40025, 'Ezekiel 19:8', 'Ezekiel', 19, 8, 'شول راټول سره قومونه چې جګړه ورسره وکړي خلک راغلل له شاوخوا ولایتونو څخه هغوی خپور کړ په هغه باندې خپل جال او په خپله کنده کې یې راګېر کړ هغه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_008.mp3', NULL, 1761758855, 1761758855),
(40026, 'Ezekiel 19:9', 'Ezekiel', 19, 9, 'هغه ته یې واچوله حلقه د اوسپنې او هغه یې یووړ د بابل پاچا ته په زندان کې یې بندي کړ هغه چې بیا وانه ورېدل شي غورېدل د هغه د اسراییلو په غرونو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_009.mp3', NULL, 1761758855, 1761758855),
(40027, 'Ezekiel 19:10', 'Ezekiel', 19, 10, 'وه ستا مور د انګورو د تاک په شان چې کرل شوی د ویالې په غاړه ځکه چې هلته وې پرېمانه اوبه هغه تاک ډک ؤ له مېوو او څانګو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_010.mp3', NULL, 1761758855, 1761758855),
(40028, 'Ezekiel 19:11', 'Ezekiel', 19, 11, 'وې قوي د هغه څانګې او ورڅخه جوړه شوه شاهي امسا هغه شو لوړ د نورو ونو څخه ټولو لیدل چې څومره لوړ دی او ډک د څانګو څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_011.mp3', NULL, 1761758855, 1761758855),
(40029, 'Ezekiel 19:12', 'Ezekiel', 19, 12, 'خو له بېخه وویستل شو تاک له ډېره قهره او راګوزار شولو په ځمکه باندې د ختیځ باد یې کړلې وچې مېوې قوي څانګه یې شوه وچه او وسوځېدله اور کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_012.mp3', NULL, 1761758855, 1761758855),
(40030, 'Ezekiel 19:13', 'Ezekiel', 19, 13, 'تاک کرل شوی اوس په دښته کې په بې‌اوبو او وچه ځمکه کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_013.mp3', NULL, 1761758855, 1761758855),
(40031, 'Ezekiel 19:14', 'Ezekiel', 19, 14, 'اور لګېدلی په تنه کې د تاک او سوځولې یې دي څانګې او مېوې د هغه هېڅ قوي څانګه په هغه کې پاتې شوې نه ده چې ورنه جوړه شي شاهي امسا» دا د ویر سندره ده او د ویر په توګه کارول شوې ده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/ezekiel19_verse_014.mp3', NULL, 1761758855, 1761758855),
(40032, 'Isaiah 22:1', 'Isaiah', 22, 1, 'دا پیغام د رویا د درې په هکله دی. څه خبره ده؟ ولې د ښار ټول خلک بامونو ته ختلي او خوشحالي کوي؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_001.mp3', NULL, 1761758855, 1761758855),
(40033, 'Isaiah 22:2', 'Isaiah', 22, 2, 'ټول ښار له غوغا، شورماشور او خوښۍ څخه ډک دی. د دې ښار خلک ووژل شول، خو هغوی په توره یا په جګړه کې نه دي وژل شوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_002.mp3', NULL, 1761758855, 1761758855),
(40034, 'Isaiah 22:3', 'Isaiah', 22, 3, 'ستاسو ټول مشران وتښتېدل او مخکې له دې چې حتی یو غشی هم ګوزار کړي هغوی ونیول شول. پروا نه لري چې څومره لېرې وتښتېدل، هغوی ټول ونیول شول او اسیران شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_003.mp3', NULL, 1761758855, 1761758855),
(40035, 'Isaiah 22:4', 'Isaiah', 22, 4, 'اوس ما یوازې پرېږدئ چې د خپل قوم د بربادۍ په خاطر سخت وژاړم او ماته د تسلۍ راکولو کوښښ مه کوئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_004.mp3', NULL, 1761758855, 1761758855),
(40036, 'Isaiah 22:5', 'Isaiah', 22, 5, 'په رښتیا مطلق قادر څښتن خدای هغه ورځ غوره کړې ده چې د رویا په دره کې خلک له ډار، ماتې او وارخطایۍ سره مخامخ شي. په هغه ورځ به د ښار دېوالونه راوغورځول شي او د ژړا او مرستې اوازونه به یې په غرونو کې واورېدل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_005.mp3', NULL, 1761758855, 1761758855),
(40037, 'Isaiah 22:6', 'Isaiah', 22, 6, 'د عیلام د هېواد عسکر چې په لیندو او غشو سمبال، په اسونو او جنګي ګاډیو باندې سپاره وو او د قیر د هېواد عسکر سپرونه په لاس تیار وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_006.mp3', NULL, 1761758855, 1761758855),
(40038, 'Isaiah 22:7', 'Isaiah', 22, 7, 'ستاسو ډېرې ښې درې د دښمن له جنګي ګاډیو ډکې شوې دي او په اسونو باندې سپاره سرتېري د اورشلیم د ښار د دروازو په مخکې قطار ولاړ دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_007.mp3', NULL, 1761758855, 1761758855),
(40039, 'Isaiah 22:8', 'Isaiah', 22, 8, 'څښتن د یهودا دفاعي قواوې له منځه یوړې. په هغه ورځ، تاسو د وسلو د راوړلو دپاره سلاح کوټ ته لاړئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_008.mp3', NULL, 1761758855, 1761758855),
(40040, 'Isaiah 22:12', 'Isaiah', 22, 12, 'په هغه ورځ مطلق قادر څښتن خدای تاسو ته بلنه درکړه چې وژاړئ او ویر وکړئ، خپل سرونه وخرایئ او د ویر کالي واغوندئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_012.mp3', NULL, 1761758855, 1761758855),
(40041, 'Isaiah 22:13', 'Isaiah', 22, 13, 'خو د دې په ځای تاسو د خوښۍ جشن جوړ کړ. تاسو غویان او پسونه حلال کړل چې ویې خورئ او شراب مو وڅښل. تاسو وویل: «راځئ چې وخورو او وڅښو، ځکه چې سبا ته مړه کېږو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_013.mp3', NULL, 1761758855, 1761758855),
(40042, 'Isaiah 22:14', 'Isaiah', 22, 14, 'مطلق قادر څښتن په خپله زما سره خبرې وکړې او ویې ویل: «ترڅو پورې چې تاسو ژوندي یئ په رښتیا به ستاسو دا ګناه ونه بخښل شي. دا زما یعنې مطلق قادر څښتن خدای خبره ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_014.mp3', NULL, 1761758855, 1761758855),
(40043, 'Isaiah 22:15', 'Isaiah', 22, 15, 'مطلق قادر څښتن خدای ماته داسې وویل چې شبنا ته چې د پاچا د دربار د چارو مسوول دی، ورشه او هغه ته ووایه:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_015.mp3', NULL, 1761758855, 1761758855),
(40044, 'Isaiah 22:16', 'Isaiah', 22, 16, '«ته دلته څه کوې؟ ته څه حق لرې چې د تیږو د غونډیو په اوچت ځای کې د خپل ځان دپاره قبر جوړوې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_016.mp3', NULL, 1761758855, 1761758855),
(40045, 'Isaiah 22:17', 'Isaiah', 22, 17, 'ګوره! که ته هرڅومره مهم سړی اوسې، خو څښتن به تا ټینګ راونیسي او لېرې به دې وغورځوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_017.mp3', NULL, 1761758855, 1761758855),
(40046, 'Isaiah 22:18', 'Isaiah', 22, 18, 'هغه به تا د توپ په شان تاو او راتاو کړي او بیا به دې یو ډېر لېرې هېواد ته ګوزار کړي. ته به د خپلو هغو جنګي ګاډیو په څنګ کې چې تا ورباندې ویاړ کاوه، مړ شې. ته د خپل بادار د کورنۍ د رسوایۍ سبب یې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_018.mp3', NULL, 1761758855, 1761758855),
(40047, 'Isaiah 22:19', 'Isaiah', 22, 19, 'نو څښتن به ستا څخه دا دنده او لوړ مقام واخلي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_019.mp3', NULL, 1761758855, 1761758855),
(40048, 'Isaiah 22:20', 'Isaiah', 22, 20, 'څښتن شبنا ته وویل: «نو زه به په هغه ورځ خپل خدمتګار د حلقیا زوی الیاقیم راوغواړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_020.mp3', NULL, 1761758855, 1761758855),
(40049, 'Isaiah 22:21', 'Isaiah', 22, 21, 'زه به ستا چپنه هغه ته ورواغوندم، ستا کمربند به د هغه په ملا باندې وتړم او هغه ټول واک چې تا درلود هغه به الیاقیم ته ورکړم. هغه به د اورشلیم او یهودا خلکو ته د پلار په شان وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_021.mp3', NULL, 1761758855, 1761758855),
(40050, 'Isaiah 22:22', 'Isaiah', 22, 22, 'زه به هغه ته د داود د پاچاهۍ د دربار کیلي ورکړم. هغه چې کومه دروازه خلاصه کړي، نو څوک نه شي کولای چې هغه وتړي او کومه دروازه چې هغه تړلې ده، هېڅوک به نه شي کولای چې هغه خلاصه کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_022.mp3', NULL, 1761758855, 1761758855),
(40051, 'Isaiah 22:23', 'Isaiah', 22, 23, 'زه به هغه لکه د مېخ په شان په خپل مقام کې ټینګ کړم او هغه به د خپل پلار د کورنۍ دپاره د سرلوړۍ سبب وګرځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_023.mp3', NULL, 1761758855, 1761758855),
(40052, 'Isaiah 22:24', 'Isaiah', 22, 24, 'خو د هغه ټول خپلوان او اولاده به په هغه بار وي. هغوی به په ده باندې داسې راځوړند وي لکه لوښي، کاسې او کوزې چې په مېخ باندې ځوړندې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_024.mp3', NULL, 1761758855, 1761758855),
(40053, 'Isaiah 22:25', 'Isaiah', 22, 25, 'په هغه ورځ به هغه مېخ چې په خپل ځای باندې ټینګ ؤ هغه به سست شي او وبه غورځیږي. هرڅه چې په هغه باندې ځوړند وو، نو هغه به له منځه لاړ شي.» دا څښتن ویلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah22_verse_025.mp3', NULL, 1761758855, 1761758855),
(40054, 'Songofsongs 1:1', 'Songofsongs', 1, 1, 'د حضرت سليمان خواږۀ سرودونه. محبوبه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_001.mp3', NULL, 1761758855, 1761758855),
(40055, 'Songofsongs 1:2', 'Songofsongs', 1, 2, 'بيا بيا مې په خپلو شونډو سره ښُکل کړه، ځکه چې ستا مينه د ميو نه زياته مزه کړينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_002.mp3', NULL, 1761758855, 1761758855),
(40056, 'Songofsongs 1:3', 'Songofsongs', 1, 3, 'ستا د عطرو خوشبوئى څومره ښُکلې ده، ستا نوم لکه د هغې د خوشبو په شان ده. نو ځکه ټولې پېغلې په تا مئينې دينه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_003.mp3', NULL, 1761758855, 1761758855),
(40057, 'Songofsongs 1:4', 'Songofsongs', 1, 4, 'زر شه، ما د خپل ځان سره بوځه، تۀ زما بادشاه شه، ما خپلې کوټې ته بوځه. ښځې اے بادشاه مونږ څومره ستا دپاره خوشحاله يونه، د ميو نه زيات مونږ ستا د مينې صِفت کوونه. محبوبه دا رښتيا دى چې پېغلې په تا مئينې دينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_004.mp3', NULL, 1761758855, 1761758855),
(40058, 'Songofsongs 1:5', 'Songofsongs', 1, 5, 'زۀ خو توره يمه خو ښُکلې يمه، اے د يروشلم جينکو، د قيدار د خېمو په شان توره يمه او د سليمان د خېمې د پردو په شان توره يمه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_005.mp3', NULL, 1761758855, 1761758855),
(40059, 'Songofsongs 1:6', 'Songofsongs', 1, 6, 'ما ته مۀ ګورئ ځکه چې زۀ غنم رنګه يمه، زما څرمنه نمر توره کړې ده. زما وروڼه ما سره وران وونه او په زبردستۍ سره هغوئ په ما د خپلو انګورو خيال ساتلو. نو بيا ما خپل خيال ونۀ ساتلو، او نۀ مې د خپل انګور خيال وکړلو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_006.mp3', NULL, 1761758855, 1761758855),
(40060, 'Songofsongs 1:7', 'Songofsongs', 1, 7, 'ما ته ووايه، زما جانانه، تۀ به نن خپله رمه څرولو له چرته بوځې؟ او تۀ خپلې ګډې په غرمه کښې د دمې دپاره چرته راغونډوې؟ نو بيا زۀ ولې برقعه په سر سرګردانه شمه او ستا د ملګرو په رمو کښې درپسې وګرځمه محبوب', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_007.mp3', NULL, 1761758855, 1761758855),
(40061, 'Songofsongs 1:8', 'Songofsongs', 1, 8, 'اے په ټولو پېغلو کښې ښائسته محبوبې، کۀ چرې تا ته دا پته نۀ وينه، نو د رمو د پښو ښاپونو پسې شه روانه، او خپل چېلى دې د شپانو د خېمو په خوا کښې وڅرونه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_008.mp3', NULL, 1761758855, 1761758855),
(40062, 'Songofsongs 1:9', 'Songofsongs', 1, 9, 'زما محبوبې، تۀ په ما دومره ګرانه ينه، لکه د فِرعون د شاهى آسپې په شان ښائسته ينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_009.mp3', NULL, 1761758855, 1761758855),
(40063, 'Songofsongs 1:10', 'Songofsongs', 1, 10, 'ستا اننګى څومره ښائسته دينه، او هغه ستا د غوږونو والو سره ځليږينه. او ستا غړۍ څومره ښائسته ده، او د سرو سره څومره ښُکلې ښکارينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_010.mp3', NULL, 1761758855, 1761758855),
(40064, 'Songofsongs 1:11', 'Songofsongs', 1, 11, 'خو مونږ به د سرو زرو والۍ درته او د سپينو زرو مرۍ جوړې کړونه. محبوبه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_011.mp3', NULL, 1761758855, 1761758855),
(40065, 'Songofsongs 1:12', 'Songofsongs', 1, 12, 'کله چې زما شهزاده خپل کټ کښې آرام کولونه، نو زما د عطرو په خوشبويۍ کښې نشه نشه شونه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_012.mp3', NULL, 1761758855, 1761758855),
(40066, 'Songofsongs 1:13', 'Songofsongs', 1, 13, 'زما جانان د مُر زونډے دېنه، زما په سينه پروت دېنه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_013.mp3', NULL, 1761758855, 1761758855),
(40067, 'Songofsongs 1:14', 'Songofsongs', 1, 14, 'زما جانان د عين‌جدى د انګورو په باغونو کښې د نکريزو د ګل په شان دېنه محبوب', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_014.mp3', NULL, 1761758855, 1761758855),
(40068, 'Songofsongs 1:15', 'Songofsongs', 1, 15, 'زما محبوبې، تۀ څومره ښائسته ينه. تۀ څومره حسينه ينه، سترګې دې د ګوګوشتکو په شان ښُکلې دينه. محبوبه', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_015.mp3', NULL, 1761758855, 1761758855),
(40069, 'Songofsongs 1:16', 'Songofsongs', 1, 16, 'تۀ ډېر ښُکلے يې زما جانانه، تۀ څومره زړۀ وړونکے ينه، شنه ګياه به زمونږ بستره وينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_016.mp3', NULL, 1761758855, 1761758855),
(40070, 'Songofsongs 1:17', 'Songofsongs', 1, 17, 'د دِيار لرګى به زمونږ د کور وى تيرونه، او د خوشبوداره دِيار لرګى زمونږ د کور دى تيرونه، او د دِيار ونه به زمونږ د کوټې چت وينه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/songofsongs1_verse_017.mp3', NULL, 1761758855, 1761758855),
(40071, 'Isaiah 15:1', 'Isaiah', 15, 1, 'د موآب په هکله پیغام: د موآب د عار او قیر ښارونه په یوه شپه کې ورانیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_001.mp3', NULL, 1761758855, 1761758855),
(40072, 'Isaiah 15:2', 'Isaiah', 15, 2, 'د دیبون خلک غره ته ختلي دي چې په خپلو بتخانو کې وژاړي. د موآب خلک د نبو او میدیبا د ښارونو په خاطر له غمه ژړا او انګولا کوي. هغوی له غمه خپل سرونه او خپلې ږیرې خریلې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_002.mp3', NULL, 1761758855, 1761758855),
(40073, 'Isaiah 15:3', 'Isaiah', 15, 3, 'خلکو د ویر کالي اغوستي دي او د خپلو کورونو په بامونو او د ښار په چوکونو انګولا کوي او په چیغو چیغو ژاړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_003.mp3', NULL, 1761758855, 1761758855),
(40074, 'Isaiah 15:4', 'Isaiah', 15, 4, 'د حشبون او العاله خلک چیغې وهي او د هغوی ژړاګانې تر یاهص اورېدل کیږي. په دې خاطر د موآب په وسلو سمبال عسکر چیغې وهي او له وېرې نه رپیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_004.mp3', NULL, 1761758855, 1761758855),
(40075, 'Isaiah 15:5', 'Isaiah', 15, 5, 'زما زړه د موآب دپاره فریاد کوي! خلک د صوغر او عجلت شلیشه ښارونو ته تښتېدلي دي. ځینې خلک په ژړا کې لوحیت ته خېژي او ځینې د حورونایم په لار د خپل هېواد د ورانۍ په خاطر په چیغو چیغو ژاړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_005.mp3', NULL, 1761758855, 1761758855),
(40076, 'Isaiah 15:6', 'Isaiah', 15, 6, 'د نمریم ویاله وچه شوې ده او د هغې په غاړه چې کوم واښه وو، هغه مړاوي شوي دي او هېڅ شین بوټی په کې نه دی پاتې شوی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_006.mp3', NULL, 1761758855, 1761758855),
(40077, 'Isaiah 15:7', 'Isaiah', 15, 7, 'په دې خاطر خلک هڅه کوي ترڅو د ولې د ونو د درې نه د خپلې ټولې شتمنۍ سره په تېښته تېر شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_007.mp3', NULL, 1761758855, 1761758855),
(40078, 'Isaiah 15:8', 'Isaiah', 15, 8, 'د موآب په سرحدونو کې په هرځای کې ژړاګانې اورېدل کیږي. حتی دا ژړاګانې او انګولاوې د اجلایم نه تر بیرایلیم پورې هم رسېدلې دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_008.mp3', NULL, 1761758855, 1761758855),
(40079, 'Isaiah 15:9', 'Isaiah', 15, 9, 'په رښتیا د دیبون له ښار سره چې کوم سیند دی هغه په وینو باندې سور شوی دی او زه څښتن به د هغه ځای په خلکو باندې د دې نه ډېر بد مصیبت هم راولم. هو، په موآب کې چې څوک پاتې دي او یا د تښتېدو هڅه کوي، هغوی به په زمریو باندې ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah15_verse_009.mp3', NULL, 1761758855, 1761758855),
(40080, 'Genesis 17:1', 'Genesis', 17, 1, 'هغه وخت چې ابرام د نهه نوي کالو په عمر ؤ، څښتن هغه ته ښکاره شو او ویې ویل: «زه مطلق قادر خدای یم. زما منونکی او بې‌ګناه اوسه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_001.mp3', NULL, 1761758855, 1761758855),
(40081, 'Genesis 17:2', 'Genesis', 17, 2, 'زه به ستا سره یو لوظ وکړم او ډېره اولاده به درکړم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_002.mp3', NULL, 1761758855, 1761758855),
(40082, 'Genesis 17:3', 'Genesis', 17, 3, 'نو هغه وخت ابرام هغه ته سجده وکړه او خدای هغه ته وویل:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_003.mp3', NULL, 1761758855, 1761758855),
(40083, 'Genesis 17:4', 'Genesis', 17, 4, '«ستا سره دا لوظ کوم چې ته به د ډېرو قومونو پلار شې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_004.mp3', NULL, 1761758855, 1761758855),
(40084, 'Genesis 17:5', 'Genesis', 17, 5, 'له دې وروسته به ستا نوم ابرام نه، بلکې ابراهیم وي، ځکه چې ته مې د ډېرو قومونو پلار کړی یې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_005.mp3', NULL, 1761758855, 1761758855),
(40085, 'Genesis 17:6', 'Genesis', 17, 6, 'زه به ستا نسل زیات کړم او ستا څخه به قومونه پیدا کړم او د هغوی څخه به ځینې پاچاهان شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_006.mp3', NULL, 1761758855, 1761758855),
(40086, 'Genesis 17:7', 'Genesis', 17, 7, 'زه به خپل لوظ ستا، ستا د اولادې او ستا څخه وروسته ستا د راتلونکي نسل سره ټینګ وساتم او دا به ابدي لوظ وي. زه به ستا خدای یم او ستا څخه وروسته به ستا د اولادې خدای یم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_007.mp3', NULL, 1761758855, 1761758855),
(40087, 'Genesis 17:8', 'Genesis', 17, 8, 'زه به د کنعان ټوله خاوره په کومه کې چې ته اوس مسافر یې، ستا څخه وروسته ستا اولادې ته د ابدي ملکیت په توګه ورکړم او زه به د هغوی خدای یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_008.mp3', NULL, 1761758855, 1761758855),
(40088, 'Genesis 17:9', 'Genesis', 17, 9, 'خدای ابراهیم ته وویل: «ته او ستا څخه وروسته ستا ټوله اولاده باید زما په لوظ باندې ټینګ ودرېږئ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_009.mp3', NULL, 1761758855, 1761758855),
(40089, 'Genesis 17:10', 'Genesis', 17, 10, 'ته او ستا اولاده باید سره موافقه وکړئ چې ستاسو هر یو نارینه دې سنت شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_010.mp3', NULL, 1761758855, 1761758855),
(40090, 'Genesis 17:13', 'Genesis', 17, 13, 'هر یو کس باید سنت شي. دا به ستاسو په بدن باندې زما د ابدي لوظ نښه وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_013.mp3', NULL, 1761758855, 1761758855),
(40091, 'Genesis 17:14', 'Genesis', 17, 14, 'هر یو نارینه چې سنت شوی نه وي باید زما د قوم څخه وشړل شي، ځکه چې هغه زما لوظ مات کړی دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_014.mp3', NULL, 1761758855, 1761758855),
(40092, 'Genesis 17:15', 'Genesis', 17, 15, 'خدای ابراهیم ته وویل: «له دې وروسته خپلې ښځې ته سارای مه وایه، د هغې نوم دې له همدا‌اوس څخه ساره شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_015.mp3', NULL, 1761758855, 1761758855),
(40093, 'Genesis 17:16', 'Genesis', 17, 16, 'زه به هغې ته برکت ورکړم او د هغې په وسیله به زوی درکړم. هغه به د قومونو مور شي او د هغې څخه به د قومونو پاچاهان راپیدا شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_016.mp3', NULL, 1761758855, 1761758855),
(40094, 'Genesis 17:17', 'Genesis', 17, 17, 'ابراهیم خدای ته سجده وکړه او ویې خندل او د خپل ځان سره یې وویل: «ایا د سل کلن سړي څخه به زوی پیدا شي؟ ایا ساره به په نوي کلنۍ کې ماشوم وزېږوي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_017.mp3', NULL, 1761758855, 1761758855),
(40095, 'Genesis 17:18', 'Genesis', 17, 18, 'ابراهیم خدای ته وویل: «اسماعیل ولې زما میراث خور نه شي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_018.mp3', NULL, 1761758855, 1761758855),
(40096, 'Genesis 17:19', 'Genesis', 17, 19, 'خو خدای وویل: «نه، خو ستا ښځه ساره به ستا دپاره زوی راوړي او ته به په هغه باندې اسحاق نوم کېږدې. زه به ستا د زوی اسحاق سره خپل لوظ ټینګ وساتم، ترڅو د هغه څخه وروسته د هغه د نسل دپاره یو ابدي لوظ وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_019.mp3', NULL, 1761758855, 1761758855),
(40097, 'Genesis 17:20', 'Genesis', 17, 20, 'ما د اسماعیل په هکله ستا غوښتنه واورېدله. نو زه به هغه ته هم برکت ورکړم او هغه ته به زیات ماشومان او ډېره اولاده ورکړم. هغه به د دولسو زامنو پلار وي چې مشران به وي او زه به د هغه د اولادې څخه یو لوی قوم جوړ کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_020.mp3', NULL, 1761758855, 1761758855),
(40098, 'Genesis 17:21', 'Genesis', 17, 21, 'خو خپل لوظ به ستا د زوی اسحاق سره چې ساره به یې په راتلونکي کال کې په همدې وخت وزېږوي، ټینګ وساتم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_021.mp3', NULL, 1761758855, 1761758855),
(40099, 'Genesis 17:22', 'Genesis', 17, 22, 'کله چې خدای د ابراهیم سره خپلې خبرې خلاصې کړې، نو د هغه څخه لاړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_022.mp3', NULL, 1761758855, 1761758855),
(40100, 'Genesis 17:23', 'Genesis', 17, 23, 'ابراهیم خپل زوی اسماعیل او نور ټول نارینه چې د هغه په کورنۍ کې وو او هغه غلامان چې د هغه په کورنۍ کې زېږېدلي وو او هغه غلامان چې په پیسو باندې اخیستل شوي وو لکه څنګه چې خدای هغه ته ویلي وو، په هماغه ورځ سنت کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_023.mp3', NULL, 1761758855, 1761758855),
(40101, 'Genesis 17:24', 'Genesis', 17, 24, 'ابراهیم د نهه نوي کالو په عمر ؤ چې سنت کړای شو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_024.mp3', NULL, 1761758855, 1761758855),
(40102, 'Genesis 17:25', 'Genesis', 17, 25, 'او د هغه زوی اسماعیل د دیارلسو کالو په عمر ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_025.mp3', NULL, 1761758855, 1761758855),
(40103, 'Genesis 17:26', 'Genesis', 17, 26, 'ابراهیم او د هغه زوی اسماعیل دواړه په یوه ورځ سنت شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_026.mp3', NULL, 1761758855, 1761758855),
(40104, 'Genesis 17:27', 'Genesis', 17, 27, 'د ابراهیم د کورنۍ هر نارینه او هغه غلامان چې د هغوی په کورنۍ کې زېږېدلي وو یا هغوی چې په پیسو اخیستل شوي وو، د هغه سره یوځای سنت شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis17_verse_027.mp3', NULL, 1761758855, 1761758855),
(40105, 'Genesis 20:1', 'Genesis', 20, 1, 'ابراهیم د ممري څخه د کنعان جنوب خواته کډه وکړه او د قادش او شور په منځ کې یې اوسېده او د یو څه وخت دپاره په جرار کې پاتې شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_001.mp3', NULL, 1761758855, 1761758855),
(40106, 'Genesis 20:2', 'Genesis', 20, 2, 'هلته ابراهیم د خپلې ښځې ساره په هکله وویل: «هغه زما خور ده.» د جرار پاچا ابي‌ملک په ساره پسې کسان ولېږل او هغه یې راوستله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_002.mp3', NULL, 1761758855, 1761758855),
(40107, 'Genesis 20:3', 'Genesis', 20, 3, 'یوه شپه خدای په خوب کې ابي‌ملک ته ښکاره شو او ویې ویل: «ته به مړ شې، ځکه هغه ښځه چې تا خپل ځان ته راوستلې ده، هغه واده شوې ښځه ده.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_003.mp3', NULL, 1761758855, 1761758855),
(40108, 'Genesis 20:4', 'Genesis', 20, 4, 'خو ابي‌ملک لا هغې ته ورنژدې شوی نه ؤ، هغه وویل: «ای څښتنه، ایا ته به بې‌ګناه خلک ووژنې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_004.mp3', NULL, 1761758855, 1761758855),
(40109, 'Genesis 20:5', 'Genesis', 20, 5, 'ابراهیم په خپله وویل چې هغه زما خور ده او هغې هم همدا خبره وکړه چې دی زما ورور دی او دا کار ما د پاک وجدان له مخې کړی دی او هېڅ غلطي مې نه ده کړې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_005.mp3', NULL, 1761758855, 1761758855),
(40110, 'Genesis 20:6', 'Genesis', 20, 6, 'خدای په خوب کې هغه ته وویل: «هو، زه پوهېږم چې تا دا کار د پاک وجدان له مخې کړی دی او ته مې د دې څخه وساتلې چې زما په وړاندې کومه ګناه وکړې او دې ته مې پرېنښودلې چې هغې ته لاس وروړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_006.mp3', NULL, 1761758855, 1761758855),
(40111, 'Genesis 20:7', 'Genesis', 20, 7, 'اوس هغه ښځه بېرته خپل مېړه ته ورکړه. هغه نبي دی او هغه به ستا دپاره دعا وکړي، ترڅو ژوندی پاتې شې. خو که چېرې هغه بېرته ورنه کړې، په دې پوه شه چې ته او ستا ټول خلک به مړه شئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_007.mp3', NULL, 1761758855, 1761758855),
(40112, 'Genesis 20:8', 'Genesis', 20, 8, 'سبا سهار وختي ابي‌ملک خپل ټول درباریان راوغوښتل او څه چې پېښ شوي وو هغوی ته یې بیان کړل او هغوی ډېر ووېرېدل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_008.mp3', NULL, 1761758855, 1761758855),
(40113, 'Genesis 20:9', 'Genesis', 20, 9, 'بیا ابي‌ملک ابراهیم راوغوښت او پوښتنه یې ترې وکړه: «زمونږ سره دې څه وکړل؟ ما ستا سره څه بد کړي وو چې داسې لوی مصیبت دې په ما او زما په پاچاهۍ باندې راوست؟ تا زما سره داسې کار وکړ چې د کولو نه ؤ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_009.mp3', NULL, 1761758855, 1761758855),
(40114, 'Genesis 20:10', 'Genesis', 20, 10, 'بیا ابي‌ملک د ابراهیم څخه پوښتنه وکړه: «داسې کار دې ولې وکړ؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_010.mp3', NULL, 1761758855, 1761758855),
(40115, 'Genesis 20:11', 'Genesis', 20, 11, 'ابراهیم ځواب ورکړ: «ما فکر وکړ چې د دې ځای خلک د خدای څخه نه وېریږي او ما به د خپلې ښځې په خاطر ووژني.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_011.mp3', NULL, 1761758855, 1761758855),
(40116, 'Genesis 20:12', 'Genesis', 20, 12, 'هغه په رښتیا سره زما خور ده، هغه زما ناسکه خور ده. هغه زما د پلار لور ده، خو زما د مور لور نه ده او ما د هغې سره واده کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_012.mp3', NULL, 1761758855, 1761758855),
(40117, 'Genesis 20:13', 'Genesis', 20, 13, 'کله چې خدای زه د خپل پلار د کور څخه پردي هېواد ته ولېږلم، ما هغې ته وویل: ‹دا به زما سره ستا وفاداري وي چې مونږ هرځای ته لاړ شو، زما په هکله به وایې چې هغه زما ورور دی.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_013.mp3', NULL, 1761758855, 1761758855),
(40118, 'Genesis 20:14', 'Genesis', 20, 14, 'نو ابي‌ملک ابراهیم ته پسونه او غویان، غلامان او وینځې ورکړل او د هغه ښځه ساره یې بېرته هغه ته وسپارله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_014.mp3', NULL, 1761758855, 1761758855),
(40119, 'Genesis 20:15', 'Genesis', 20, 15, 'ابي‌ملک وویل: «زما ټوله ځمکه ستا په مخکې ده، هرځای چې ستا خوښ وي هلته واوسېږه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_015.mp3', NULL, 1761758855, 1761758855),
(40120, 'Genesis 20:16', 'Genesis', 20, 16, 'هغه ساره ته وویل: «زه ستا ورور ته د سپینو زرو زر سیکې ورکوم، ترڅو هغو ټولو خلکو ته چې ستا سره دي دا ثابته شي چې ته بې‌ګناه یې او هر یو په دې باندې پوه شي چې تا کومه غلطي نه ده کړې.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis20_verse_016.mp3', NULL, 1761758855, 1761758855),
(40121, 'Job 25:1', 'Job', 25, 1, 'بيا شوحى بِلداد جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_001.mp3', NULL, 1761758855, 1761758855),
(40122, 'Job 25:2', 'Job', 25, 2, '”اختيار او يره د خُدائ پاک سره دى، هغه په آسمانى بادشاهۍ کښې امن قائموى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_002.mp3', NULL, 1761758855, 1761758855),
(40123, 'Job 25:3', 'Job', 25, 3, 'د هغۀ آسمانى لښکر څوک شمارلے شى؟ د هغۀ رڼا په چا باندې نۀ ځليږى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_003.mp3', NULL, 1761758855, 1761758855),
(40124, 'Job 25:4', 'Job', 25, 4, 'نو بنى آدم د خُدائ پاک په مخکښې څنګه صادق کېدے شى؟ څوک چې د مور نه پېدا شوے وى نو هغه کس څنګه صفا کېدے شى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_004.mp3', NULL, 1761758855, 1761758855),
(40125, 'Job 25:5', 'Job', 25, 5, 'ګوره، د هغۀ په وړاندې ځلېدونکى سپوږمۍ او ستورى هيڅ هم نۀ دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_005.mp3', NULL, 1761758855, 1761758855),
(40126, 'Job 25:6', 'Job', 25, 6, 'نو بيا انسان څۀ څيز دے يو مېږے کۀ يا يو چينجے؟ د خُدائ پاک په نظر کښې د يو انسان څۀ اهميت دے؟“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job25_verse_006.mp3', NULL, 1761758855, 1761758855),
(40127, 'Isaiah 40:1', 'Isaiah', 40, 1, 'ستاسو خدای وایي: «ورکړئ تسلي زما غوره شوي قوم ته ورکړئ تسلي!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_001.mp3', NULL, 1761758855, 1761758855),
(40128, 'Isaiah 40:2', 'Isaiah', 40, 2, 'خبرې وکړئ په نرمه ژبه د اورشلیم خلکو سره او کړئ اعلان هغوی ته چې تېرې شوې مو دي د غلامۍ ورځې او ما بخښلي ګناهونه ستاسو ځکه هغوی ته مې ورکړې سزا د ګناهونو په بدل کې یو په دوه»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_002.mp3', NULL, 1761758855, 1761758855),
(40129, 'Isaiah 40:3', 'Isaiah', 40, 3, 'زه اواز اورم چې یو څوک وهي نارې: «لاره تیاره کړئ په دښته کې څښتن دپاره جوړه صحرا کې کړئ لویه او سیده لاره زمونږ د خدای دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_003.mp3', NULL, 1761758855, 1761758855),
(40130, 'Isaiah 40:4', 'Isaiah', 40, 4, 'شي به ډکه هره دره شي به هواره هره غونډۍ او غر او شي به هوار کنډ و کپر ځایونه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_004.mp3', NULL, 1761758855, 1761758855),
(40131, 'Isaiah 40:5', 'Isaiah', 40, 5, 'بیا راښکاره به شي جلال د څښتن او ټول انسانان به یې یوځای وویني ځکه داسې ویلي دي خپله څښتن»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_005.mp3', NULL, 1761758855, 1761758855),
(40132, 'Isaiah 40:6', 'Isaiah', 40, 6, 'یو اواز راځي او وایي: «یو پیغام اعلان کړه» ما پوښتنه وکړه: «کوم پیغام اعلان کړم؟» «دا اعلان وکړه چې د واښو په شان دي ټول انسانان زیات دوام نه کړي د هغوی ژوند له ځنګلي ګلانو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_006.mp3', NULL, 1761758855, 1761758855),
(40133, 'Isaiah 40:7', 'Isaiah', 40, 7, 'څښتن چې کله په هغوی باندې نازل کړي باد واښه وچیږي او ګلان رژیږي هو، په رښتیا چې انسانان دي د واښو په شان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_007.mp3', NULL, 1761758855, 1761758855),
(40134, 'Isaiah 40:8', 'Isaiah', 40, 8, 'واښه وچیږي او ګلان رژیږي خو تل ترتله به وي ټینګ زمونږ د خدای کلام»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_008.mp3', NULL, 1761758855, 1761758855),
(40135, 'Isaiah 40:9', 'Isaiah', 40, 9, 'ای صهیونه، وخېژه لوړ غره ته له هغه ځایه ورکړه زېری ای اورشلیمه، په لوړ اواز ورکړه خپل زېری پرته له وېرې ته اعلان کړه هغه د یهودا ښارو ته ووایه: «راروان دی ستاسو خدای»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_009.mp3', NULL, 1761758855, 1761758855),
(40136, 'Isaiah 40:10', 'Isaiah', 40, 10, 'ګوره، څښتن تعالی راځي او پاچاهي کوي د مټو په زور ګوره، راولي له خپله ځانه سره هغه ژغورل شوي خلک راروان دي هغوی هغه نه مخکې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_010.mp3', NULL, 1761758855, 1761758855),
(40137, 'Isaiah 40:11', 'Isaiah', 40, 11, 'هغه به پام کوي په خپلې رمې لکه د شپون په شان راغونډوي به هغه وري په یوځای او وړي به یې غېږه کې خپل بیایي په مینه به د هغوی مورګانې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_011.mp3', NULL, 1761758855, 1761758855),
(40138, 'Isaiah 40:12', 'Isaiah', 40, 12, 'ایا کولای شي څوک چې اندازه کړي د بحر اوبه په خپله لپه یا اسمان په خپلې لوېشت باندې؟ ایا کولای شي څوک چې په سطل کې ځای کړي د ټولې ځمکې خاورې یا تله کې وتلي غونډۍ او غرونه؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_012.mp3', NULL, 1761758855, 1761758855),
(40139, 'Isaiah 40:13', 'Isaiah', 40, 13, 'ایا کولای شي څوک چې نصیحت وکړي څښتن ته؟ یا د هغه روح ته لارښوونه وکړي د مشاور په توګه؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_013.mp3', NULL, 1761758855, 1761758855),
(40140, 'Isaiah 40:14', 'Isaiah', 40, 14, 'ایا مجبور ؤ څښتن مشورې ته د چا چې وروښایي هغه ته سمه لاره یا ورزده کړي ورته پوهه او حکمت؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_014.mp3', NULL, 1761758855, 1761758855),
(40141, 'Isaiah 40:15', 'Isaiah', 40, 15, 'نه، په حقیقت کې ټول قومونه دي څښتن دپاره داسې لکه په سطل کې یو څاڅکی اوبه او یا لکه چې دوړه وي په تله کې هغه د دوړې په شان پورته کوي جزیرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_015.mp3', NULL, 1761758855, 1761758855),
(40142, 'Isaiah 40:16', 'Isaiah', 40, 16, 'زمونږ څښتن ته د سوځېدونکو نذرانو دپاره کافي نه دي اور بلولو دپاره د لبنان د ځنګلونو هغه ټول حیوانات کافي نه دي د دې ځنګلونو ټولې ونې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_016.mp3', NULL, 1761758855, 1761758855),
(40143, 'Isaiah 40:17', 'Isaiah', 40, 17, 'هېڅ هم نه دي د څښتن په وړاندې د نړۍ ټول قومونه او په هېڅ کې شمېرل کیږي د هغه په وړاندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_017.mp3', NULL, 1761758855, 1761758855),
(40144, 'Isaiah 40:18', 'Isaiah', 40, 18, 'نو تشبیه کولای شئ خدای د چا سره؟ پرتله کولای شئ هغه د کومې مجسمې سره؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_018.mp3', NULL, 1761758855, 1761758855),
(40145, 'Isaiah 40:19', 'Isaiah', 40, 19, 'ایا کولای شئ چې پرتله کړئ څښتن له یو بت سره؟ کسبګر هغه قالب کې اچوي اول او ترې جوړوي مجسمه په سرو زرو پوښوي زرګر هغه او جوړوي هم د سپینو زرو زنځیرونه د هغه دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_019.mp3', NULL, 1761758855, 1761758855),
(40146, 'Isaiah 40:20', 'Isaiah', 40, 20, 'څوک چې غریب وي هغه نه شي ورکولی نذرانه داسې لرګی غوره کوي هغه بت جوړولو لره چې نه ورستیږي هغه بیا ورکوي هغه په لاس د یو ماهر کسبګر چې ترې جوړ کړي یو بت چې راونه غورځیږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_020.mp3', NULL, 1761758855, 1761758855),
(40147, 'Isaiah 40:21', 'Isaiah', 40, 21, 'ایا تاسو په دې نه پوهېږئ؟ ایا تاسو اورېدلي نه وو؟ ایا تاسو ته له پیله ویل شوي نه وو؟ ایا تاسو په دې نه پوهېدئ چې څنګه پیدا شوه دا نړۍ؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_021.mp3', NULL, 1761758855, 1761758855),
(40148, 'Isaiah 40:22', 'Isaiah', 40, 22, 'څښتن ډېر لوړ له ځمکې ناست دی په خپل تخت باندې او د ځمکې اوسېدونکي ورته ښکاري ملخانو په شان خپروي هغه اسمان لکه پردې په شان او ودروي یې لکه خېمې په شان د اوسېدو دپاره', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_022.mp3', NULL, 1761758855, 1761758855),
(40149, 'Isaiah 40:23', 'Isaiah', 40, 23, 'غورځوي له واکه هغه قوي حکمرانان او په نشت بدلوي د نړۍ قوي مشران', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_023.mp3', NULL, 1761758855, 1761758855),
(40150, 'Isaiah 40:24', 'Isaiah', 40, 24, 'هغوی دي هغو نیالګیو په شان چې کرل شوي اوس تازه او ریښې یې ځغلیدلې نه وي چې راوالوزي کله د څښتن باد هغوی وچ شي او سیلۍ یې یوسي لکه د بوسو په شان', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_024.mp3', NULL, 1761758855, 1761758855),
(40151, 'Isaiah 40:25', 'Isaiah', 40, 25, 'سپېڅلی خدای وایي: «تشبیه کوئ مې تاسو چا سره؟ ایا بل څوک شته زما په شان؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_025.mp3', NULL, 1761758855, 1761758855),
(40152, 'Isaiah 40:26', 'Isaiah', 40, 26, 'اسمان ته وګورئ! چا پیدا کړي دي دا ستوري چې یې وینئ تاسې؟ دا هغه څوک دی تنظیموي چې اسماني لښکرې ورته معلوم دی شمېر د هغوی، هر یو په نوم پېژني هغه لري دومره توان هغه نه پرېږدي چې ورک شي له هغو نه یو هم', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_026.mp3', NULL, 1761758855, 1761758855),
(40153, 'Isaiah 40:27', 'Isaiah', 40, 27, 'نو ای یعقوبه، ولې وایئ او ای اسراییلو، بیا کوئ شکایت ولې چې خبر نه دی څښتن زمونږ له کړاوونو څخه او نه کوي پام زمونږ حق ته زمونږ خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_027.mp3', NULL, 1761758855, 1761758855),
(40154, 'Isaiah 40:28', 'Isaiah', 40, 28, 'ایا نه پوهېږئ او تاسو نه دي اورېدلي چې څښتن دی تلپاتې خدای او پیدا کړې ده هغه ټوله نړۍ؟ هغه هېڅکله نه ستړی کیږي او ستومانه کیږي نه او نه پوهیږي هېڅوک د هغه فکرونو باندې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_028.mp3', NULL, 1761758855, 1761758855),
(40155, 'Isaiah 40:29', 'Isaiah', 40, 29, 'هغه ستړو ته قوت وربخښي او زیاتوي زور د کمزورو', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_029.mp3', NULL, 1761758855, 1761758855),
(40156, 'Isaiah 40:30', 'Isaiah', 40, 30, 'حتی ځوانان هم شي ستړي او ستومانه او زلمي هم له ستړیا رالویږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_030.mp3', NULL, 1761758855, 1761758855),
(40157, 'Isaiah 40:31', 'Isaiah', 40, 31, 'خو چې څښتن ته منتظر دي هغوی وبه مومي هغوی نوی زور په وزرونو باندې به الوزي لکه عقاب په شان هغوی به منډې وهي، خو ستومانه کیږي به نه هغوی به ګرځي، خو ستړي کیږي به نه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah40_verse_031.mp3', NULL, 1761758855, 1761758855),
(40158, 'Exodus 8:1', 'Exodus', 8, 1, 'بیا څښتن موسی ته وویل: «فرعون ته ورشه او هغه ته ووایه چې څښتن وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_001.mp3', NULL, 1761758855, 1761758855),
(40159, 'Exodus 8:2', 'Exodus', 8, 2, 'که چېرې ته د هغوی د پرېښودلو څخه انکار وکړې، زه به ستا په ټول هېواد باندې د چونګښو بلا نازله کړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_002.mp3', NULL, 1761758855, 1761758855),
(40160, 'Exodus 8:3', 'Exodus', 8, 3, 'د نیل سیند به د چونګښو څخه ډک شي. هغوی به ستا ماڼۍ او ستا د خوب کوټې ته درننوځي او ستا کټ ته به دروخېژي. حتی ستا د قوم او د درباریانو کورونو او ستا تنورونو او د خمیره کولو لګنونو ته به هم ورننوځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_003.mp3', NULL, 1761758855, 1761758855),
(40161, 'Exodus 8:4', 'Exodus', 8, 4, 'چونګښې به ستا، ستا د قوم او ستا د ټولو درباریانو سرونو باندې ټوپونه وهي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_004.mp3', NULL, 1761758855, 1761758855),
(40162, 'Exodus 8:5', 'Exodus', 8, 5, 'څښتن موسی ته وویل: «هارون ته ووایه: خپله امسا د ویالو، نهرونو او ډنډونو خواته ونیسه، ترڅو چونګښې دباندې ووځي او د مصر ځمکه په هغو پټه شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_005.mp3', NULL, 1761758855, 1761758855),
(40163, 'Exodus 8:6', 'Exodus', 8, 6, 'نو هارون خپله امسا د اوبو په سر ونیوله او چونګښې راووتلې او ځمکه ورباندې پټه شوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_006.mp3', NULL, 1761758855, 1761758855),
(40164, 'Exodus 8:7', 'Exodus', 8, 7, 'خو جادوګرانو هم همداسې کار وکړ. هغوی هم د جادو په وسیله چونګښې ځمکې ته راوویستلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_007.mp3', NULL, 1761758855, 1761758855),
(40165, 'Exodus 8:8', 'Exodus', 8, 8, 'فرعون موسی او هارون راوغوښتل او ورته ویې ویل: «تاسو څښتن ته دعا وکړئ چې زمونږ څخه دا چونګښې لېرې کړي، نو زه به ستاسو قوم پرېږدم چې لاړ شي او څښتن ته قربانۍ وړاندې کړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_008.mp3', NULL, 1761758855, 1761758855),
(40166, 'Exodus 8:9', 'Exodus', 8, 9, 'موسی په ځواب کې وویل: «زه به ستا دپاره دعا وکړم. ماته وخت وټاکه چې زه کله ستا، ستا د درباریانو او ستا د قوم دپاره دعا وکړم. بیا به تاسو او ستاسو کورونه د چونګښو څخه خلاص شي او یوازې د نیل په سیند کې به چونګښې پاتې شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_009.mp3', NULL, 1761758855, 1761758855),
(40167, 'Exodus 8:10', 'Exodus', 8, 10, 'فرعون په ځواب کې وویل: «سبا زما دپاره دعا وکړه.» موسی وویل: «څنګه چې ستا خوښه وي زه به هماغسې وکړم. بیا به ته پوه شې چې زمونږ د څښتن خدای په شان بل خدای نشته.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_010.mp3', NULL, 1761758855, 1761758855),
(40168, 'Exodus 8:11', 'Exodus', 8, 11, 'ته، ستا درباریان او ستا خلک به له چونګښو څخه خلاص شئ او چونګښې به د نیل د سیند څخه پرته په بل ځای کې پاتې نه شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_011.mp3', NULL, 1761758855, 1761758855),
(40169, 'Exodus 8:12', 'Exodus', 8, 12, 'بیا موسی او هارون د فرعون څخه لاړل او موسی څښتن ته سوال وکړ چې هغه چونګښې له منځه یوسي چې څښتن په فرعون باندې نازلې کړې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_012.mp3', NULL, 1761758855, 1761758855),
(40170, 'Exodus 8:13', 'Exodus', 8, 13, 'څښتن د موسی سوال قبول کړ او هغه چونګښې چې په کورونو، حوېلیو او پټیو کې وې، مړې شوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_013.mp3', NULL, 1761758855, 1761758855),
(40171, 'Exodus 8:14', 'Exodus', 8, 14, 'مصریانو هغه ډېرۍ کړې او ټوله ځمکه بد بوی ونیوله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_014.mp3', NULL, 1761758855, 1761758855),
(40172, 'Exodus 8:15', 'Exodus', 8, 15, 'کله چې فرعون ولیدل چې چونګښې مړې شوې، هغه بیا خپل زړه سخت کړ او لکه څنګه چې څښتن ویلي وو، هغه د موسی او هارون خبرو ته غوږ ونه نیوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_015.mp3', NULL, 1761758855, 1761758855),
(40173, 'Exodus 8:16', 'Exodus', 8, 16, 'بیا څښتن موسی ته وویل: «هارون ته ووایه چې په خپله امسا باندې ځمکه ووهي چې د مصر ټولې خاورې په میاشو بدلې شي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_016.mp3', NULL, 1761758855, 1761758855),
(40174, 'Exodus 8:17', 'Exodus', 8, 17, 'نو هارون ځمکه په امسا باندې ووهله او د مصر ټولې خاورې په میاشو بدلې شوې او ټول انسانان او حیوانات په کې پټ شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_017.mp3', NULL, 1761758855, 1761758855),
(40175, 'Exodus 8:18', 'Exodus', 8, 18, 'جادوګرانو هڅه وکړه چې د جادو په وسیله میاشي پیدا کړي، خو هغوی ونه شو کولای. انسانانو او حیواناتو پورې میاشي نښتي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_018.mp3', NULL, 1761758855, 1761758855),
(40176, 'Exodus 8:19', 'Exodus', 8, 19, 'جادوګرانو فرعون ته وویل: «دا کار خدای کړی دی!» خو د فرعون زړه سخت ؤ او څنګه چې څښتن ویلي وو، فرعون د موسی او هارون خبرو ته غوږ ونه نیوه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_019.mp3', NULL, 1761758855, 1761758855),
(40177, 'Exodus 8:20', 'Exodus', 8, 20, 'څښتن موسی ته وویل: «سبا سهار وختي پاڅه او کله چې فرعون سیند ته ځي، ورشه او ورسره وګوره او هغه ته ووایه چې څښتن داسې وایي: زما قوم پرېږده چې لاړ شي او زما عبادت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_020.mp3', NULL, 1761758855, 1761758855),
(40178, 'Exodus 8:21', 'Exodus', 8, 21, 'که ته زما قوم پرېنږدې چې لاړ شي، زه به په تا، ستا په درباریانو او ستا په قوم او په کورونو باندې مچان نازل کړم. د مصریانو کورونه به د مچانو څخه ډک شي او ځمکه به ورباندې پټه شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_021.mp3', NULL, 1761758855, 1761758855),
(40179, 'Exodus 8:22', 'Exodus', 8, 22, 'خو زه به د جوشن سیمه چې زما قوم په کې اوسيږي، وژغورم چې هلته هېڅ مچان نه وي. دا کار د دې دپاره کوم، ترڅو تاسو پوه شئ چې زه حتی په دې خاوره باندې هم اختیار لرم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_022.mp3', NULL, 1761758855, 1761758855),
(40180, 'Exodus 8:23', 'Exodus', 8, 23, 'زه به ستا او د خپل قوم ترمنځ ښکاره فرق وکړم. دا معجزه به سبا پېښیږي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_023.mp3', NULL, 1761758855, 1761758855),
(40181, 'Exodus 8:24', 'Exodus', 8, 24, 'نو څښتن د فرعون په ماڼۍ او د هغه د درباریانو په کورونو باندې ډېر زیات مچان نازل کړل. مچانو د مصر ټول هېواد وران کړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_024.mp3', NULL, 1761758855, 1761758855),
(40182, 'Exodus 8:25', 'Exodus', 8, 25, 'بیا فرعون موسی او هارون راوغوښتل او هغوی ته یې وویل: «لاړ شئ او په همدې هېواد کې خپل خدای ته قربانۍ وړاندې کړئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_025.mp3', NULL, 1761758855, 1761758855),
(40183, 'Exodus 8:26', 'Exodus', 8, 26, 'موسی په ځواب کې وویل: «دا ښه کار نه دی. ځکه مصریان به زمونږ څخه خفه شي چې مونږ خپل څښتن خدای ته حیوانات قرباني کړو. که چېرې دا حیوانات په داسې ځای کې قرباني کړو چې مصریان مو وویني، نو هغوی به مونږ سنګسار کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_026.mp3', NULL, 1761758855, 1761758855),
(40184, 'Exodus 8:27', 'Exodus', 8, 27, 'لکه څنګه چې زمونږ څښتن خدای حکم کړی دی، مونږ باید هغه ته د قربانۍ وړاندې کولو په خاطر درې ورځې په دښته کې سفر وکړو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_027.mp3', NULL, 1761758855, 1761758855),
(40185, 'Exodus 8:28', 'Exodus', 8, 28, 'فرعون وویل: «زه به تاسو پرېږدم چې لاړ شئ او خپل څښتن خدای ته په دښته کې قربانۍ وړاندې کړئ. خو ډېر لېرې لاړ نه شئ او زما دپاره دعا وکړئ.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_028.mp3', NULL, 1761758855, 1761758855),
(40186, 'Exodus 8:29', 'Exodus', 8, 29, 'موسی په ځواب کې وویل: «څنګه چې زه لاړ شم، نو ستا دپاره به دعا وکړم چې څښتن ستا، ستا له درباریانو او ستا له قوم څخه مچان لېرې کړي. خو ته به بیا مونږ نه غولوې او د قوم مخنیوی به نه کوې چې هغوی څښتن ته قرباني وړاندې کړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_029.mp3', NULL, 1761758855, 1761758855),
(40187, 'Exodus 8:30', 'Exodus', 8, 30, 'موسی د فرعون څخه لاړ او څښتن ته یې دعا وکړه.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_030.mp3', NULL, 1761758855, 1761758855),
(40188, 'Exodus 8:31', 'Exodus', 8, 31, 'څښتن د موسی دعا قبوله کړه. مچانو فرعون، د هغه درباریان او د هغه قوم پرېښودل. یو مچ هم پاتې نه شو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_031.mp3', NULL, 1761758855, 1761758855),
(40189, 'Exodus 8:32', 'Exodus', 8, 32, 'خو دا ځل هم فرعون خپل زړه سخت کړ او د اسراییلو قوم یې پرېنښود چې لاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/exodus8_verse_032.mp3', NULL, 1761758855, 1761758855),
(40190, 'Esther 6:1', 'Esther', 6, 1, 'په هغه شپه پاچا ته هېڅ خوب نه ورته، نو هغه امر وکړ چې د امپراتورۍ د پېښو تاریخي کتاب راوړئ او ماته یې په لوړ اواز ولولئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_001.mp3', NULL, 1761758855, 1761758855),
(40191, 'Esther 6:2', 'Esther', 6, 2, 'په هغه کې یې داسې لیکنه وموندله چې څنګه مردخای د پاچا د وژلو هغه دسیسه چې د پاچا د کوټې د دروازې د دوو خصي شویو ساتونکو یعنې بګتان او تارش له خوا ترتیب شوې وه، ښکاره او بربنډه کړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_002.mp3', NULL, 1761758855, 1761758855),
(40192, 'Esther 6:3', 'Esther', 6, 3, 'پاچا پوښتنه وکړه: «د دې کار په خاطر مونږ مردخای ته څومره عزت او انعام ورکړی دی؟» د هغه خدمتګارانو په ځواب کې وویل: «د هغه دپاره هېڅ نه دي شوي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_003.mp3', NULL, 1761758855, 1761758855),
(40193, 'Esther 6:4', 'Esther', 6, 4, 'پاچا پوښتنه وکړه: «ایا زما د درباریانو څخه څوک په ماڼۍ کې شته؟» نو هامان په دې وخت کې د ماڼۍ باندینۍ حوېلۍ ته راغی. هغه د پاچا څخه غوښتل مردخای په هغه دار باندې چې د هغه دپاره یې تیار کړی ؤ، ځوړند کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_004.mp3', NULL, 1761758855, 1761758855),
(40194, 'Esther 6:5', 'Esther', 6, 5, 'د هغه خدمتګارانو په ځواب کې وویل: «هامان دلته په دربار کې دی.» پاچا وویل: «هغه دننه راولئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_005.mp3', NULL, 1761758855, 1761758855),
(40195, 'Esther 6:6', 'Esther', 6, 6, 'کله چې هامان دننه راغی، نو پاچا ورڅخه پوښتنه وکړه: «د هغه سړي سره چې پاچا غواړي عزت ورته ورکړي، باید څه وکړو؟» نو بیا هامان د خپل ځان سره فکر وکړ: «داسې څوک شته چې پاچا غواړي هغه ته زما نه زیات عزت ورکړي؟»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_006.mp3', NULL, 1761758855, 1761758855),
(40196, 'Esther 6:9', 'Esther', 6, 9, 'بیا یو لوړ رتبه مامور ته دنده وسپارئ چې هغه شاهي چپنه هغه ته ورواغوندي، په اس باندې یې سپور کړي، د ښار په چوک کې دې وګرځوي او په لوړ اواز دې ووایي: ‹ګورئ، د هغه سړي سره چې پاچا غواړي هغه ته عزت ورکړي داسې عمل کیږي!›»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_009.mp3', NULL, 1761758855, 1761758855),
(40197, 'Esther 6:10', 'Esther', 6, 10, 'بیا پاچا هامان ته وویل: «سمدلاسه لاړ شه، چپنه او اس د مردخای یهودي دپاره چې د ماڼۍ په دروازې کې ناست دی، تیار کړه. لکه څنګه چې تا وړاندیز وکړ هماغسې وکړه، پام کوه چې کوم شی دې هېر نه شي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_010.mp3', NULL, 1761758855, 1761758855),
(40198, 'Esther 6:11', 'Esther', 6, 11, 'نو بیا هامان چپنه او اس تیار کړل. مردخای ته یې چپنه واغوستله، هغه یې په اس باندې سپور کړ، د ښار په چوک کې یې وګرځاوه او د هغه په مخکې یې چیغې وهلې: «ګورئ، د هغه سړي سره چې پاچا غواړي هغه ته عزت ورکړي داسې عمل کیږي!»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_011.mp3', NULL, 1761758855, 1761758855),
(40199, 'Esther 6:12', 'Esther', 6, 12, 'له هغې وروسته مردخای بېرته د ماڼۍ دروازې ته راستون شو. خو هامان په داسې حال کې چې ډېر غمجن ؤ او د شرم نه یې خپل مخ پټ کړی ؤ، په بیړه خپل کور ته لاړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_012.mp3', NULL, 1761758855, 1761758855),
(40200, 'Esther 6:13', 'Esther', 6, 13, 'هرڅه چې ورباندې پېښ شوي وو هغه یې خپلې ښځې زرش او خپلو ملګرو ته بیان کړل. د هغه ښځې زرش او د هغه ماهرو مشاورانو هغه ته وویل: «ته د مردخای په وړاندې کمزوری کېږې. هغه یهودي دی، په هغه باندې بریالی کېدای نه شې. هغه به په رښتیا تاته ماتې درکړي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_013.mp3', NULL, 1761758855, 1761758855),
(40201, 'Esther 6:14', 'Esther', 6, 14, 'په داسې حال کې چې هغوی لا خبرې کولې د ماڼۍ خصیان راورسېدل چې هامان په بیړه هغې مېلمستیا ته بوځي چې استر تیاره کړې وه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/esther6_verse_014.mp3', NULL, 1761758855, 1761758855),
(40202, 'Job 12:1', 'Job', 12, 1, 'نو ايُوب جواب ورکړو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_001.mp3', NULL, 1761758855, 1761758855),
(40203, 'Job 12:2', 'Job', 12, 2, '”په دې کښې هيڅ شک نشته چې تاسو په هر څۀ پوهېږئ، او چې کله تاسو مرئ نو ستاسو پوهه به تاسو سره ختمه شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_002.mp3', NULL, 1761758855, 1761758855),
(40204, 'Job 12:3', 'Job', 12, 3, 'خو زۀ هم ستاسو په شان پوهه لرم، زۀ ستاسو نه کم نۀ يم، چې تاسو څۀ وايئ نو په دې باندې هر څوک پوهيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_003.mp3', NULL, 1761758855, 1761758855),
(40205, 'Job 12:4', 'Job', 12, 4, 'زۀ د خپلو دوستانو دپاره يوه مسخره يم، زۀ چې خُدائ پاک ته آواز کوم نو هغه زما آواز اورى، زۀ يو داسې سړے يم چې صادق او بې‌داغه يم، خو زۀ مسخره جوړ شوے يم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_004.mp3', NULL, 1761758855, 1761758855),
(40206, 'Job 12:5', 'Job', 12, 5, 'کوم خلق چې په آرام وى نو هغوئ په هغه چا پورې خندا کوى چې څوک په تکليف کښې دى، او هغه خلقو له ديکه ورکوى د چا چې پښې ښوئيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_005.mp3', NULL, 1761758855, 1761758855),
(40207, 'Job 12:6', 'Job', 12, 6, 'د ډاکوانو کورونه په امن کښې وى، او چې څوک خُدائ پاک راپاروى نو هغه محفوظ وى، اګر چې هغوئ د خُدائ پاک په ځائ په خپل طاقت باندې بهروسه کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_006.mp3', NULL, 1761758855, 1761758855),
(40208, 'Job 12:7', 'Job', 12, 7, 'خو د ځناورو نه تپوس وکړئ او هغوئ به ستاسو رهنمائى وکړى، او په هوا کښې د مارغانو نه تپوس وکړئ، نو هغوئ به تاسو ته ښودنه وکړى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_007.mp3', NULL, 1761758855, 1761758855),
(40209, 'Job 12:8', 'Job', 12, 8, 'او د زمکې د بوټو نه تپوس وکړئ، نو دا به تاسو ته ښودنه وکړى، او د سمندر کبانو نه تپوس وکړئ نو هغه به تاسو ته دا بيان وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_008.mp3', NULL, 1761758855, 1761758855),
(40210, 'Job 12:9', 'Job', 12, 9, 'ځکه چې هغوئ ټولو ته پته ده چې زما تکليف د مالِک خُدائ د طرف نه دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_009.mp3', NULL, 1761758855, 1761758855),
(40211, 'Job 12:10', 'Job', 12, 10, 'د هغۀ په لاس کښې د هر ژوندى څيز ژوند دے او د هغۀ په لاس کښې د هر بشر ساه ده.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_010.mp3', NULL, 1761758855, 1761758855),
(40212, 'Job 12:11', 'Job', 12, 11, 'ولې غوږونه د خبرو معائنه نۀ کوى لکه څنګه چې ژبه د خوراک خوند معلوموى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_011.mp3', NULL, 1761758855, 1761758855),
(40213, 'Job 12:12', 'Job', 12, 12, 'ولې حِکمت د سپين‌ږيرو سره نۀ وى څۀ؟ ولې زيات عُمر سره پوهه نۀ راځى څۀ؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_012.mp3', NULL, 1761758855, 1761758855),
(40214, 'Job 12:13', 'Job', 12, 13, 'حِکمت او طاقت د خُدائ پاک سره دى، د هغۀ سره رهنمائى او پوهه شته دے.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_013.mp3', NULL, 1761758855, 1761758855),
(40215, 'Job 12:14', 'Job', 12, 14, 'چې هغه څۀ وران کړى نو هيڅ څوک يې بيا نۀ شى جوړولے، او چې هغه کوم سړے قېدى کړى نو هغه خلاصېدلے نۀ شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_014.mp3', NULL, 1761758855, 1761758855),
(40216, 'Job 12:15', 'Job', 12, 15, 'کۀ هغه باران ايسار کړى، نو زمکه به اوچه شى، کۀ هغه اوبۀ راپرېږدى، نو اوبۀ به زمکه تباه کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_015.mp3', NULL, 1761758855, 1761758855),
(40217, 'Job 12:16', 'Job', 12, 16, 'طاقت او حِکمت د هغۀ سره دے، دوکه خوړونکے او دوکه ورکوونکے د هغۀ د اختيار لاندې دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_016.mp3', NULL, 1761758855, 1761758855),
(40218, 'Job 12:17', 'Job', 12, 17, 'هغه د مشرانو نه پوهه اخلى، او د قاضيانو نه کم عقلان جوړوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_017.mp3', NULL, 1761758855, 1761758855),
(40219, 'Job 12:18', 'Job', 12, 18, 'هغه د بادشاهانو نه اختيار واخلى، او د هغوئ نه غلامان جوړ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_018.mp3', NULL, 1761758855, 1761758855),
(40220, 'Job 12:19', 'Job', 12, 19, 'هغه اِمامان شړى او اختيار ترې اخلى، او هغه طاقتور لرې کوى چې ډېر وخت يې حکومت کړے وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_019.mp3', NULL, 1761758855, 1761758855),
(40221, 'Job 12:20', 'Job', 12, 20, 'هغه اعتبارى مشيران غلى کړى، د مشرانو نه حِکمت يوسى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_020.mp3', NULL, 1761758855, 1761758855),
(40222, 'Job 12:21', 'Job', 12, 21, 'هغه شهزادګان سپک کړى، او هغه د زورَورو زور اوبۀ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_021.mp3', NULL, 1761758855, 1761758855),
(40223, 'Job 12:22', 'Job', 12, 22, 'هغه د قبر تيارۀ لرې کوى، او هغه تکه توره تيارۀ په رڼا بدلوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_022.mp3', NULL, 1761758855, 1761758855),
(40224, 'Job 12:23', 'Job', 12, 23, 'هغه قومونه تکړه کړى او بيا يې تباه کړى، هغه قومونه لوئ کړى او بيا يې پرېږدى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_023.mp3', NULL, 1761758855, 1761758855),
(40225, 'Job 12:24', 'Job', 12, 24, 'هغه د دُنيا د مشرانو نه پوهه ختموى، او پرې يې ږدى چې سرګردانه او پرېشانه ګرځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_024.mp3', NULL, 1761758855, 1761758855),
(40226, 'Job 12:25', 'Job', 12, 25, 'هغه مشران په تيارۀ کښې د ړندو په شان سرګردانه ګرځى، او د شرابى په شان يې ځنګېدلے کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job12_verse_025.mp3', NULL, 1761758855, 1761758855),
(40227, 'Isaiah 66:1', 'Isaiah', 66, 1, 'څښتن داسې وایي: «اسمان زما تخت دی او ځمکه زما د پښو چوکۍ ده. تاسو به ماته څه ډول کور جوړ کړئ او زما د اوسېدلو ځای چېرته دی؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_001.mp3', NULL, 1761758855, 1761758855),
(40228, 'Isaiah 66:2', 'Isaiah', 66, 2, 'ما دا ټول شیان په خپل لاس پیدا کړل او هغه منځ ته راغلل. خو زه د هغه چا سره یم چې عاجز او توبه کوونکی وي او زما د کلام په وړاندې له وېرې رېږدي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_002.mp3', NULL, 1761758855, 1761758855),
(40229, 'Isaiah 66:3', 'Isaiah', 66, 3, 'څوک چې د قربانۍ دپاره غویی حلالوي، هغه انسان هم قتلوي. څوک چې وری د قربانۍ دپاره حلالوي، هغه د سپي ورمېږ هم ماتوي. څوک چې د غلو دانو نذرانې ماته راوړي، هغه د خوګ وینه هم وړاندې کوي. څوک چې ماته قیمتي خوشبویي سوځوي، هغه بت ته هم عبادت کوي. څنګه چې د هغوی زړه وغواړي، هماغه کار کوي. هغوی د هغو ناوړو کارونو څخه چې د کرکې وړ دي، خوند اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_003.mp3', NULL, 1761758855, 1761758855),
(40230, 'Isaiah 66:4', 'Isaiah', 66, 4, 'نو زه به هم د هغوی دپاره سخت مصیبت وغواړم، داسې مصیبت چې هغوی ورنه وېریږي. ځکه کله چې ما په هغوی غږ وکړ، نو هېچا ځواب رانه کړ او کله به چې ما خبرې کولې، نو هېچا به ورته غوږ نه نیوه. خو هغوی هغه کارونه وکړل چې زما په نظر بد وو او هغه څه یې خوښ کړل چې زه پرې خوشحاله نه وم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_004.mp3', NULL, 1761758855, 1761758855),
(40231, 'Isaiah 66:5', 'Isaiah', 66, 5, 'ای هغو خلکو چې د څښتن د کلام څخه لړزېږئ، د هغه کلام ته غوږ ونیسئ چې وایي: «زما د نوم په خاطر ستاسو خپل خلک ستاسو نه کرکه کوي او تاسې شړي. هغوی په ملنډو تاسو ته وایي: ‹څښتن دې خپله لویي وښایي او تاسو دې وژغوري، ترڅو مونږ ستاسو خوشحالي ووینو!› خو هغوی به په خپله رسوا شي او وبه شرمیږي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_005.mp3', NULL, 1761758855, 1761758855),
(40232, 'Isaiah 66:6', 'Isaiah', 66, 6, 'واورئ! هغه شورماشور چې له ښار څخه راځي او هغه غوغا چې د عبادت د ځای څخه اورېدل کیږي، دا د څښتن اواز دی چې د خپلو دښمنانو څخه بدل اخلي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_006.mp3', NULL, 1761758855, 1761758855),
(40233, 'Isaiah 66:7', 'Isaiah', 66, 7, 'زما سپېڅلی ښار د هغې ښځې په شان دی چې ماشوم یې د زېږېدو له درد نه مخکې وزېږیږي، د لنګون له درد نه مخکې یې ناڅاپه زوی دې نړۍ ته راځي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_007.mp3', NULL, 1761758855, 1761758855),
(40234, 'Isaiah 66:8', 'Isaiah', 66, 8, 'ایا چا کله داسې حیرانوونکې پېښه لیدلې یا اورېدلې ده چې ناڅاپه یو هېواد په یوه ورځ کې پیدا شي؟ ایا کوم قوم په یوه شېبه کې زېږېدلی شي؟ خو په هغه شېبه کې چې په صهیون باندې د لنګون درد پیل شو، ماشومان یې دې نړۍ ته راوړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_008.mp3', NULL, 1761758855, 1761758855),
(40235, 'Isaiah 66:9', 'Isaiah', 66, 9, 'ایا فکر کوئ کله چې زه د یوې ښځې خېټه خلاصه کړم او په همدې شېبه کې یې پرېنږدم چې ماشوم یې وزېږیږي؟ نه، زه هېڅکله داسې کار نه کوم.» ستاسو څښتن خدای داسې ویلي دي:', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_009.mp3', NULL, 1761758855, 1761758855),
(40236, 'Isaiah 66:10', 'Isaiah', 66, 10, 'ای هغو خلکو چې کوئ مینه د اورشلیم سره ای هغو خلکو چې کوئ ویر د هغه دپاره خو اوس خوشحال اوسئ او شریک شئ د هغه په خوشحالۍ کې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_010.mp3', NULL, 1761758855, 1761758855),
(40237, 'Isaiah 66:11', 'Isaiah', 66, 11, 'لکه څنګه چې خوند اخلي ماشوم د خپلې مور د سینې له شیدو تاسو به هم شئ برخمن د اورشلیم له نعمتونو څخه او خوند به واخلئ د هغه له جلاله څخه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_011.mp3', NULL, 1761758855, 1761758855),
(40238, 'Isaiah 66:12', 'Isaiah', 66, 12, 'څښتن داسې وایي: «ګورئ، زه به نېکمرغي او سلامتي د سیند په شان په اورشلیم کې جاري کړم او د نورو قومونو شتمني به هغه ته د خوړ د سېلاب په شان راروانه کړم. تاسو به د داسې ماشوم په شان یئ چې د مور له خوا شیدې ورکول کیږي، په خپله غېږه کې یې وړي او د مینې نه ډک چلند ورسره کوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_012.mp3', NULL, 1761758855, 1761758855),
(40239, 'Isaiah 66:13', 'Isaiah', 66, 13, 'لکه څنګه چې یوه مور خپل ماشوم ته تسلي ورکوي، نو زه به هم تاسو ته په اورشلیم کې تسلي درکړم.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_013.mp3', NULL, 1761758855, 1761758855),
(40240, 'Isaiah 66:14', 'Isaiah', 66, 14, 'کله چې تاسو دا پېښې وګورئ، نو خوشحاله به شئ. ستاسو بدن به د شنو واښو په شان وده وکړي. نو هغه وخت به پوه شئ چې زه څښتن د خپلو خدمتګارانو سره مرسته کوم او خپلو دښمنانو ته خپل قهر ښایم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_014.mp3', NULL, 1761758855, 1761758855),
(40241, 'Isaiah 66:15', 'Isaiah', 66, 15, 'ګورئ، څښتن د اور سره راروان دی او د هغه جنګي ګاډۍ د توفان په شان غړمبیږي. هغه به په ډېر قهر او د اور د شغلو په شان په سختو رټلو سره خپلو دښمنانو ته سزا ورکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_015.mp3', NULL, 1761758855, 1761758855),
(40242, 'Isaiah 66:16', 'Isaiah', 66, 16, 'ځکه هغه به په اور او خپلې تورې د نړۍ ټولو خلکو ته سزا ورکړي او ډېر خلک به د هغه د لاسه ووژل شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_016.mp3', NULL, 1761758855, 1761758855),
(40243, 'Isaiah 66:17', 'Isaiah', 66, 17, 'څښتن داسې وایي: «هغه خلک به ټول یوځای له منځه لاړ شي چې خپل ځانونه سپېڅلي او پاکوي، یوازې د دې دپاره باغونو ته ځي چې د بتانو عبادت وکړي او د خوګ غوښه، موږکان او نور حرام شیان وخوري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_017.mp3', NULL, 1761758855, 1761758855),
(40244, 'Isaiah 66:18', 'Isaiah', 66, 18, 'زه د هغوی د خیالونو او کړنو څخه خبر یم. زه راځم د دې دپاره چې د ټولو قومونو او ژبو خلک سره راغونډ کړم. کله چې هغوی راشي، نو زما جلال به وویني', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_018.mp3', NULL, 1761758855, 1761758855),
(40245, 'Isaiah 66:19', 'Isaiah', 66, 19, 'او زه به د هغوی په منځ کې یو زورور کار وکړم. له دې خلکو نه به ځینې ژوندي پرېږدم او هغوی به دغو ځایونو ته ولېږم: هسپانیې، پول، لود چې په غشو ویشتلو کې مهارت لري، توبال او یونان او لېرې هېوادونو ته چې زما د شهرت څخه خبر نه دي او زما لویي یې نه ده لیدلې. هغوی به د دغو هېوادنو خلکو ته زما لویي اعلان کړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_019.mp3', NULL, 1761758855, 1761758855),
(40246, 'Isaiah 66:20', 'Isaiah', 66, 20, 'هغوی به ستاسو ټول اسراییلي ورونه له نورو قومونو څخه بېرته راولي. هغوی به دغه اسراییلي ورونه په اسونو، قچرو، اوښانو، جنګي او عادي ګاډیو کې سپاره زما سپېڅلي غره اورشلیم ته راولي او ماته به یې د یوې نذرانې په توګه وړاندې کړي، لکه څنګه چې اسراییلیان په پاکو لوښو کې د غلو دانو نذرانې زما د عبادت ځای ته راوړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_020.mp3', NULL, 1761758855, 1761758855),
(40247, 'Isaiah 66:21', 'Isaiah', 66, 21, 'همدارنګه زه به د هغوی نه ځینې د کاهنانو په توګه وټاکم او ځینې د لاویانو په توګه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_021.mp3', NULL, 1761758855, 1761758855),
(40248, 'Isaiah 66:22', 'Isaiah', 66, 22, 'څښتن داسې وایي: «لکه څنګه چې نوي اسمانونه او نوې ځمکه چې زه یې جوړوم زما په حضور کې به تلپاتې وي، همداسې به ستاسو اولاده او ستاسو نوم تلپاتې وي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_022.mp3', NULL, 1761758855, 1761758855),
(40249, 'Isaiah 66:23', 'Isaiah', 66, 23, 'د هرې نوې میاشتې په اختر او همدارنګه د سبت په هره ورځ به د نړۍ ټول خلک زما عبادت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_023.mp3', NULL, 1761758855, 1761758855),
(40250, 'Isaiah 66:24', 'Isaiah', 66, 24, 'کله چې هغوی د اورشلیم څخه ووځي، نو د هغو خلکو مړي به وویني چې زما په وړاندې یې سرغړونه کړې وه. کوم چینجي چې د هغوی مړي خوري، هېڅکله به نه مري او کوم اور چې هغوی سوځوي، هېڅکله به نه مړ کیږي. ټول خلک به هغوی ته د کرکې په سترګه ګوري.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah66_verse_024.mp3', NULL, 1761758855, 1761758855),
(40251, 'Job 34:1', 'Job', 34, 1, 'نو اليهُو خپله خبره جارى وساتله او وې وئيل،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_001.mp3', NULL, 1761758855, 1761758855),
(40252, 'Job 34:2', 'Job', 34, 2, '”اے عقلمندو سړو، زما خبره واورئ، اے هوښيارانو ما ته غوږ ونيسئ،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_002.mp3', NULL, 1761758855, 1761758855),
(40253, 'Job 34:3', 'Job', 34, 3, 'ځکه چې غوږونه خبرې داسې معلوموى لکه څنګه چې ژبه د خوراک په خوند پوهيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_003.mp3', NULL, 1761758855, 1761758855),
(40254, 'Job 34:4', 'Job', 34, 4, 'راځئ چې د دې پته ولګوو چې څۀ صحيح دى، راځئ چې ښۀ څيزونه زده کړُو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_004.mp3', NULL, 1761758855, 1761758855),
(40255, 'Job 34:5', 'Job', 34, 5, 'ځکه چې ايُوب وئيلى دى چې زۀ بې‌ګناه يم، او خُدائ پاک زما سره اِنصاف نۀ کوى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_005.mp3', NULL, 1761758855, 1761758855),
(40256, 'Job 34:6', 'Job', 34, 6, 'زۀ بې‌ګناه يم خو دروغژن ګڼلے شم، په ما کښې څۀ غلطى نشته، خو زما د زخم علاج نشته.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_006.mp3', NULL, 1761758855, 1761758855),
(40257, 'Job 34:7', 'Job', 34, 7, 'د ايُوب په شان څوک شته، چې په چا کښې زره غوندې ادب هم نۀ وى؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_007.mp3', NULL, 1761758855, 1761758855),
(40258, 'Job 34:8', 'Job', 34, 8, 'چې هغه د بدعملو سره ملګرتيا کوى او د بدمعاشانو سره ګرځى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_008.mp3', NULL, 1761758855, 1761758855),
(40259, 'Job 34:9', 'Job', 34, 9, 'نو هغۀ دا هم وئيلى دى چې، ”د خُدائ پاک د راضى کولو څۀ فائده ده.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_009.mp3', NULL, 1761758855, 1761758855),
(40260, 'Job 34:10', 'Job', 34, 10, 'نو چې څوک عقل لرئ نو زما خبره واورئ، هر چا ته پته ده چې خُدائ پاک بدى نۀ کوى، او د قادر خُدائ دپاره ممکن نۀ دى چې هغه غلطى وکړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_010.mp3', NULL, 1761758855, 1761758855),
(40261, 'Job 34:11', 'Job', 34, 11, 'ځکه چې هغه د عملونو په مطابق خلقو له بدله ورکوى، او هغه شان سلوک ورسره کوى چې څنګه يې حقدار وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_011.mp3', NULL, 1761758855, 1761758855),
(40262, 'Job 34:12', 'Job', 34, 12, 'بې‌شکه، خُدائ پاک به بد عمل نۀ کوى، او قادر خُدائ د هيچا سره بې‌اِنصافى نۀ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_012.mp3', NULL, 1761758855, 1761758855),
(40263, 'Job 34:13', 'Job', 34, 13, 'هغۀ له د زمکې اختيار چا ورکړے دے، او دا ټوله دُنيا په خپل ځائ چا لګولې ده؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_013.mp3', NULL, 1761758855, 1761758855),
(40264, 'Job 34:14', 'Job', 34, 14, 'کۀ خُدائ پاک د خلقو نه روح واخلى، او د ژوند ساه ترې نه واخلى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_014.mp3', NULL, 1761758855, 1761758855),
(40265, 'Job 34:15', 'Job', 34, 15, 'ټول انسانان به ختم شى، او ټول بنى آدم به خاورو ته واپس کيږى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_015.mp3', NULL, 1761758855, 1761758855),
(40266, 'Job 34:16', 'Job', 34, 16, 'کۀ تاسو پوهه لرئ، نو دا خبره واورئ، زۀ چې څۀ وايم نو هغې ته غوږ کېږدئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_016.mp3', NULL, 1761758855, 1761758855),
(40267, 'Job 34:17', 'Job', 34, 17, 'چې خُدائ پاک پخپله اِنصاف نۀ کوى نو بيا هغه څنګه دُنيا چلولے شى؟ تاسو به هغه لويه هستى رد کوئ څوک چې صادق دے؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_017.mp3', NULL, 1761758855, 1761758855),
(40268, 'Job 34:18', 'Job', 34, 18, 'څوک چې بادشاه ته وائى چې تۀ بې‌کاره يې، او مشر ته وائى چې تۀ بدعمله يې،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_018.mp3', NULL, 1761758855, 1761758855),
(40269, 'Job 34:19', 'Job', 34, 19, 'څوک چې د حکمرانانو طرفدارى نۀ کوى، او د مالدارو خلقو طرفدارى د غريبانانو نه زياته نۀ کوى، ځکه چې ټول هغۀ پېدا کړى دى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_019.mp3', NULL, 1761758855, 1761758855),
(40270, 'Job 34:20', 'Job', 34, 20, 'يو کس د شپې اچانک مړ کېدے شى، خُدائ پاک خلق ووهى او هغوئ هلاک شى، خُدائ پاک طاقتور خلق هم په آسانۍ سره وژلے شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_020.mp3', NULL, 1761758855, 1761758855),
(40271, 'Job 34:21', 'Job', 34, 21, 'ځکه چې د هغۀ نظر د بنى آدم په عمل باندې دے، او هغه د هغوئ هر قدم ته ګورى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_021.mp3', NULL, 1761758855, 1761758855),
(40272, 'Job 34:22', 'Job', 34, 22, 'داسې تکه توره تيارۀ نشته چرته چې بدعمله خلق خپل ځانونه د هغۀ نه پټ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_022.mp3', NULL, 1761758855, 1761758855),
(40273, 'Job 34:23', 'Job', 34, 23, 'مونږ وخت نۀ مقرروو چې کله به د خُدائ پاک په وړاندې د عدالت دپاره راځو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_023.mp3', NULL, 1761758855, 1761758855),
(40274, 'Job 34:24', 'Job', 34, 24, 'هغه د تپوس نه بغېر طاقتور راګزار کړى، او د هغوئ په ځائ کښې نور مقرر کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_024.mp3', NULL, 1761758855, 1761758855),
(40275, 'Job 34:25', 'Job', 34, 25, 'هغه د هغوئ په کارونو خبر دے، هغه يې په شپه کښې لرې کړى او هغوئ تباه شى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_025.mp3', NULL, 1761758855, 1761758855),
(40276, 'Job 34:26', 'Job', 34, 26, 'د هغوئ د بدعملۍ په وجه يې تباه کړى چې د نورو دپاره د عبرت سبب جوړ شى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_026.mp3', NULL, 1761758855, 1761758855),
(40277, 'Job 34:27', 'Job', 34, 27, 'ځکه چې هغوئ د هغۀ د تابعدارۍ نه اوړى، او د هغۀ په حُکمونو باندې عمل نۀ کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_027.mp3', NULL, 1761758855, 1761758855),
(40278, 'Job 34:28', 'Job', 34, 28, 'نو هغوئ غريبانان فرياد کولو ته جوړ کړل، چې دا فرياد خُدائ پاک ته ورسيږى. او هغۀ د ضرورتمندو خلقو فرياد واورېدو،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_028.mp3', NULL, 1761758855, 1761758855),
(40279, 'Job 34:29', 'Job', 34, 29, 'کۀ خُدائ پاک خاموش وى، نو څوک ورباندې اِعتراض کولے شى څۀ؟ کله چې هغه پناه شى، نو څوک يې ليدلے شى، کۀ هغه يو کس وى او کۀ قوم وى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_029.mp3', NULL, 1761758855, 1761758855),
(40280, 'Job 34:30', 'Job', 34, 30, 'نو چې داسې د خُدائ پاک نه منکر خلق حکومت ونۀ کړى، او چې هغوئ خلق دوکه نۀ کړى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_030.mp3', NULL, 1761758855, 1761758855),
(40281, 'Job 34:31', 'Job', 34, 31, 'خلق خُدائ پاک ته ولې نۀ وائى چې، ”مونږ ګناه کړې ده، خو مونږ به نوره ګناه نۀ کوُو“؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_031.mp3', NULL, 1761758855, 1761758855),
(40282, 'Job 34:32', 'Job', 34, 32, 'يا، ”ما چې کومه بدعملى کړې وى نو هغه ما ته وښايه، کۀ ما غلطى کړې وى، نو فوراً به يې پرېږدم“؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_032.mp3', NULL, 1761758855, 1761758855),
(40283, 'Job 34:33', 'Job', 34, 33, 'خُدائ پاک به ستا د خوښې دپاره خپل اِنصاف پرېږدى؟ خو تا هغه رد کړے دے. دا زما نه بلکې ستا فېصله ده، مونږ ته اوس ووايه چې ستا خيال څۀ دے؟', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_033.mp3', NULL, 1761758855, 1761758855),
(40284, 'Job 34:34', 'Job', 34, 34, 'چې څوک پوهه لرى نو هغوئ به ما ته ووائى، او هغه عقلمند چې ما ته غوږ ږدى نو هغوئ به ووائى،', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_034.mp3', NULL, 1761758855, 1761758855),
(40285, 'Job 34:35', 'Job', 34, 35, '”ايُوب د جهالت خبرې کوى، د هغۀ خبرې د کم عقلتوب نه ډکې دى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_035.mp3', NULL, 1761758855, 1761758855),
(40286, 'Job 34:36', 'Job', 34, 36, 'ايُوب دې عدالت ته راوستلے شى او غټى نه غټه سزا دې ورکړے شى، ځکه چې هغه د بدعمله سړى په شان خبرې کوى.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_036.mp3', NULL, 1761758855, 1761758855),
(40287, 'Job 34:37', 'Job', 34, 37, 'ځکه چې هغه د سرکشۍ سره ګناه کوى، هغه ګستاخ دے، او هغه د خُدائ پاک خِلاف ډېرې خبرې کوى.“', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/job34_verse_037.mp3', NULL, 1761758855, 1761758855),
(40288, 'Isaiah 51:1', 'Isaiah', 51, 1, 'څښتن وایي: «ای هغو خلکو چې روان یئ د عدالت په لاره او یئ لټون کې د څښتن نو ماته غوږ ونیسئ فکر وکړئ د هغه ګټ په هکله چې جدا شوي یئ ترې فکر وکړئ د هغه کان په هکله چې راویستل شوي یئ ترې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_001.mp3', NULL, 1761758855, 1761758855),
(40289, 'Isaiah 51:2', 'Isaiah', 51, 2, 'فکر وکړئ د خپل نیکه ابراهیم په اړه او هم د ساره په اړه چې زېږولي یې یئ تاسو کله چې ما راوغوښت ابراهیم نو اولادونه یې نه وو خو ما ورکړ برکت هغه ته او هغه شو د اولادونو خاوند او اولاده مې ورته کړه ډېره زیاته', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_002.mp3', NULL, 1761758855, 1761758855),
(40290, 'Isaiah 51:3', 'Isaiah', 51, 3, 'زه به ورکړم تسلي صهیون ته او کنډوالې به د هغه جوړې کړم ټولې که څه هم چې ځمکه یې دښته ده خو زه به جوړ کړمه ترې باغ د هغه باغ په شان چې مې جوړ کړی ؤ عدن کې هلته وي به خوشحالي او خوښي هلته ویل کیږي به زما په خاطر د شکرانې او ثنا او صفت سندرې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_003.mp3', NULL, 1761758855, 1761758855),
(40291, 'Isaiah 51:4', 'Isaiah', 51, 4, 'ای زما خلکو، ماته غوږ ونیسئ زه چې څه وایم ورته پام وکړئ زه به قومونو ته شریعت ورکړم زه به جاري کړمه خپل عدالت ترڅو رڼا شي ژوند د هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_004.mp3', NULL, 1761758855, 1761758855),
(40292, 'Isaiah 51:5', 'Isaiah', 51, 5, 'زما عدالت او زما انصاف نژدې دی او راروانه ده زما ژغورنه زه به په خپله حکومت وکړم قومونو باندې لېرې هېوادونه انتظار کوي زما د راتلو په دې هیله دي چې وژغورم هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_005.mp3', NULL, 1761758855, 1761758855),
(40293, 'Isaiah 51:6', 'Isaiah', 51, 6, 'وکړئ نظر پورته اسمان ته او وګورئ لاندې ځمکې ته! ځکه چې ورک به له نظره شي اسمانونه د لوګي په شان ځمکه زړه به شي لکه کالیو په شان او ټول خلک به یې مړه شي د مچانو په شان خو زه به وژغورم تاسو د تل دپاره او نه لري پای زما عدالت', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_006.mp3', NULL, 1761758855, 1761758855),
(40294, 'Isaiah 51:7', 'Isaiah', 51, 7, 'ای هغو خلکو چې پوهېږئ عدالت باندې نو ماته غوږ ونیسئ! او هغو خلکو چې زما شریعت ته یې ورکړی دی ځای په خپلو زړونو کې! کله چې څوک کړي سپکاوی ستاسو، نو مه وېرېږئ کله چې څوک درته ښکنځلې کوي، مه خپه کېږئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_007.mp3', NULL, 1761758855, 1761758855),
(40295, 'Isaiah 51:8', 'Isaiah', 51, 8, 'ځکه هغوی به وي هغو کالیو په شان چې وي خوړلي کوېو او هغو وړیو په شان چې خوړلي وي چنجیو خو وي به تلپاتې عدالت زما او ژغورنه به وي ټولو نسلونو دپاره»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_008.mp3', NULL, 1761758855, 1761758855),
(40296, 'Isaiah 51:9', 'Isaiah', 51, 9, 'راویښ شه، پاڅه ای څښتنه! د خپل قدرت څخه دې کار واخله او وژغوره مونږ لکه چې څنګه دې پخوا کړي وو دا ته وې چې دې ټوټې ټوټې کړه لویه بلا د سیند', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_009.mp3', NULL, 1761758855, 1761758855),
(40297, 'Isaiah 51:10', 'Isaiah', 51, 10, 'دا هم ته وې چې بحیره دې کړله وچه یعنې هغه بحیره چې وه ډېره ژوره په ژورو د بحیرې کې دې کړه جوړه لاره ترڅو پرې تېر شي هغه خلک چې ژغورلي دي تا', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_010.mp3', NULL, 1761758855, 1761758855),
(40298, 'Isaiah 51:11', 'Isaiah', 51, 11, 'هغه خلک چې ژغورلي دي څښتن وبه رسیږي صهیون ته هغوی په خوشحالۍ سره او راستانه به شي صهیون ته په دې لاره د خوشحالۍ له سندرو سره د تاج په شان د هغوی په سر به وي خوشحالي تلپاتې د هغوی زړونه به شي ډک له خوشحالۍ نه او شي به له غم او له خفګانه خلاص', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_011.mp3', NULL, 1761758855, 1761758855),
(40299, 'Isaiah 51:12', 'Isaiah', 51, 12, 'څښتن وایي: «یوازې زه درکوم تسلي تاسو ته نو بیا وېرېږئ ولې له فاني انسانه چې د واښو په شان له منځه ځي زر؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_012.mp3', NULL, 1761758855, 1761758855),
(40300, 'Isaiah 51:13', 'Isaiah', 51, 13, 'ایا هېر کړی مو دی هغه څښتن، چې پیدا کړي یې یئ تاسو اسمانونه یې دي خپاره کړي او بنیاد یې ایښی دی د ځمکې؟ ولې په وېره کې تل ژوند تېروئ د هغو خلکو د غوسې له لاسه چې درباندې ظلم کوي څوک چې تیار دي تاسو له منځه یوسي؟ په تاسو نه کوي اغېزه نور د هغوی قهر', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_013.mp3', NULL, 1761758855, 1761758855),
(40301, 'Isaiah 51:14', 'Isaiah', 51, 14, 'څوک چې بندیان دي زر به ازاد شي هغوی هغوی به نه مري په زندان کې او وږي به هم نه شي هېڅکله هغوی', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_014.mp3', NULL, 1761758855, 1761758855),
(40302, 'Isaiah 51:15', 'Isaiah', 51, 15, 'ځکه چې زه یم څښتن خدای ستاسو زه راولمه بحیره په څپو او غړمبوم څپې د هغه زما نوم دی مطلق قادر څښتن!', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_015.mp3', NULL, 1761758855, 1761758855),
(40303, 'Isaiah 51:16', 'Isaiah', 51, 16, 'ما درکړی خپل کلام تاته او ساتلی مې یې د خپل لاس د سیوري لاندې ما خپاره کړي اسمانونه بنیاد مې ایښی دی د ځمکې او ما وویل صهیون ته: ‹ته یې قوم زما›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_016.mp3', NULL, 1761758855, 1761758855),
(40304, 'Isaiah 51:17', 'Isaiah', 51, 17, 'ای اورشلیمه، ته راویښ شه! ته راپاڅېږه او ودرېږه! تا د څښتن له لاسه څښلې د غضب ډکه پیاله چې یې درکړې وه د قهر په وخت کې هغه دې وڅښله تر وروستي څاڅکي پورې او اوس په لاره کوږ ووږ روان یې', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_017.mp3', NULL, 1761758855, 1761758855),
(40305, 'Isaiah 51:18', 'Isaiah', 51, 18, 'ستا چې څومره اولادونه زېږېدلي له هغو نه یو هم نشته چې ستا وکړي لارښوونه تا چې څومره اولادونه دي روزلي له هغو نه یو هم نشته چې تا ونیسي د لاسه', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_018.mp3', NULL, 1761758855, 1761758855),
(40306, 'Isaiah 51:19', 'Isaiah', 51, 19, 'دوه غبرګې بلاګانې نازل شوې دي په تا یعنې ورانی او تباهي، قحطي او جګړه داسې څوک نشته چې درته درکړي تسلي داسې څوک نشته چې درسره وکړي خواخوږي', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_019.mp3', NULL, 1761758855, 1761758855),
(40307, 'Isaiah 51:20', 'Isaiah', 51, 20, 'د هرې کوڅې په سر کې اولادونه ستا غورځیږي او پراته دي هغوی دي هغې هوسۍ په شان چې راګېر شوې وي په جال کې ځکه په هغو دی نازل شوی د څښتن غضب او هغوی رټلي دي ستا خدای', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_020.mp3', NULL, 1761758855, 1761758855),
(40308, 'Isaiah 51:21', 'Isaiah', 51, 21, 'نو واورئ، ای د اورشلیم کړېدلو او بې وزله خلکو! که څه هم شراب مو نه دي څښلي خو نشه ښکارئ', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_021.mp3', NULL, 1761758855, 1761758855),
(40309, 'Isaiah 51:22', 'Isaiah', 51, 22, 'څښتن، ستاسو خدای کوي دفاع ستاسو او داسې وایي: «ګورئ، ما لېرې کړې ده پیاله د غضب ستاسو له لاسه د هغې پیالې په څښلو چې کاږه واږه ځئ تاسو نور به ونه څښئ تاسو دا پیاله', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_022.mp3', NULL, 1761758855, 1761758855),
(40310, 'Isaiah 51:23', 'Isaiah', 51, 23, 'زه به ورکړم هغه چاته دا پیاله چا چې په تاسو باندې کړی ظلم هغه چا چې په کوڅو کې څملولئ تاسو او ایښودلې به یې پښې درباندې لکه چې ګرځي څوک په خاورو باندې»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/isaiah51_verse_023.mp3', NULL, 1761758855, 1761758855),
(40311, 'Nehemiah 5:1', 'Nehemiah', 5, 1, 'په دې وخت کې زیات شورماشور جوړ شو. ډېرو خلکو او د هغوی ښځو د نورو یهودیانو په ضد شکایت پیل کړ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_001.mp3', NULL, 1761758855, 1761758855),
(40312, 'Nehemiah 5:2', 'Nehemiah', 5, 2, 'ځینو وویل: «زمونږ کورنۍ ډېرې لویې دي، نو مونږ غلو دانو ته اړتیا لرو ترڅو ژوندي پاتې شو.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_002.mp3', NULL, 1761758855, 1761758855),
(40313, 'Nehemiah 5:3', 'Nehemiah', 5, 3, 'نورو وویل: «مونږ مجبور یو چې خپل پټي، د انګورو باغونه او خپل کورونه ګرو کړو، ترڅو د دې قحطۍ په وخت کې په پوره اندازه غلې دانې په بیه واخلو.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_003.mp3', NULL, 1761758855, 1761758855),
(40314, 'Nehemiah 5:4', 'Nehemiah', 5, 4, 'نورو وویل: «مونږ مجبور شو چې پاچا ته د خپلو پټیو او انګورو د باغونو د مالیې د ورکولو دپاره پیسې پور کړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_004.mp3', NULL, 1761758855, 1761758855),
(40315, 'Nehemiah 5:5', 'Nehemiah', 5, 5, 'مونږ لکه د نورو یهودیانو په شان د یو قوم څخه یو. زمونږ اولادونه هم د هغوی د اولادونو په شان دي. خو مونږ مجبور یو چې خپل اولادونه غلامان کړو او زمونږ د لورګانو څخه ځینې لا پخوا د وینځو په توګه خرڅې شوې دي. مونږ بې وسه یو، ځکه چې زمونږ پټي او د انګورو باغونه ګرو شوي دي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_005.mp3', NULL, 1761758855, 1761758855),
(40316, 'Nehemiah 5:6', 'Nehemiah', 5, 6, 'کله چې ما د هغوی شکایتونه او تورونه واورېدل، ډېر په قهر شوم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_006.mp3', NULL, 1761758855, 1761758855),
(40317, 'Nehemiah 5:7', 'Nehemiah', 5, 7, 'د فکر کولو نه وروسته ما د قوم مشران او مامورین ملامته کړل او هغوی ته مې وویل: «تاسو ولې د خپلو خپلوانو څخه سود اخلئ؟» بیا مې د هغوی په ضد لویه جرګه راوغوښتله.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_007.mp3', NULL, 1761758855, 1761758855),
(40318, 'Nehemiah 5:8', 'Nehemiah', 5, 8, 'هغوی ته مې وویل: «ترڅو پورې چې مونږ کولای شول، خپل یهودي خپلوان مو چې په پردیو قومونو باندې خرڅ شوي وو، بېرته واخیستل. اوس تاسو هغوی دې ته مجبوروئ چې خپل ځانونه په مونږ، یعنې په خپلو خلکو باندې خرڅ کړي!» مشران غلي شول او ځواب یې نه درلود.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_008.mp3', NULL, 1761758855, 1761758855),
(40319, 'Nehemiah 5:9', 'Nehemiah', 5, 9, 'بیا مې وویل: «تاسو چې کوم کار کوئ هغه ښه نه دی! تاسو باید د خدای څخه ووېرېږئ او هغه کار وکړئ چې ښه وي. نو تاسو باید زمونږ دښمنانو یعنې غیریهودیانو ته وخت ورنه کړئ چې په مونږ باندې ملنډې ووهي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_009.mp3', NULL, 1761758855, 1761758855),
(40320, 'Nehemiah 5:10', 'Nehemiah', 5, 10, 'ما، زما خپلوانو او زما ملګرو، خلکو ته پیسې او غلې دانې په پور ورکړې دي، خو مونږ باید د هغو په بدل کې سود ونه غواړو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_010.mp3', NULL, 1761758855, 1761758855),
(40321, 'Nehemiah 5:11', 'Nehemiah', 5, 11, 'تاسو چې د هغوی پټي، د انګورو باغونه، د زیتونو باغونه او کورونه او هم هغه سود چې د پیسو، غلو دانو، شرابو او د زیتونو د تېلو په خاطر د هغوی څخه اخیستی دی، همدا نن بېرته ورکړئ.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_011.mp3', NULL, 1761758855, 1761758855),
(40322, 'Nehemiah 5:12', 'Nehemiah', 5, 12, 'مشرانو ځواب ورکړ: «څنګه چې تاسو وایئ هماغسې به وکړو. مونږ به د هغوی جایداد بېرته ورکړو او خپل پورونه به ورڅخه نه غواړو.» کاهنان مې راوغوښتل او د هغوی په مخکې مې مشرانو او مامورینو ته قسم ورکړ چې په هغې وعدې باندې چې همدا اوس یې وکړه، ټینګ ودریږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_012.mp3', NULL, 1761758855, 1761758855),
(40323, 'Nehemiah 5:13', 'Nehemiah', 5, 13, 'بیا مې څادر راوویست او هغه مې وڅنډه. بیا مې وویل: «ستاسو څخه هرڅوک چې په خپله وعده باندې ونه درېده، نو خدای به هغه همداسې وڅنډي. هغه به ستاسو څخه ستاسو کورونه او ټول شیان واخلي او تاسو ته به هېڅ شی پرېنږدي.» هرڅوک چې حاضر ؤ، ویې ویل: «آمین!» او د څښتن ثنا یې وویله. څنګه چې خلکو وعده وکړه، هماغسې یې وکړل.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_013.mp3', NULL, 1761758855, 1761758855),
(40324, 'Nehemiah 5:14', 'Nehemiah', 5, 14, 'د دې ټولو دولسو کالو په دوران کې چې زه د یهودا والي وم، یعنې د ارتخششتا د پاچاهۍ د شلم کال څخه تر دوه دېرشم کاله پورې نه ما او نه زما خپلوانو د والي دپاره هغه ټاکل شوې ډوډۍ خوړله.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_014.mp3', NULL, 1761758855, 1761758855),
(40325, 'Nehemiah 5:15', 'Nehemiah', 5, 15, 'زما څخه مخکې هر والي به په خلکو باندې دروند بار ایښوده، یعنې د هغوی څخه به یې د خوړو او شرابو دپاره د ورځې څلوېښت د سپینو زرو سکې غوښتلې. حتی د هغوی مامورینو به په خلکو باندې ظلم کاوه. خو ما داسې کار نه کاوه، ځکه چې د خدای څخه وېرېدم.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_015.mp3', NULL, 1761758855, 1761758855),
(40326, 'Nehemiah 5:16', 'Nehemiah', 5, 16, 'ما خپل ټول قوت او طاقت د دېوال په بیا ودانولو باندې ولګاوه او هېڅ ځمکه مې د ځان دپاره وانخیستله. زما ټول خدمتګاران هلته د کار دپاره راټول شوي وو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_016.mp3', NULL, 1761758855, 1761758855),
(40327, 'Nehemiah 5:17', 'Nehemiah', 5, 17, 'برسېره پر هغو ټولو خلکو چې د شاوخوا قومونو څخه به ماته راتلل، ما تل د یهودیانو یو سلو پنځوسو کسانو او د هغوی مامورینو ته په خپل دسترخوان باندې ډوډۍ ورکوله.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_017.mp3', NULL, 1761758855, 1761758855),
(40328, 'Nehemiah 5:18', 'Nehemiah', 5, 18, 'ما به هره ورځ یو غویی، شپږ چاغ پسونه، چرګان او په هرو لسو ورځو کې به مې یوځل په زیاته اندازه هر ډول شراب تیارول. ما د والي په توګه د خپلو خوړو د لګښت غوښتنه نه ده کړې. زه پوهېدم چې دا په خلکو باندې څومره دروند بار دی.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_018.mp3', NULL, 1761758855, 1761758855),
(40329, 'Nehemiah 5:19', 'Nehemiah', 5, 19, 'ای زما خدایه، ما در په یاد کړه او د هغه څه په خاطر چې د دې خلکو دپاره مې کړي دي ماته برکت راکړه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/nehemiah5_verse_019.mp3', NULL, 1761758855, 1761758855),
(40330, 'Judges 13:1', 'Judges', 13, 1, 'اسراییلیانو یوځل بیا د څښتن په وړاندې ګناه وکړه. نو څښتن فلسطینیان پرېښودل چې څلوېښت کاله په هغوی باندې حکومت وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_001.mp3', NULL, 1761758855, 1761758855),
(40331, 'Judges 13:2', 'Judges', 13, 2, 'په هغه وخت کې د زرعه په ښارګوټي کې یو سړی اوسېده چې نوم یې مانوح ؤ او د دان د قبیلې څخه ؤ. د هغه ښځه شنډه وه او اولاد یې نه درلود.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_002.mp3', NULL, 1761758855, 1761758855),
(40332, 'Judges 13:3', 'Judges', 13, 3, 'یوه ورځ د څښتن فرښته هغې ښځې ته ښکاره شوه او ورته ویې ویل: «ته شنډه او بې اولاده یې. خو زر به امیدواره شې او زوی به وزېږوې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_003.mp3', NULL, 1761758855, 1761758855),
(40333, 'Judges 13:4', 'Judges', 13, 4, 'پام کوه چې هېڅ شراب ونه څښې او حرام شیان ونه خورې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_004.mp3', NULL, 1761758855, 1761758855),
(40334, 'Judges 13:5', 'Judges', 13, 5, 'کله چې ستا زوی وشو، نو هېڅکله باید د هغه ویښتان ونه خرایې، ځکه چې هغه به د زېږېدلو د ورځې څخه د نذر په توګه خدای ته وقف شي. هغه به اسراییل د فلسطینیانو څخه وژغوري.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_005.mp3', NULL, 1761758855, 1761758855),
(40335, 'Judges 13:6', 'Judges', 13, 6, 'بیا هغه ښځه خپل مېړه ته ورغله او ورته ویې ویل: «ماته د خدای یو نبي راغی. هغه د خدای د فرښتې په شان ښکاره کېده او ډېر هیبتناک ؤ. ما د هغه څخه دا پوښتنه ونه کړه چې ته د کوم ځای څخه راغلی یې او هغه هم ماته خپل نوم ونه ښوده.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_006.mp3', NULL, 1761758855, 1761758855),
(40336, 'Judges 13:7', 'Judges', 13, 7, 'خو هغه راته وویل چې ته به امیدواره شې او یو زوی به وزېږوې. شراب به نه څښې او حرام شیان به نه خورې، ځکه چې دا هلک به د زېږېدلو د وخت څخه نیولې د مرګ تر ورځې پورې د نذر په توګه څښتن ته وقف وي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_007.mp3', NULL, 1761758855, 1761758855),
(40337, 'Judges 13:8', 'Judges', 13, 8, 'بیا مانوح څښتن ته دعا وکړه او ویې ویل: «ای څښتنه، زه تاته سوال کوم، هغه نبي چې تا رالېږلی ؤ هغه پرېږده چې یوځل بیا راشي او مونږ ته وښایي چې کله هغه هلک پیدا شي د هغه روزنه څنګه وکړو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_008.mp3', NULL, 1761758855, 1761758855),
(40338, 'Judges 13:9', 'Judges', 13, 9, 'خدای د مانوح غوښتنه قبوله کړه او په داسې حال کې چې هغه ښځه په پټي کې ناسته وه، فرښته بېرته هغې ته راغله. په هغه وخت کې د هغې مېړه مانوح د هغې سره نه ؤ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_009.mp3', NULL, 1761758855, 1761758855),
(40339, 'Judges 13:10', 'Judges', 13, 10, 'نو هغه په منډه خپل مېړه ته ورغله او ویې ویل: «هغه سړی چې هغه ورځ ماته ښکاره شوی ؤ، هغه بیا راغلی دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_010.mp3', NULL, 1761758855, 1761758855),
(40340, 'Judges 13:11', 'Judges', 13, 11, 'مانوح د خپلې ښځې سره روان شو او هغه سړي ته ورغی او پوښتنه یې ترې وکړه: «ایا ته هغه سړی یې چې زما د ښځې سره دې خبرې کړې وې؟» هغه په ځواب کې وویل: «هو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_011.mp3', NULL, 1761758855, 1761758855),
(40341, 'Judges 13:12', 'Judges', 13, 12, 'بیا مانوح وویل: «کله چې ستا خبرې رښتیا شي، هغه هلک باید څه وکړي؟ هغه باید څه ډول ژوند وکړي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_012.mp3', NULL, 1761758855, 1761758855),
(40342, 'Judges 13:13', 'Judges', 13, 13, 'د څښتن فرښتې په ځواب کې وویل: «ستا ښځه باید زما په ټولو خبرو باندې عمل وکړي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_013.mp3', NULL, 1761758855, 1761758855),
(40343, 'Judges 13:14', 'Judges', 13, 14, 'هر شی چې د انګورو څخه جوړیږي هغه باید ونه خوري. هغه دې نه شراب څښي او نه دې حرام شیان خوري. هرڅه چې مې ورته ویلي دي په هغو باندې دې عمل وکړي.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_014.mp3', NULL, 1761758855, 1761758855),
(40344, 'Judges 13:17', 'Judges', 13, 17, 'مانوح وویل: «ستا نوم څه دی؟ کله چې ستا خبرې رښتیا شي، نو بیا به مونږ ستا عزت کوو.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_017.mp3', NULL, 1761758855, 1761758855),
(40345, 'Judges 13:18', 'Judges', 13, 18, 'فرښتې پوښتنه وکړه: «ته ولې غواړې چې زما نوم وپېژنې؟ ځکه چې زما د نوم په معنی باندې پوهېدل د انسان د قدرت څخه وتلی کار دی.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_018.mp3', NULL, 1761758855, 1761758855),
(40346, 'Judges 13:19', 'Judges', 13, 19, 'نو مانوح یو سېرلی او یو څه غلې دانې واخیستلې او په یو ګټ باندې یې څښتن ته وړاندې کړل. څښتن د مانوح او د هغه د ښځې د سترګو په وړاندې داسې عجیبه کار وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_019.mp3', NULL, 1761758855, 1761758855),
(40347, 'Judges 13:22', 'Judges', 13, 22, 'مانوح خپلې ښځې ته وویل: «مونږ به په رښتیا سره مړه شو، ځکه چې خدای مو لیدلی دی!»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_022.mp3', NULL, 1761758855, 1761758855),
(40348, 'Judges 13:23', 'Judges', 13, 23, 'خو د هغه ښځې په ځواب کې وویل: «که چېرې څښتن زمونږ د وژلو نیت درلودلی، نو هغه به زمونږ نذرانې قبولې کړې نه وای او نه به یې مونږ ته دا ټول شیان ښودلي وای او نه به یې مونږ ته په دې وخت کې دا خبرې کړې وای.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_023.mp3', NULL, 1761758855, 1761758855),
(40349, 'Judges 13:24', 'Judges', 13, 24, 'نو هغې ښځې یو هلک وزېږاوه او په هغه باندې یې شمشون نوم کېښود. هغه لوی شو او څښتن هغه ته برکت ورکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_024.mp3', NULL, 1761758855, 1761758855),
(40350, 'Judges 13:25', 'Judges', 13, 25, 'او هغه وخت چې شمشون د زرعه او اشتاول ترمنځ د دان په کمپ کې ؤ، د څښتن روح د هغه په قوي کولو پیل وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/judges13_verse_025.mp3', NULL, 1761758855, 1761758855),
(40351, 'Micah 7:1', 'Micah', 7, 1, 'افسوس دې وي زما په حال! ځکه زه د هغه وږي کس په شان یم چې د فصل د راټولېدو نه وروسته په ونو کې ورته مېوه او په تاکونو کې ورته انګور نه پیدا کیږي. ځکه چې انګور او خوندور او پاخه انځران پاتې شوي نه دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_001.mp3', NULL, 1761758855, 1761758855),
(40352, 'Micah 7:2', 'Micah', 7, 2, 'ټول خدای ته وفادار خلک ورک شوي دي او هېڅ یو صادق سړی د ځمکې په مخ نه دی پاتې. هرڅوک د دې موقعې په انتظار کې دی چې قتل وکړي او هرڅوک خپل خلک په دام کې راګېروي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_002.mp3', NULL, 1761758855, 1761758855),
(40353, 'Micah 7:3', 'Micah', 7, 3, 'هغوی ټول په بدو کارونو کې ماهران دي. مامورین او قاضیان رشوتونه اخلي. د غټو او قدرمندو خلکو چې هرڅه زړه غواړي، هغوی ته یې وایي او هغوی په ګډه سره دسیسې جوړوي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_003.mp3', NULL, 1761758855, 1761758855),
(40354, 'Micah 7:4', 'Micah', 7, 4, 'حتی د هغوی ډېر ښه خلک هم لکه د اغزو په شان او ایمانداره خلک یې لکه د کرکڼو په شان دي. هغه ورځ رارسېدلې ده چې خدای به هغو خلکو ته سزا ورکوي، لکه څنګه یې چې هغوی د خپلو پهره‌دارانو یعنې پیغمبرانو په وسیله خبر کړي وو. اوس هغوی وارخطا دي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_004.mp3', NULL, 1761758855, 1761758855),
(40355, 'Micah 7:5', 'Micah', 7, 5, 'په خپل ګاونډي باندې اعتبار مه کوه او حتی په خپل دوست باندې هم یقین مه کوه. حتی خپلې ګرانې ښځې ته هم چې کومه خبره کوې، نو په هغې کې احتیاط کوه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_005.mp3', NULL, 1761758855, 1761758855),
(40356, 'Micah 7:6', 'Micah', 7, 6, 'په دې زمانه کې زوی خپل پلار ته په سپکه سترګه ګوري، لور د خپلې مور سره مخالفت کوي او انږور د خپلې خواښې سره ناندرۍ وهي. د یو سړي د خپلې کورنۍ غړي د هغه دښمنان شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_006.mp3', NULL, 1761758855, 1761758855),
(40357, 'Micah 7:7', 'Micah', 7, 7, 'خو زه به څښتن ته سترګې په لاره یم. زه به خدای ته په صبر سره انتظار کوم چې هغه به مې وژغوري. زما خدای به زما دعا قبوله کړي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_007.mp3', NULL, 1761758855, 1761758855),
(40358, 'Micah 7:8', 'Micah', 7, 8, 'ای زمونږ دښمنانو، بېځایه په مونږ باندې مه خوشحالېږئ. ځکه کله چې مونږ ولوېږو، نو بېرته به راپورته شو. کله چې مونږ په تیاره کې یو، نو څښتن به زمونږ دپاره رڼا وي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_008.mp3', NULL, 1761758855, 1761758855),
(40359, 'Micah 7:9', 'Micah', 7, 9, 'مونږ د څښتن په وړاندې ګناه کړې ده، نو مونږ باید تر یو وخته پورې د هغه قهر وزغمو. خو وروسته به هغه زمونږ دفاع وکړي او زمونږ دښمنانو ته به د هغو بدیو په سبب چې زمونږ سره یې کړي دي، سزا ورکړي. هغه به مونږ د تیارې نه رڼا ته راولي او مونږ به د هغه عدالت ووینو.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_009.mp3', NULL, 1761758855, 1761758855),
(40360, 'Micah 7:10', 'Micah', 7, 10, 'نو زمونږ دښمنان به دا وګوري او رسوا به شي، یعنې هغو دښمنانو چې مونږ ته به یې پېغور راکاوه او پوښتنه به یې کوله: «چېرته دی ستاسو څښتن خدای؟» مونږ به وګورو چې هغوی به د ماتې سره مخامخ شي او د خټو په شان به په کوڅو کې تر‌پښو لاندې شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_010.mp3', NULL, 1761758855, 1761758855),
(40361, 'Micah 7:11', 'Micah', 7, 11, 'ای د اورشلیم خلکو، ستاسو د ښار د دېوالونو د بیا جوړونې وخت راروان دی. په هغه وخت کې به ستاسو سیمه پراخه شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_011.mp3', NULL, 1761758855, 1761758855),
(40362, 'Micah 7:12', 'Micah', 7, 12, 'ستاسو خلک به د هرځای نه بېرته تاسو ته راشي یعنې په ختیځ کې د آشور نه، په جنوب کې د مصر د ښارونو نه، د فرات د سیمې نه او د لېرې لېرې بحیرو او غرونو څخه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_012.mp3', NULL, 1761758855, 1761758855),
(40363, 'Micah 7:13', 'Micah', 7, 13, 'خو نور هېوادونه به د هغې د اوسېدونکو د بدکارۍ له امله په دښته باندې بدله شي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_013.mp3', NULL, 1761758855, 1761758855),
(40364, 'Micah 7:14', 'Micah', 7, 14, 'ای څښتنه، د خپل قوم شپون اوسه یعنې هغه قوم چې تا د خپل ځان دپاره غوره کړی دی. که څه هم هغوی په ځنګل کې یوازې اوسیږي، خو شاوخوا ته یې حاصلخېزه ځمکه ده. پرېږده چې هغوی لاړ شي او د باشان او جلعاد په شنو څړځایونو کې د پخوا زمانو په شان وڅریږي.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_014.mp3', NULL, 1761758855, 1761758855),
(40365, 'Micah 7:15', 'Micah', 7, 15, 'څښتن وایي: «زه به هغوی ته خپلې معجزې وښایم لکه څنګه چې ما په هغه وخت کې وښودلې چې کله مې تاسو د مصر نه راویستلئ.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_015.mp3', NULL, 1761758855, 1761758855),
(40366, 'Micah 7:16', 'Micah', 7, 16, 'نور قومونه به دا وګوري او د هغه ټول قوت سره سره چې دوی یې لري، وبه شرمیږي. هغوی به له وېرې خپله خوله پټه کړي او څه به نه اوري.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_016.mp3', NULL, 1761758855, 1761758855),
(40367, 'Micah 7:17', 'Micah', 7, 17, 'هغوی به لکه د مارانو په شان په خاورو کې په سینه باندې ښوییږي او خاورې به څټي. هغوی به د خپلو جنګي کلاګانو نه راوځي او رپیږي به. هغوی به له وېرې ما څښتن ته چې ستاسو خدای یم راوګرځي.»', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_017.mp3', NULL, 1761758855, 1761758855),
(40368, 'Micah 7:18', 'Micah', 7, 18, 'ای څښتنه، ستا په شان بل خدای نشته. ته د خپلو هغو خلکو ګناهونه او سرکښي بخښې چې د جلاوطنۍ نه وروسته ژوندي پاتې شوي دي. ستا قهر به د تل دپاره نه وي، خو ته مونږ ته د خپلې تلپاتې مینې په ښودلو باندې خوشحالېږې.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_018.mp3', NULL, 1761758855, 1761758855),
(40369, 'Micah 7:19', 'Micah', 7, 19, 'ته به یوځل بیا په مونږ باندې مهربانه شې. ته به زمونږ ګناهونه تر‌پښو لاندې کړې او هغه به د بحیرې تل ته وروغورځوې!', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_019.mp3', NULL, 1761758855, 1761758855),
(40370, 'Micah 7:20', 'Micah', 7, 20, 'ته به خپله وفاداري او تلپاتې مینه مونږ ته یعنې د ابراهیم او یعقوب اولادې ته وروښایې، لکه څنګه چې دې په پخوا زمانو کې زمونږ د نیکونو سره وعده کړې وه.', NULL, NULL, 'Unknown', 'afghan2023', 'afghan', '[]', 'afghan2023/unknown/micah7_verse_020.mp3', NULL, 1761758855, 1761758855),
(40371, 'Genesis 31:1', 'Genesis', 31, 1, 'یعقوب واورېدل چې د لابان زامنو ویلي دي چې «هرڅه چې زمونږ د پلار سره وو، هغه یعقوب واخیستل او دا ټوله شتمني یې زمونږ د پلار د شتمنۍ څخه لاسته راوړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_001.mp3', NULL, 1761758855, 1761758855),
(40372, 'Genesis 31:2', 'Genesis', 31, 2, 'هغه ولیدل چې د لابان چلند د هغه سره د پخوا په شان دوستانه نه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_002.mp3', NULL, 1761758855, 1761758855),
(40373, 'Genesis 31:3', 'Genesis', 31, 3, 'بیا څښتن یعقوب ته وویل: «بېرته خپل پلرني وطن او خپلو خپلوانو ته لاړ شه. زه به ستا سره مل یم.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_003.mp3', NULL, 1761758855, 1761758855),
(40374, 'Genesis 31:4', 'Genesis', 31, 4, 'نو یعقوب راحیل او لیې ته خبر ولېږه چې صحرا ته یعنې هغه ځای ته راشي چې د هغه رمې په کې وې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_004.mp3', NULL, 1761758855, 1761758855),
(40375, 'Genesis 31:5', 'Genesis', 31, 5, 'یعقوب هغوی ته وویل: «زه وینم چې ستاسو د پلار چلند زما سره د پخوا په شان دوستانه نه دی، خو زما د پلار خدای زما سره مل دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_005.mp3', NULL, 1761758855, 1761758855),
(40376, 'Genesis 31:6', 'Genesis', 31, 6, 'تاسې دواړه پوهېږئ چې ما په خپل ټول قوت سره ستاسو د پلار خدمت کړی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_006.mp3', NULL, 1761758855, 1761758855),
(40377, 'Genesis 31:7', 'Genesis', 31, 7, 'سره له دې چې ستاسو پلار زما سره ټګي کړې ده او لس ځله یې زما مزدوري بدله کړه، خو خدای هغه پرېنښود چې ماته زیان راورسوي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_007.mp3', NULL, 1761758855, 1761758855),
(40378, 'Genesis 31:8', 'Genesis', 31, 8, 'کله چې به لابان وویل: ‹خالداره وزې دې ستا مزدوري وي،› نو ټولو رمو به خالداره بچي زېږول او چې کله به یې وویل: ‹خطداره دې ستا وي،› نو ټولو رمو به خطداره بچي زېږول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_008.mp3', NULL, 1761758855, 1761758855),
(40379, 'Genesis 31:9', 'Genesis', 31, 9, 'نو خدای ستاسو د پلار څخه رمې واخیستلې او ماته یې راکړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_009.mp3', NULL, 1761758855, 1761758855),
(40380, 'Genesis 31:10', 'Genesis', 31, 10, 'د بچیو د زېږولو په موسم کې ما یو خوب ولیده. سترګې مې پورته کړې او ومې لیدل هغه سېرلي چې د وزو سره جوړه کېدل خطداره او خالداره وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_010.mp3', NULL, 1761758855, 1761758855),
(40381, 'Genesis 31:11', 'Genesis', 31, 11, 'د خدای فرښتې په خوب کې راته وویل: ‹ای یعقوبه!› ما ځواب ورکړ: ‹زه حاضر یم.›', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_011.mp3', NULL, 1761758855, 1761758855),
(40382, 'Genesis 31:12', 'Genesis', 31, 12, 'هغه وویل: ‹سترګې پورته کړه او وګوره. هغه ټول سېرلي چې د وزو سره جوړه کیږي ټول خالداره او خطداره دي، ځکه هرڅه چې لابان ستا سره کړي دي، هغه مې لیدلي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_012.mp3', NULL, 1761758855, 1761758855),
(40383, 'Genesis 31:13', 'Genesis', 31, 13, 'زه هماغه خدای یم چې په بیت‌ییل کې درښکاره شوم. په هغه ځای کې چې تا په هغې تیږې باندې د زیتونو تېل واچول او زما دپاره دې نذر ورکړ. اوس دا خاوره پرېږده او هغه وطن ته لاړ شه چې ته په کې پیدا شوی یې.›»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_013.mp3', NULL, 1761758855, 1761758855),
(40384, 'Genesis 31:14', 'Genesis', 31, 14, 'راحیل او لیه یعقوب ته په ځواب کې وویل: «مونږ ته د خپل پلار څخه هېڅ شی په میراث کې راپاتې نه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_014.mp3', NULL, 1761758855, 1761758855),
(40385, 'Genesis 31:15', 'Genesis', 31, 15, 'هغه زمونږ سره د پردیو په شان چلند کوي. هغه مونږ خرڅې کړې یو او هغه پیسې چې زمونږ دپاره هغه ته ورکړل شوې وې، ټولې یې مصرف کړي دي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_015.mp3', NULL, 1761758855, 1761758855),
(40386, 'Genesis 31:16', 'Genesis', 31, 16, 'هغه ټول مال او دولت چې خدای زمونږ د پلار څخه اخیستی دی، هغه زمونږ او زمونږ د اولادونو دی. نو هرڅه چې خدای درته ویلي دي، هماغسې وکړه.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_016.mp3', NULL, 1761758855, 1761758855),
(40387, 'Genesis 31:17', 'Genesis', 31, 17, 'نو یعقوب خپل اولادونه او خپلې ښځې په اوښانو باندې سپرې کړې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_017.mp3', NULL, 1761758855, 1761758855),
(40388, 'Genesis 31:18', 'Genesis', 31, 18, 'هغه خپل ټول حیوانات مخکې کړل او هغه څه چې په بین‌النهرین کې یې ګټلي وو ټول واخیستل، ترڅو خپل پلار اسحاق ته چې په کنعان کې ؤ، لاړ شي.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_018.mp3', NULL, 1761758855, 1761758855),
(40389, 'Genesis 31:19', 'Genesis', 31, 19, 'په هغه وخت کې چې لابان د خپلو پسونو د سکولولو دپاره تللی ؤ، راحیل د خپل پلار د کورنۍ بتان غلا کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_019.mp3', NULL, 1761758855, 1761758855),
(40390, 'Genesis 31:20', 'Genesis', 31, 20, 'یعقوب لابان وغولاوه، ځکه چې هغه یې په دې باندې خبر نه کړ چې دی د تللو نیت لري.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_020.mp3', NULL, 1761758855, 1761758855),
(40391, 'Genesis 31:21', 'Genesis', 31, 21, 'هرڅه چې هغه درلودل هغه یې واخیستل او وتښتېده. هغوی د فرات د سیند څخه تېر شول او د جلعاد د غرنۍ سیمې په لور روان شول.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_021.mp3', NULL, 1761758855, 1761758855),
(40392, 'Genesis 31:22', 'Genesis', 31, 22, 'په درېمه ورځ لابان ته خبر ورسېده چې یعقوب تښتېدلی دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_022.mp3', NULL, 1761758855, 1761758855),
(40393, 'Genesis 31:23', 'Genesis', 31, 23, 'هغه خپل خپلوان د ځان سره واخیستل او اووه ورځې یې په هغه پسې لاره ووهله او د جلعاد په غرنۍ سیمه کې هغه ته ورورسېد.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_023.mp3', NULL, 1761758855, 1761758855),
(40394, 'Genesis 31:24', 'Genesis', 31, 24, 'خو خدای د شپې په خوب کې لابان ته ښکاره شو او هغه ته یې وویل: «پام کوه چې یعقوب ته هېڅ ونه وایې. نه ورته ښه ووایې او نه بد.»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_024.mp3', NULL, 1761758855, 1761758855),
(40395, 'Genesis 31:25', 'Genesis', 31, 25, 'یعقوب د جلعاد په غرنۍ سیمه کې خپلې خېمې ودرولې وې چې لابان ورورسېد او هغه هم د خپلو خپلوانو سره په هغه ځای کې خېمې ودرولې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_025.mp3', NULL, 1761758855, 1761758855),
(40396, 'Genesis 31:26', 'Genesis', 31, 26, 'لابان یعقوب ته وویل: «څه دې وکړل؟ زه دې وغولولم او زما لورګانې دې د جنګي اسیرانو په شان بوتللې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_026.mp3', NULL, 1761758855, 1761758855),
(40397, 'Genesis 31:27', 'Genesis', 31, 27, 'ولې دې زه وغولولم او په پټه وتښتېدلې؟ ولې دې زه خبر نه کړم چې تاسو مې په خوشحالۍ، په سندرو او د چمبو او رباب په ساز سره رخصت کړي وای.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_027.mp3', NULL, 1761758855, 1761758855),
(40398, 'Genesis 31:28', 'Genesis', 31, 28, 'زه دې پرېنښودم چې خپل لمسیان او لورګانې ښکل کړم او خدای پاماني ورسره وکړم. بې‌عقله کار دې وکړ.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_028.mp3', NULL, 1761758855, 1761758855),
(40399, 'Genesis 31:29', 'Genesis', 31, 29, 'زه دا توان لرم چې زیان درورسوم، خو ستا د پلار خدای تېره شپه ماته وویل چې پام کوه چې یعقوب ته هېڅ ونه وایې. نه ورته ښه ووایې او نه بد.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_029.mp3', NULL, 1761758855, 1761758855),
(40400, 'Genesis 31:30', 'Genesis', 31, 30, 'اوس ته روان یې، ځکه چې تا دا ارمان درلود چې بېرته د خپل پلار کور ته لاړ شې، نو زما بتان دې ولې غلا کړي دي؟»', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_030.mp3', NULL, 1761758855, 1761758855),
(40401, 'Genesis 31:31', 'Genesis', 31, 31, 'یعقوب لابان ته په ځواب کې وویل: «زه ووېرېدم، ځکه چې ما فکر وکړ چې خپلې لورګانې به په زور زما څخه واخلې.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_031.mp3', NULL, 1761758855, 1761758855),
(40402, 'Genesis 31:32', 'Genesis', 31, 32, 'خو که د هرچا سره دې خپل بتان پیدا کړل، هغه دې ووژل شي. زمونږ د خپلوانو په مخکې یې وګوره. که چېرې ستا کوم شی زمونږ سره وي، خپل ځان ته یې واخله.» خو یعقوب په دې باندې نه پوهېده چې راحیل هغه بتان غلا کړي وو.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_032.mp3', NULL, 1761758855, 1761758855),
(40403, 'Genesis 31:33', 'Genesis', 31, 33, 'نو لابان د یعقوب خېمې ته ننوت او هغه یې ولټوله. بیا د لیه خېمې ته او د دواړو وینځو خېمو ته ننوت او هېڅ یې پیدا نه کړل. بیا هغه د راحیل خېمې ته ننوت.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_033.mp3', NULL, 1761758855, 1761758855),
(40404, 'Genesis 31:34', 'Genesis', 31, 34, 'راحیل بتان د اوښ د زین لاندې ایښي وو او ورباندې ناسته وه. لابان ټوله خېمه ولټوله، هېڅ یې ونه موندل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_034.mp3', NULL, 1761758855, 1761758855),
(40405, 'Genesis 31:35', 'Genesis', 31, 35, 'راحیل خپل پلار ته وویل: «پلاره، خفه نه شې. زه ستا په مخکې نه شم پاڅېدلی، ځکه چې په ما باندې میاشتینۍ ناروغي راغلې ده.» لابان خېمه ولټوله، خو بتان یې پیدا نه کړل.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_035.mp3', NULL, 1761758855, 1761758855),
(40406, 'Genesis 31:36', 'Genesis', 31, 36, 'یعقوب په قهر شو او د لابان سره یې شخړه وکړه او د هغه څخه یې پوښتنه وکړه: «ما څه جرم کړی دی؟ او کومه خطا مې کړې ده چې راپسې یې؟', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_036.mp3', NULL, 1761758855, 1761758855),
(40407, 'Genesis 31:37', 'Genesis', 31, 37, 'اوس چې تا زما ټول سامان ولټاوه که د خپل کور سامان دې موندلی وي، دلته یې زما د خپلوانو او ستا د خپلوانو په مخکې کېږده او پرېږده چې هغوی دا پرېکړه وکړي چې زمونږ دواړو څخه کوم یو په حقه دی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_037.mp3', NULL, 1761758855, 1761758855),
(40408, 'Genesis 31:38', 'Genesis', 31, 38, 'شل کاله کیږي چې زه ستا سره وم. ستا مېږو او وزو بچي زیان نه کړل او ستا د رمو څخه مې یو پسه هم نه دی خوړلی.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_038.mp3', NULL, 1761758855, 1761758855),
(40409, 'Genesis 31:39', 'Genesis', 31, 39, 'هغه حیوانات چې وحشي ځناورو به داړلي وو، هغه مې نه دي راوړي. د هغوی تاوان مې په خپل ځان منلی دی او هغه چې د ورځې یا به د شپې غلا شوي وو، د هغو بیه به دې زما څخه غوښتله.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_039.mp3', NULL, 1761758855, 1761758855),
(40410, 'Genesis 31:40', 'Genesis', 31, 40, 'دا زما حال ؤ چې د ورځې په ګرمۍ او د شپې په یخنۍ کې به ځورېدلم او خوب مې نه شو کولای.', NULL, NULL, 'OT', 'afghan2023', 'afghan', '[]', 'afghan2023/ot/genesis31_verse_040.mp3', NULL, 1761758855, 1761758855);